def htmllib_unescape(t):
    import html as htmllib
    return htmllib.unescape(t)


def A_walk(xs):
    for x in xs:
        yield x
        yield from A_walk(x.get("children") or [])


def ctr(g):
    """The centre of a node's shape in the Map's SVG: a rounded square or envelope (rect), or a circle."""
    m = re.search(r'<rect class="shape" x="(-?[\d.]+)" y="(-?[\d.]+)" width="([\d.]+)" height="([\d.]+)"', g)
    if m:
        x, y, w, h = (float(v) for v in m.groups())
        return x + w / 2, y + h / 2
    m = re.search(r'<circle class="shape" cx="(-?[\d.]+)" cy="(-?[\d.]+)"', g)
    return float(m.group(1)), float(m.group(2))


def map_logic():
    """Every run under runs/ with workflows.json: every line has a record (source) that exists in the run's files and points producer ->
    consumer; every recorded read between two drawn boxes is a line; every workflow is in exactly one stage's circle or under Not recorded;
    no deliverable sits above one it reads in the Tree; every label comes from its file, its type or its workflow. One row per run."""
    import j2_map as M
    import j2_artifacts as A
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    types = {t["file"]: t["label"] for t in A.load_types()["types"] if "*" not in t["file"]}
    by_type = {t["name"]: t["label"] for t in A.load_types()["types"]}
    rows_out, bad = [], []
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo      # read only: building and drawing a map never writes to a run
    try:
        for name in names:
            d = os.path.join(repo, name)
            rd = lambda f, dflt=None: json.load(open(os.path.join(d, f), encoding="utf-8")) if os.path.isfile(os.path.join(d, f)) else dflt
            wfs = {w["id"]: w for w in rd("workflows.json", []) if isinstance(w, dict) and w.get("id")}
            named = {k: w["id"] for w in wfs.values() for k in (w.get("proposal_id"), w.get("name"), w["id"]) if k}
            plan = {p_.get("name"): p_ for p_ in (((rd("realization.json") or {}).get("plan") or {}).get("workflows") or []) if isinstance(p_, dict)}
            atoms = {a["id"]: a for a in (rd("atoms.json") or {}).get("atoms", [])}
            m = M.build(d)
            by = {n["id"]: n for n in m["nodes"]}
            holds = {}
            for n in m["nodes"]:
                if n["kind"] == "work":
                    for w in n.get("workflows") or []:
                        holds.setdefault(w, set()).add(n["id"])
            def proven(src):      # the record named by an edge is really in the run's files
                f, wid, field, val = src.get("file"), src.get("workflow"), src.get("field"), src.get("value")
                if f == "live run" or not f or not os.path.isfile(os.path.join(d, f)):
                    return False
                if wid and wid not in wfs:
                    return False
                w = wfs.get(wid) or {}
                if f == "workflows.json" and field in ("dependencies", "artifact", "stage", "section", "style_guide"):
                    v = w.get(field)
                    return val in v if isinstance(v, list) else v == val
                if f == "realization.json" and field == "inputs_from":
                    return val in ((plan.get(w.get("proposal_id")) or plan.get(w.get("name")) or {}).get("inputs_from") or [])
                if f == "atoms.json" and field == "depends_on":
                    return any(e.get("atom") == val for a in atoms.values() if a.get("workflow") == wid for e in a.get("depends_on") or [])
                return True      # a whole-file record (goal.json, chat.jsonl, calls.jsonl, audits, artifacts.json, summary.json)
            # the rule: between two artifacts there is always the team that read one and made the other. A read is drawn artifact -> team,
            # what the team made team -> artifact; the Charter (an artifact) goes only to a team.
            kind_of = {n["id"]: n["kind"] for n in m["nodes"]}
            reads_e = [e for e in m["edges"] if e["kind"] in ("step", "handoff") and kind_of.get(e["from"]) == "work"]
            made_e = [e for e in m["edges"] if e["kind"] == "step" and kind_of.get(e["to"]) == "work"]
            art_to_art = sum(1 for e in m["edges"] if e["kind"] in ("step", "handoff") and kind_of.get(e["from"]) == "work" and kind_of.get(e["to"]) == "work")
            read_not_to_team = sum(1 for e in reads_e if kind_of.get(e["to"]) != "engine")
            made_not_from_team = sum(1 for e in made_e if kind_of.get(e["from"]) != "engine")
            no_basis, wrong_way = 0, 0
            team_made = {e["from"]: e["to"] for e in made_e if kind_of.get(e["from"]) == "engine"}
            for e in m["edges"]:
                if e["kind"] not in ("step", "handoff"):
                    continue
                srcs = e.get("sources") or ([e["source"]] if e.get("source") else [])
                if not srcs or not all(proven(x) for x in srcs):
                    no_basis += 1
                    continue
                if kind_of.get(e["from"]) == "work" and kind_of.get(e["to"]) == "engine" and e["from"] != "work:charter":
                    # producer -> consumer: every record names a workflow of this team that read what the artifact holds
                    for src in srcs:
                        read = named.get(src.get("value")) or str(src.get("value")).split(".")[0]
                        if src.get("workflow") not in by[e["to"]].get("workflows", []) or read not in by[e["from"]].get("workflows", []):
                            wrong_way += 1
                elif kind_of.get(e["from"]) == "engine" and kind_of.get(e["to"]) == "work":
                    a_, b_ = set(by[e["from"]].get("workflows", [])), set(by[e["to"]].get("workflows", []))
                    if (a_ or b_) and not a_ & b_:
                        wrong_way += 1
            # every recorded read between two drawn artifacts is a line from the artifact to the team (never to another artifact)
            have = {(e["from"], e["to"]) for e in reads_e if e["from"] != "work:charter"}
            want = set()
            for wid, w in wfs.items():
                p_ = plan.get(w.get("proposal_id")) or plan.get(w.get("name")) or {}
                srcs = [named.get(x) for x in (w.get("dependencies") or []) + (p_.get("inputs_from") or [])]
                srcs += [str(e.get("atom")).split(".")[0] for a in atoms.values() if a.get("workflow") == wid for e in a.get("depends_on") or []]
                for s_ in filter(None, srcs):
                    for a_ in holds.get(s_, ()):
                        for b_ in holds.get(wid, ()):
                            if a_ != b_ and s_ != wid and b_ in team_made.values():
                                want.add((a_, next(k for k, v in team_made.items() if v == b_)))
            missing = len(want - have)
            # the Charter is not given a line to every team: only to a team that reads nothing else
            charter_busy = sum(1 for e in m["edges"] if e["from"] == "work:charter" and e["kind"] == "step" and any(x["to"] == e["to"] and x["from"] != "work:charter" for x in reads_e))
            # the Tree: each workflow in exactly one stage's circle (or listed as not placed); artifacts and teams alternate; no box above one it reads
            t = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "map": m})["tree"]
            circles = [w for n in t["nodes"] if n["kind"] == "stage" for w in n["workflows"]]
            listed = {x for s_ in m["not_recorded"] if s_.startswith("workflows not placed on the map: ") for x in s_.split(": ", 1)[1].split(", ")}
            dropped = sum(1 for w in wfs if circles.count(w) + (w in listed) == 0)
            twice = sum(1 for w in wfs if circles.count(w) + (w in listed) > 1)
            row = {n["id"]: n["row"] for n in t["nodes"]}
            tk = {n["id"]: n["kind"] for n in t["nodes"]}
            side = lambda k: "team" if k == "stage" else "artifact"
            tree_bad = sum(1 for l in t["links"] if side(tk[l["from"]]) == side(tk[l["to"]]))      # artifact to artifact, or team to team
            misplaced = sum(1 for l in t["links"] if not l.get("side") and row[l["to"]] <= row[l["from"]]) + tree_bad      # a side line runs along its own row
            no_basis += sum(1 for n in m["nodes"] for src in (n.get("team_reads") or {}).get("sources", []) if not proven(src))
            # labels: from the file, the file's type, or the workflow (its name, or the field that records it)
            labels = 0
            for n in m["nodes"]:
                if n["kind"] != "work":
                    continue
                ok = {types.get(n.get("file")), M.file_label(n.get("file")) if n.get("file") else None, by_type.get(n["id"].split(":")[1])}
                if not n.get("file"):
                    ok.add(n.get("output"))      # planned, nothing written yet: named by its stage's output
                ok |= {(wfs.get(w) or {}).get("name") for w in n.get("workflows") or []}
                ok |= {M.file_label(f) for w in n.get("workflows") or [] for f, v in (wfs.get(w) or {}).items() if v is True}
                labels += n["label"] not in ok
            rows_out.append((name, len(m["edges"]), no_basis + wrong_way, missing, misplaced, labels, t["crossings"],
                             art_to_art + tree_bad, read_not_to_team, made_not_from_team, dropped, twice, charter_busy))
            if no_basis or wrong_way or missing or misplaced or labels or art_to_art or read_not_to_team or made_not_from_team or dropped or twice or charter_busy:
                bad.append(rows_out[-1])
    finally:
        j2.RUNS_DIR = keep_dir
    cols = ("edges", "artifact->artifact", "read not to a team", "made not from a team", "no basis / wrong way", "missing reads", "workflows dropped",
            "workflows twice", "charter line to a busy team", "misplaced", "labels", "crossings")
    pick = lambda r: (r[1], r[7], r[8], r[9], r[2], r[3], r[10], r[11], r[12], r[4], r[5], r[6])
    if "--map-logic" in sys.argv or bad:
        print(f"{'run':<22}" + "".join(f" {c[:12]:>12}" for c in cols))
        for r in rows_out:
            print(f"{r[0]:<22}" + "".join(f" {v:>12}" for v in pick(r)))
    tot = [sum(pick(r)[i] for r in rows_out) for i in range(len(cols))]
    print("map logic counts over %d runs (all must be 0 except edges and crossings): " % len(rows_out) + " | ".join(f"{c} {v}" for c, v in zip(cols, tot)))
    assert not bad, bad
    print("map logic: no artifact -> artifact line, every read ends at a team and every made line starts at one, every line has a record in the run's "
          "files and points producer -> consumer, no recorded read is missing, every workflow once, the Charter not drawn to a team that reads "
          "something else, nothing below what reads it, every label from its file, type or workflow ok")


def map_readback():
    """An artifact its own team made and other workflows of that team read (team_reads, from the records) sits beside the team on its row
    with a "made" line and a dashed "read back" line, never in the row of the team's plain outputs; an artifact nobody on the team reads
    stays a plain output. Checked on a synthetic run (made-up names) and, from the raw records, on every saved run under runs/."""
    import j2_map as M
    keep_dir, d = j2.RUNS_DIR, tempfile.mkdtemp(prefix="j2-readback-")
    wf = lambda i, stage, art, deps=(): {"id": f"W-{i}", "name": f"zq-{i}", "stage": stage, "artifact": f"artifacts/{art}.md", "status": "done", "dependencies": list(deps)}
    # Ledger Co: W-1 makes ledger, W-2 (same team) reads it and makes report; Brand Co: W-3 makes tone, W-4 (same team) and W-5 (other team) read it
    json.dump([wf(1, "business", "zq-ledger"), wf(2, "business", "zq-report", ["W-1"]), wf(3, "marketing", "zq-tone"),
               wf(4, "marketing", "zq-flyer", ["W-3"]), wf(5, "sales", "zq-pitch", ["W-3"])], open(os.path.join(d, "workflows.json"), "w"))
    json.dump({"goal": "zq"}, open(os.path.join(d, "goal.json"), "w"))      # the Charter every team is given
    for a in ("zq-ledger", "zq-report", "zq-tone", "zq-flyer", "zq-pitch"):
        os.makedirs(os.path.join(d, "artifacts"), exist_ok=True)
        open(os.path.join(d, "artifacts", a + ".md"), "w").write("x")
    def check(m, label):
        tree = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "map": m})["tree"]
        at = {n["id"]: n for n in tree["nodes"]}
        made = {l["to"]: l["from"] for l in tree["links"] if l["kind"] == "made"}
        back = {l["from"]: l for l in tree["links"] if l["kind"] == "back"}
        return tree, at, made, back
    try:
        m = M.build(d)
        lab = {n["label"]: n for n in m["nodes"] if n["kind"] == "work"}
        assert {k for k, n in lab.items() if n.get("team_reads")} == {"Zq ledger", "Zq tone"}, {k: n.get("team_reads") for k, n in lab.items()}
        assert lab["Zq tone"]["team_reads"]["made_by"] == ["W-3"] and lab["Zq tone"]["team_reads"]["read_by"] == ["W-4"], lab["Zq tone"]["team_reads"]
        tree, at, made, back = check(m, "synthetic")
        ids = {n["label"]: n["id"] for n in tree["nodes"]}
        assert set(back) == {ids["Zq ledger"], ids["Zq tone"]}, back
        for a in ("Zq ledger", "Zq tone"):
            n, team = at[ids[a]], at[made[ids[a]]]
            assert n["row"] == team["row"] and n["y"] == team["y"] and n["x"] > team["x"], (a, n, team)      # beside its team, to its right
            assert back[n["id"]]["to"] == team["id"] and back[n["id"]]["side"], back
        assert "made by W-3, read by W-4, same team" in back[ids["Zq tone"]]["tip"] and "made by W-1, read by W-2" in back[ids["Zq ledger"]]["tip"], back
        for a in ("Zq report", "Zq flyer", "Zq pitch"):      # nobody on the team reads it: a plain output one row below its team
            assert ids[a] not in back and at[ids[a]]["row"] == at[made[ids[a]]]["row"] + 1, (a, at[ids[a]])
        assert any(l["from"] == ids["Zq tone"] and l["kind"] == "reads" and at[l["to"]]["label"] == "Sales Lead" for l in tree["links"]), "its normal line to the other team stays"
        assert not any(l["from"] in back and l["to"] in back for l in tree["links"]), "no artifact -> artifact line"
        assert tree["crossings"] == 0, tree["pairs"]
        syn = [n["label"] for n in tree["nodes"] if n["kind"] == "deck"]
    finally:
        j2.RUNS_DIR = keep_dir
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")
    found = {}
    for name in sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []:
        r = os.path.join(repo, name)
        wfs = {w["id"]: w for w in json.load(open(os.path.join(r, "workflows.json"))) if isinstance(w, dict) and w.get("id")}
        named = {k: w["id"] for w in wfs.values() for k in (w.get("proposal_id"), w.get("name"), w["id"]) if k}
        plan = {p_.get("name"): p_ for p_ in (((j2._read(r, "realization.json", None) or {}).get("plan") or {}).get("workflows") or []) if isinstance(p_, dict)}
        atoms = {a["id"]: a for a in (j2._read(r, "atoms.json", None) or {}).get("atoms", [])}
        m = M.build(r)
        tree, at, made, back = check(m, name)
        node = {n["id"]: n for n in m["nodes"]}
        def reads(w):      # the raw records, not the map: what workflow w lists
            p_ = plan.get(wfs[w].get("proposal_id")) or plan.get(wfs[w].get("name")) or {}
            got = [named.get(x) for x in (wfs[w].get("dependencies") or []) + (p_.get("inputs_from") or [])]
            return {x for x in got + [str(e.get("atom")).split(".")[0] for a in atoms.values() if a.get("workflow") == w for e in a.get("depends_on") or []] if x}
        want = {}
        for aid, sid in made.items():
            mk, team = set(node[aid].get("workflows") or []), set(at[sid]["workflows"])
            rd = sorted((w for w in team - mk if reads(w) & mk), key=lambda x: int(x.split("-")[1]))
            if mk and rd:
                want[aid] = rd
        assert set(back) == set(want), (name, set(back) ^ set(want))
        for aid, rd in want.items():
            n, team = at[aid], at[made[aid]]
            assert n["row"] == team["row"] and n["x"] > team["x"] and back[aid]["to"] == team["id"], (name, aid)
            assert f"read by {', '.join(rd)}, same team" in back[aid]["tip"], (name, back[aid]["tip"])
        for aid, sid in made.items():
            assert aid in want or at[aid]["row"] > at[sid]["row"], (name, aid, "a plain output sits below its team")
        if want:
            found[name] = sorted(want)
    print(f"map read-back: synthetic run (beside, loop, normal line to another team, {len(syn)} artifacts, unread ones plain); "
          f"{len(found)} saved runs have a team-read artifact, each drawn beside its team with the loop: " + ", ".join(f"{k} {'+'.join(v)}" for k, v in found.items()))


def map_shapes():
    """The Map's rule and shapes, on every saved run: a read is drawn artifact -> team and what a team made team -> artifact; the Charter has a
    line only to a team that reads nothing else, and a note on its panel says every team reads it; an artifact is a rounded square, an action an
    envelope, a team a circle with a dot cluster, the Charter a circle with a centre dot (Tree, Line and the team's own circle); the status is on
    the outline of every shape; the legend names them; a run waiting on a Requester question is "Waiting on you" in map.json and in the chip."""
    import collections
    import html as htmllib
    import j2_map as M
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    stroke = {"filed": "var(--ok)", "fault": "var(--bad)", "waiting": "var(--validator)", "waiting_on_you": "var(--validator)", "done_unchecked": "var(--validator)",
              "not_made": "var(--line)", "idle": "var(--line)"}
    dash = {"left_open": ' stroke-dasharray="6 4"', "done_unchecked": ' stroke-dasharray="2 3"'}
    seen = collections.Counter()
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo
    try:
        for name in names:
            d = os.path.join(repo, name)
            m = M.build(d)
            by = {n["id"]: n for n in m["nodes"]}
            reads = collections.defaultdict(list)
            for e in m["edges"]:
                if e["kind"] in ("step", "handoff") and by[e["from"]]["kind"] == "work":
                    assert by[e["to"]]["kind"] == "engine", (name, e, "a read ends at a team")
                    reads[e["to"]].append(e["from"])
            for n in m["nodes"]:      # every team has an input: the Charter only when it has no other
                if n["kind"] == "engine" and by.get(n["id"]):
                    others = [a for a in reads[n["id"]] if a != "work:charter"]
                    assert bool(others) != ("work:charter" in reads[n["id"]]), (name, n["id"], reads[n["id"]], "the Charter only to a team that reads nothing else")
            for e in m["edges"]:
                if e["kind"] in ("step", "handoff") and e["from"] != "work:charter" and by[e["from"]]["kind"] == "work":
                    assert e.get("sources") and e["readers"], (name, e, "a read keeps its records and the workflows that read")
            snap = {"workflows": [], "chat": []}
            tree = render_node(snap, docs={"docs": {}, "map": m, "mappin": "work:charter"})["map"]
            if "work:charter" in by:
                assert "Every team reads the charter." in tree, (name, "the Charter's panel says every team reads it")
                assert by["work:charter"]["note"] == "Every team reads the charter."
            svg = tree[tree.index('<svg class="treesvg"'):tree.index("</svg>", tree.index('<svg class="treesvg"'))]
            for mt in re.finditer(r'<g class="tnode (t(?:charter|stage|deck))[ "][^>]*data-id="([^"]+)"[^>]*>(.*?)</g>', svg, re.S):
                kind, nid, body = mt.group(1), htmllib.unescape(mt.group(2)), mt.group(3)
                # the status badge (mapBadge) is a circle with "!" or "?" by design, so the shape of the node itself
                # is read without it: a faulted or waiting box still has to be a rounded square
                body = re.sub(r"<g><circle\b.*$", "", body, flags=re.S)      # the badge's own </g> ends the capture
                n = by.get(nid)
                if kind == "tcharter":
                    assert '<circle class="tdot"' in body and body.count('class="tglyph"') == 1 and "<rect" not in body, (name, "Charter: a circle with a centre dot")
                elif kind == "tstage":
                    assert '<circle class="tdot"' in body and body.count('class="tglyph"') == 5, (name, nid, "team: a circle with a dot cluster")
                elif n and n.get("tag") == "Send":
                    assert '<rect class="tdot"' in body and 'class="tglyphl"' in body and "<circle" not in body, (name, nid, "action: an envelope")
                else:
                    assert re.search(r'<rect class="tdot" x="-[\d.]+" y="-[\d.]+" width="[\d.]+" height="[\d.]+" rx="[\d.]+"', body) and "<circle" not in body, (name, nid, "artifact: a rounded square")
                if n and kind != "tstage":      # the status stays on the outline of every shape
                    st = n["status"]
                    assert f'stroke="{stroke.get(st, "var(--muted)")}"' in body and (dash.get(st, "") in body), (name, nid, st, "status on the outline")
                seen[kind] += 1
            line = render_node(snap, docs={"docs": {}, "map": m, "mapview": "line"})["map"]
            wide = line.split('<svg class="mapsvg mapvert"')[0]
            for mt in re.finditer(r'<g class="mapnode[^"]*" data-id="([^"]+)".*?(?=<g class="mapnode|</svg>)', wide, re.S):
                nid, body = htmllib.unescape(mt.group(1)), mt.group(0)
                n = by.get(nid)
                if not n:
                    continue
                if n["kind"] == "work" and nid == "work:charter":
                    assert '<circle class="shape"' in body and 'class="youdot"' in body, (name, "Line: Charter is a circle with a centre dot")
                elif n["kind"] == "work" and n.get("tag") == "Send":
                    assert '<rect class="shape"' in body and "<path d=\"M" in body and "<polygon" not in body, (name, nid, "Line: an action is an envelope")
                elif n["kind"] == "work":
                    assert re.search(r'<rect class="shape" x="-?[\d.]+" y="-?[\d.]+" width="[\d.]+" height="[\d.]+" rx="[\d.]+"', body) and "<polygon" not in body, (name, nid, "Line: an artifact is a rounded square")
                elif n["kind"] == "engine":
                    assert body.count('class="teamdot"') == 5 and "<polygon" not in body, (name, nid, "Line: a team has the dot cluster")
                seen["line:" + n["kind"]] += 1
            leg = line[line.index('<div class="maplegend"'):]
            leg = leg[:leg.index("</div>")]
            for k, word in (("charter", "Charter (circle, centre dot)"), ("engine", "Team (circle with a dot cluster)"), ("work", "Artifact: a spec, document, site or code (rounded square)"),
                            ("send", "Action: an email or message (letter icon)")):
                drawn = any((x["id"] == "work:charter") if k == "charter" else x["kind"] == "engine" if k == "engine" else x["kind"] == "work" and x["id"] != "work:charter"
                            and (x.get("tag") == "Send") == (k == "send") for x in m["nodes"] if k in ("charter", "engine", "work", "send"))
                assert (word in leg) == drawn, (name, k, "the legend names the shapes the map draws")
            # the state: a run whose last Identity message (a system note after it does not count) still waits on the Requester is "Waiting on you"
            chat = [json.loads(x) for x in open(os.path.join(d, "chat.jsonl"), encoding="utf-8")] if os.path.isfile(os.path.join(d, "chat.jsonl")) else []
            last = next((x for x in reversed(chat) if x.get("who") != "system" and not x.get("meta")), {})
            waiting = bool(last.get("pause") and last.get("who") == "identity")
            assert (m["status"]["state"] == "Waiting on you") == waiting and (by["person:requester"]["status"] == "waiting_on_you") == waiting, (name, m["status"], waiting)
            if waiting:
                assert 'class="mappill' in tree and ">Waiting on you<" in tree, (name, "the chip agrees with map.json")
                seen["waiting"] += 1
    finally:
        j2.RUNS_DIR = keep_dir
    assert seen["tdeck"] and seen["tstage"] and seen["tcharter"] and seen["line:engine"] and seen["line:work"] and seen["waiting"], seen
    print(f"map shapes: {len(names)} runs, a read goes artifact -> team -> artifact, the Charter only to teams with no other input and a note on its panel, "
          f"rounded square / envelope / dot cluster / centre dot in the Tree and the Line with the status on the outline, the legend, a paused run says Waiting on you "
          f"({seen['tdeck']} artifacts, {seen['tstage']} teams drawn in the Tree) ok")


def map_tree():
    """The Map's Tree view (default; "Line" is the metro drawing): Charter, the stages (one per team), their deliverables, a deliverable
    that reads others below them. Same run, same positions; every workflow sits in the tree or its stage's circle; no two labels
    overlap; the crossing count is reported. A clicked stage gets its workflows on a circle round it and the rest fades; Esc returns."""
    import html as htmllib
    import shutil
    import threading
    import j2_map as M
    import j2_server
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")
    names = [n for n in ("j2-20261026-174314", "j2-20261026-155610", "j2-20261027-130930") if os.path.isdir(os.path.join(repo, n))]
    if not names:
        print("map tree: runs 174314, 155610 and 130930 not in runs/, the tree checks on them are skipped")
    report = []
    for name in names:
        if not os.path.exists(os.path.join(j2.RUNS_DIR, name)):
            shutil.copytree(os.path.join(repo, name), os.path.join(j2.RUNS_DIR, name))      # read only: the test's own copy
        mp = M.build(os.path.join(j2.RUNS_DIR, name))
        snap = j2.saved_snapshot(name, 0)
        a, b = render_node(snap, docs={"docs": {}, "map": mp}), render_node(snap, docs={"docs": {}, "map": mp})
        t = a["tree"]
        assert t == b["tree"] and a["map"] == b["map"], f"{name}: the same run draws the same tree"
        assert 'data-view="tree"' in a["map"] and '<svg class="treesvg"' in a["map"] and 'data-mapview="tree" aria-pressed="true"' in a["map"], "Tree is the default"
        rows = {n["id"]: n["row"] for n in t["nodes"]}
        files = {n["id"]: n.get("file") for n in mp["nodes"] if n.get("tag") == "Spec"}
        for n in t["nodes"]:      # a spec is named from its file: artifacts/hint-method.md is "Hint method"
            if n["id"] in files:
                base = os.path.splitext(os.path.basename(files[n["id"]]))[0].replace("-", " ").replace("_", " ")
                assert n["label"] == base[:1].upper() + base[1:], (name, n["id"], n["label"], files[n["id"]])
        if name == "j2-20261026-174314":
            lab = {n["id"]: n["label"] for n in t["nodes"]}
            assert (lab["work:W-1"], lab["work:W-3"], lab["work:W-4"]) == ("Product spec", "Copy guide", "Hint method"), lab
            assert {"Curriculum", "Content plan"} <= {n["sub"].split(" · ")[0] for n in t["nodes"]}, "the stage output stays as the second line"
        if "work:style" in rows:      # style.json is made by a build team that also reads it: no line runs from one artifact to the next
            assert not any({l["from"], l["to"]} == {"work:style", "work:website"} for l in t["links"]), (name, "no artifact -> artifact line")
        kind_ = {n["id"]: n["kind"] for n in t["nodes"]}
        for l in t["links"]:      # artifacts and teams alternate: a read goes from an artifact to a team, a made line from a team to an artifact
            assert (l["kind"], kind_[l["from"]] == "stage", kind_[l["to"]] == "stage") in (("reads", False, True), ("made", True, False), ("plan", False, True), ("back", False, True)), (name, l)
        made, side = {}, {l["from"] for l in t["links"] if l["kind"] == "back"}      # a team-read artifact sits beside its team, not below it
        for l in t["links"]:
            if l["kind"] == "made" and l["to"] not in side:
                made.setdefault(l["from"], []).append(rows[l["to"]])
        assert rows["work:charter"] == 0 and all(n["row"] >= 2 for n in t["nodes"] if n["kind"] == "deck" and n["id"] not in side)
        assert all(rows[s_] == min(r_) - 1 for s_, r_ in made.items()), (name, "each team sits right above the deliverable(s) it made", made, rows)
        for l in t["links"]:
            if l["kind"] == "reads":
                assert rows[l["to"]] > rows[l["from"]], (name, l, "a deliverable sits below every deliverable it reads")
        boxes = [n["box"] for n in t["nodes"]]
        for i in range(len(boxes)):
            for j in range(i + 1, len(boxes)):
                p, q = boxes[i], boxes[j]
                assert p[2] <= q[0] or q[2] <= p[0] or p[3] <= q[1] or q[3] <= p[1], (name, t["nodes"][i]["id"], t["nodes"][j]["id"], "labels overlap")
        same_row = {}
        for n in t["nodes"]:
            same_row.setdefault(n["row"], []).append(n)
        for r in same_row.values():
            r.sort(key=lambda n: n["x"])
            assert all(r[k + 1]["box"][0] - r[k]["box"][2] >= 24 - 0.2 for k in range(len(r) - 1)), (name, "at least 24px between labels")
        # every workflow: in the tree (a deliverable's workflows) or in its team (the team's solar system draws exactly its workflows: graph_map)
        wids = [w["id"] for w in json.load(open(os.path.join(j2.RUNS_DIR, name, "workflows.json"), encoding="utf-8"))]
        stages = [n for n in t["nodes"] if n["kind"] == "stage"]
        placed = {w for n in t["nodes"] for w in n["workflows"]}
        missing = [w for w in wids if w not in placed]
        assert not missing or all(f"workflows not placed on the map: " in x and all(w in x for w in missing) for x in mp["not_recorded"] if "not placed" in x), (name, missing)
        assert not missing, (name, "every workflow is in the tree or its team", missing)
        # the Line toggle: the metro drawing, as before
        ln = render_node(snap, docs={"docs": {}, "map": mp, "mapview": "line"})["map"]
        assert 'data-view="line"' in ln and '<svg class="mapsvg"' in ln and 'data-mapview="line" aria-pressed="true"' in ln
        report.append(f"{name[3:]} {t['crossings']} crossing{'s' if t['crossings'] != 1 else ''}")
    chrome = j2.j2_check.find_chrome()
    if chrome and BROWSER and names:      # the real page at 1440x900: the flow on hover, a stage's circle, one panel inside the map card, Esc, Line
        ui = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "j2_ui.html"), encoding="utf-8").read()
        name = names[0]

        def probe(js, flags=()):
            tmp = tempfile.mkdtemp(prefix="j2-tree-")
            open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(ui.replace("</body>", "<script>setTimeout(() => { try { " + js + " } catch (e) { document.body.setAttribute('data-r', JSON.stringify({error: String(e.stack || e)})); } }, 2500)</script></body>"))
            keep_here, j2_server.HERE = j2_server.HERE, tmp
            srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            try:
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", "--window-size=1440,900", "--virtual-time-budget=10000", *flags, "--dump-dom",
                                  f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={name}"], capture_output=True, text=True, timeout=180).stdout
            finally:
                j2_server.HERE = keep_here
                srv.shutdown()
            got = json.loads(htmllib.unescape(re.search(r'data-r="([^"]*)"', dom).group(1)))
            assert "error" not in got, got
            return got
        base = ("const q = s => [...document.querySelectorAll(s)], r = {}, ev = (el, t, rel) => el.dispatchEvent(new MouseEvent(t, {bubbles: true, relatedTarget: rel || null})),"
                " vis = el => getComputedStyle(el).display !== 'none', touching = id => q('.tedge').filter(e => vis(e) && (e.dataset.from === id || e.dataset.to === id)),"
                " busiest = q('.tnodes > .tnode.tdeck').sort((a, b) => touching(b.dataset.id).length - touching(a.dataset.id).length)[0], hid = busiest.dataset.id;")
        js = (base + "const st = q('.tnode.tstage').sort((a, b) => b.querySelectorAll('*').length - a.querySelectorAll('*').length || +b.dataset.x - +a.dataset.x)[0], id = st.dataset.id; r.id = id;"
              "const s0 = document.querySelector('.treesvg').getBoundingClientRect(); r.fits = [s0.bottom <= innerHeight, s0.top >= 0, document.documentElement.scrollHeight <= innerHeight + 1];"
              "r.d3 = typeof d3; r.tree = getComputedStyle(document.querySelector('.treesvg')).display; r.line = getComputedStyle(document.querySelector('.mapsvg:not(.mapvert)')).display;"
              "r.rest = q('.tflow').length; r.hid = hid; ev(busiest, 'mouseover');"
              "r.flow = q('.tflow').map(c => [c.dataset.from, c.dataset.to, c.classList.contains('fin'), c.querySelector('animateMotion').getAttribute('path'), c.querySelector('animateMotion').getAttribute('dur')]);"
              "r.edges = touching(hid).map(e => [e.dataset.from, e.dataset.to, e.getAttribute('d'), e.classList.contains('hot')]); ev(busiest, 'mouseout'); r.after0 = q('.tflow').length;"
              "r.zInit = TREE.zoom; ev(st, 'click');"
              "setTimeout(() => { r.tfocus = [q('.treesvg.tfocused').length, q('.tpill').length, q('[data-treeopen]').length, q('#pane-map .mappanel').map(x => x.dataset.stagepanel || ''), q('.consvg').length]; r.tback = !document.querySelector('[data-treeback]').hidden;"
              " ev(q('[data-treeopen]')[0], 'click'); setTimeout(() => { const c = document.querySelector('.consvg');"
              " r.team = [c.dataset.kind, c.dataset.cons, q('.consvg .cnode.k-wf').length, q('.consvg .cnode.k-centre').length]; const w = q('.consvg .cnode.k-wf').sort((a, b) => b.dataset.cid.localeCompare(a.dataset.cid))[0]; r.wid = w.dataset.cid;"
              " ev(w, 'click'); setTimeout(() => { const box = r_ => { const b = r_.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom]; };"
              " r.lit = [q('.consvg.focusing').length, q('.consvg .cline.lit').length, q('.conspanel').length]; r.pb = box(document.querySelector('.conspanel')); r.card = box(document.querySelector('.consbox')); r.chat = box(document.querySelector('#dview .chat')); r.needs = box(document.getElementById('needs'));"
              " ev(q('.consvg .cnode.k-wf').find(x => x.dataset.cid === r.wid), 'click'); setTimeout(() => { const s2 = document.querySelector('.consvg'); r.wfsun = [s2.dataset.kind, s2.dataset.cons];"
              " document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); setTimeout(() => { r.esc1 = [document.querySelector('.consvg').dataset.kind];"
              " document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); setTimeout(() => { r.esc2 = [q('.consvg').length, q('.treesvg.tfocused').length];"
              " document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); setTimeout(() => { r.z0 = TREE.zoom; const h = q('.tnode.tstage').find(x => x.dataset.id === id);"
              "  r.after = [q('.treesvg.tfocused').length, q('.tdim').length, h.getAttribute('transform') === 'translate(' + h.dataset.x + ',' + h.dataset.y + ')', q('#pane-map .mappanel').length];"
              "  ev(q('.tnodes > .tnode.tdeck')[0], 'click'); r.second = q('#pane-map .mappanel').map(x => x.dataset.panel || x.dataset.stagepanel).concat(q('.consvg').map(x => x.dataset.cons)); consBack();      /* an artifact opens its constellation, no other panel */"
              "  document.querySelector('[data-mapview=line]').click(); r.line2 = [...document.querySelectorAll('.mapsvg')].some(x => getComputedStyle(x).display !== 'none') ? 'block' : 'none'; r.tree2 = getComputedStyle(document.querySelector('.treebox')).display;"
              "  r.z = r.z0; document.querySelector('[data-mapview=tree]').click(); document.body.setAttribute('data-r', JSON.stringify(r)); }, 900); }, 900); }, 900); }, 900); }, 700); }, 900); }, 900);")
        got = probe(js)
        assert got["d3"] == "object" and got["tree"] == "block" and got["line"] == "none", got
        assert got["fits"] == [True, True, True], ("the whole tree fits 1440x900 at load, no scrolling", got)
        # the flow: nothing moves at rest; on hover one dot per lit line, along the line's own path (producer -> consumer), about 1.5 s,
        # "reads" (into the node) and "read by" (out of it) told apart; leaving the node stops it
        assert got["rest"] == 0 and got["after0"] == 0, got
        lines = {(a, b): (d, hot) for a, b, d, hot in got["edges"]}
        assert got["flow"] and len(got["flow"]) == len(lines) and all(h for _, h in lines.values()), got
        for a, b, fin, path, dur in got["flow"]:
            assert (a, b) in lines and path == lines[(a, b)][0] and fin == (b == got["hid"]) and dur == "1.5s", (a, b, fin, got["hid"])
        assert {f[2] for f in got["flow"]} == {True, False} or len(got["flow"]) == 1, "lines in and lines out, when it has both"
        # a team: clicking it focuses it (its panel has the button that opens it); opened, it is a solar system of what it made with its workflows round it (no team
        # node); a workflow clicked lights what it read with its panel inside the map card, clicked again it is the sun; Esc steps back to the team, the focus, the Tree
        meets = lambda a, b: a[0] < b[2] and b[0] < a[2] and a[1] < b[3] and b[1] < a[3]
        assert got["tfocus"][:3] == [1, 1, 1] and got["tfocus"][3] == [got["id"]] and got["tfocus"][4] == 0 and got["tback"], got
        assert got["team"][0] == "team" and got["team"][1] == got["id"] and got["team"][2] > 0 and got["team"][3] == 1, ("the open team", got["team"])
        pb, card, chat, needs = got["pb"], got["card"], got["chat"], got["needs"]
        inside = pb[0] >= card[0] - 0.5 and pb[1] >= card[1] - 0.5 and pb[2] <= card[2] + 0.5 and pb[3] <= card[3] + 0.5
        assert got["lit"][0] == 1 and got["lit"][2] == 1 and inside and not meets(pb, chat) and not meets(pb, needs) and pb[3] <= 900, ("a workflow lights what it read, its panel in the card", got["lit"], pb, card)
        assert got["wfsun"] == ["wf", got["wid"]] and got["esc1"] == ["team"] and got["esc2"] == [0, 1], ("again: its sun; Esc: the team, then the focus", got)
        assert got["after"] == [0, 0, True, 0] and got["z"] == got["zInit"], ("Esc closes the focus; the view is back where it was", got["after"], got["z"], got["zInit"])
        assert len(got["second"]) == 1 and got["second"][0].startswith("work:"), ("an artifact opens its own sun, no other panel", got)
        assert got["line2"] != "none" and got["tree2"] == "none", "the Line toggle shows the metro map"
        # reduced motion: no dots, small arrowheads on the lit lines instead
        rm = probe(base + "ev(busiest, 'mouseover'); r.rm = [q('.tflow').length, touching(hid).filter(e => e.getAttribute('marker-end')).length, touching(hid).length];"
                   "document.body.setAttribute('data-r', JSON.stringify(r));", ("--force-prefers-reduced-motion",))
        assert rm["rm"][0] == 0 and rm["rm"][1] == rm["rm"][2] > 0, ("reduced motion: arrowheads, nothing moves", rm)
    print("map tree: Charter, stages, deliverables below what they read; the same run draws the same; every workflow in the tree or its team; "
          "no labels overlap, 24px apart; a team focused, opened as its solar system, a workflow lit then its sun, Esc steps back; "
          "Line shows the metro map ok (" + ", ".join(report) + ")")


def arc_points(d, n=40):
    """The points of an edge path, which must be exactly one straight line (M x y L x y), one circular arc (M x y A r r 0 f s x y) or one cubic bend
    (M x y C x y x y x y, as the page draws every edge): any other command fails."""
    import math
    num = r"-?[\d.]+"
    assert re.fullmatch(rf"M{num} {num} (L{num} {num}|A[\d.]+ [\d.]+ 0 [01] [01] {num} {num}|C{num} {num} {num} {num} {num} {num})", d), ("an edge is a line, one arc or one cubic bend", d)
    v = [float(x) for x in re.findall(r"-?[\d.]+", d)]
    if "C" in d:
        return [tuple((1 - u) ** 3 * v[k] + 3 * (1 - u) ** 2 * u * v[k + 2] + 3 * (1 - u) * u * u * v[k + 4] + u ** 3 * v[k + 6] for k in (0, 1)) for u in (i / n for i in range(n + 1))]
    if "L" in d:
        return [(v[0] + (v[2] - v[0]) * i / n, v[1] + (v[3] - v[1]) * i / n) for i in range(n + 1)]
    x1, y1, rx, ry, _, fa, fs, x2, y2 = v
    dx, dy = (x1 - x2) / 2, (y1 - y2) / 2
    coef = (-1 if fa == fs else 1) * math.sqrt(max(0, (rx * rx * ry * ry - rx * rx * dy * dy - ry * ry * dx * dx) / (rx * rx * dy * dy + ry * ry * dx * dx)))
    cx, cy = coef * rx * dy / ry + (x1 + x2) / 2, -coef * ry * dx / rx + (y1 + y2) / 2
    a0, da = math.atan2(y1 - cy, x1 - cx), math.atan2(y2 - cy, x2 - cx) - math.atan2(y1 - cy, x1 - cx)
    if fs and da <= 0:
        da += 2 * math.pi
    if not fs and da >= 0:
        da -= 2 * math.pi
    return [(cx + rx * math.cos(a0 + da * i / n), cy + ry * math.sin(a0 + da * i / n)) for i in range(n + 1)]


def map_focus():
    """Map, focus at every level (Tree: a team; a team's circle: a workflow), on every saved run. Browser-free: the Tree itself, every team focused, every
    team opened and every workflow focused: all recorded inputs and outputs are labelled shapes (a read of a workflow with no deliverable is marked as such),
    the nodes directly connected to the focus beside it, no shape or label overlaps another or leaves the canvas, every edge is one straight line or one
    circular arc (any other path command fails) and none passes through a shape or a label, the same run draws the same. With Chrome (--browser): runs 174314
    and 155610 on the real page: a team focused, opened, W-8 focused, another workflow, with Esc, Back, a second click and empty space returning, the nodes
    gliding (and sitting at once with reduced motion)."""
    import collections
    import html as htmllib
    import shutil
    import threading
    import j2_map as M
    import j2_server
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    meets = lambda a, b: a[0] < b[2] and b[0] < a[2] and a[1] < b[3] and b[1] < a[3]
    hit = lambda pts, b: any(b[0] + 1 < x < b[2] - 1 and b[1] + 1 < y < b[3] - 1 for x, y in pts)
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo
    seen = collections.Counter()
    try:
        for name in names:
            m = M.build(os.path.join(repo, name))
            snap = {"workflows": [], "chat": []}
            a = render_node(snap, docs={"docs": {}, "map": m, "focusall": True})
            b = render_node(snap, docs={"docs": {}, "map": m, "focusall": True})
            assert a["focusall"] == b["focusall"] and a["tree"] == b["tree"], (name, "the same run draws the same")
            t, fa = a["tree"], a["focusall"]
            by = {n["id"]: n for n in t["nodes"]}
            # the Tree: every edge a line or one arc, none through a shape or a label, no two crossing; labels apart
            for l in t["links"]:
                pts = arc_points(l["d"])
                assert l["clear"], (name, l["from"], l["to"], "the Tree left an edge across a node")
                for n in t["nodes"]:
                    r = n["r"] * (1.2 if n.get("tag") == "Send" else 1)
                    boxes = ([] if n["id"] in (l["from"], l["to"]) else [[n["x"] - r, n["y"] - n["r"], n["x"] + r, n["y"] + n["r"]]]) + [n["box"]]
                    assert not any(hit(pts, bx) for bx in boxes), (name, l["from"], l["to"], n["id"], "an edge runs through a shape or a label in the Tree")
                seen["tree edges"] += 1
            assert t["crossings"] == 0 and t["W"] > 0, (name, t["pairs"])
            flows = {w["id"]: w for w in m["workflows"]}
            stages = {n["id"]: n for n in t["nodes"] if n["kind"] == "stage"}
            assert set(fa["stages"]) == set(stages) and all(fa["stages"].values()), (name, "focus data for every team")
            io = {sid: ([l["from"] for l in t["links"] if l["to"] == sid and l["kind"] in ("reads", "plan")], [l["to"] for l in t["links"] if l["from"] == sid and l["kind"] == "made"]) for sid in stages}
            made_by = {l["to"]: l["from"] for l in t["links"] if l["kind"] == "made"}

            def geometry(F, what):
                nodes = {n["id"]: n for n in F["nodes"]}
                boxes = [(n["id"], n["box"]) for n in F["nodes"]] + [(o["id"], [o["x"] - o["r"], o["y"] - o["r"], o["x"] + o["r"], o["y"] + o["r"]]) for o in F["others"]]
                for n in F["nodes"]:
                    assert n["label"].strip() and n["lbox"][2] > n["lbox"][0] and n["status"] is not None, (name, what, n["id"], "labelled, with a status")
                for i in range(len(boxes)):
                    assert boxes[i][1][0] >= 0 and boxes[i][1][1] >= 0 and boxes[i][1][2] <= F["W"] and boxes[i][1][3] <= F["H"], (name, what, boxes[i][0], "inside the canvas")
                    for j in range(i + 1, len(boxes)):
                        assert not meets(boxes[i][1], boxes[j][1]), (name, what, boxes[i][0], boxes[j][0], "shapes or labels overlap")
                for e in F["edges"]:
                    pts = arc_points(e["d"])
                    assert {e["from"], e["to"]} <= set(nodes), (name, what, e)
                    assert (nodes[e["from"]]["kind"] == "stage") != (nodes[e["to"]]["kind"] == "stage"), (name, what, e["from"], e["to"], "a team-team or artifact-artifact line")
                    for id_, bx in boxes:
                        if id_ in (e["from"], e["to"]):
                            if nodes[id_]["role"] == "focus":
                                continue
                            bx = nodes[id_]["lbox"]
                        assert not hit(pts, bx), (name, what, e["from"], e["to"], id_, "an edge runs through a shape or a label")
                    seen["focus edges"] += 1
                return nodes

            sid0 = sorted(stages)[0]      # a focused team's panel has one open button (a second click on the team does the same), no second link
            pm = render_node(snap, docs={"docs": {}, "map": m, "tree": {"focus": sid0}})["map"]
            assert pm.count("data-treeopen=") == 1 and "Open these workflows" not in pm and "Open its workflows" in pm, (name, sid0, "one open button")
            for sid, F in fa["stages"].items():      # a team focused in the Tree: its makers, what it reads, it, what it made, its readers
                nodes = geometry(F, "team " + sid)
                ins, outs = io[sid]
                role = lambda *r: {n["id"] for n in F["nodes"] if n["role"] in r}
                assert set(ins) == role("in") and set(outs) == role("out"), (name, sid, "a team's inputs and outputs")
                makers = {made_by[a] for a in ins if made_by.get(a) not in (None, sid)}
                readers = {l["to"] for l in t["links"] if l["kind"] == "reads" and l["from"] in outs and l["to"] != sid}
                assert role("maker", "peer", "reader") == makers | readers, (name, sid, "the teams beside it: makers of its inputs and readers of its outputs")
                want = ({(a, sid) for a in ins} | {(sid, a) for a in outs} | {(made_by[a], a) for a in ins if made_by.get(a) in makers}
                        | {(a, r) for a in outs for r in readers if any(l["kind"] == "reads" and l["from"] == a and l["to"] == r for l in t["links"])})
                assert {(e["from"], e["to"]) for e in F["edges"]} == want, (name, sid, "every line is a team making an artifact or reading one")
                assert nodes[sid]["role"] == "focus" and (nodes[sid]["label"] == by[sid]["label"]), (name, sid)
                seen["teams"] += 1
            seen["runs"] += 1
        # the drawn page: the team and the workflow of run 174314, and the picture a focus leaves behind when Esc is pressed
        name = "j2-20261026-174314"
        if name in names:
            m = M.build(os.path.join(repo, name))
            snap = {"workflows": [], "chat": []}
            base = render_node(snap, docs={"docs": {}, "map": m})
            st = next(n for n in base["tree"]["nodes"] if n["kind"] == "stage" and "W-8" in n["workflows"])
            for state, label in (({"focus": st["id"]}, "team"),):
                o = render_node(snap, docs={"docs": {}, "map": m, "tree": state})
                svg = o["map"][o["map"].index('<svg class="treesvg'):o["map"].index("</svg>", o["map"].index('<svg class="treesvg'))]
                F = o["tree"]["focus"]
                assert 'class="treesvg tfocused"' in svg and f'viewBox="0 0 {F["W"]} {F["H"]}"' in svg and svg.count('class="tedge fedge') == len(F["edges"]), (name, label)
                for n in F["nodes"]:
                    assert htmllib.escape(n["label"]) in svg or n["label"] in svg, (name, label, n["label"], "labelled on the page")
                assert svg.count("tdim thide") >= len(F["others"]), (name, label, "everything else fades")
                for n in F["nodes"]:      # an action is an envelope, an artifact a rounded square, with the status on the outline
                    if n["role"] in ("in", "out"):
                        g_ = re.search(r'<g class="tnode [^"]*" data-id="%s".*?</g>' % re.escape(htmllib.escape(n["id"])), svg, re.S).group(0)
                        send = next((x for x in base["tree"]["nodes"] if x["id"] == n["id"]), {}).get("tag") == "Send"
                        assert ("tglyphl" in g_) == send and ('<rect class="tdot"' in g_) and "stroke=" in g_, (name, label, n["id"], "action: envelope, artifact: square, status on the outline")
            plain = render_node(snap, docs={"docs": {}, "map": m})["map"]
            for state in ({"focus": ""},):
                assert render_node(snap, docs={"docs": {}, "map": m, "tree": state})["map"] == plain, (name, "with nothing focused the Tree is drawn as before")
    finally:
        j2.RUNS_DIR = keep_dir
    chrome = j2.j2_check.find_chrome()
    if chrome and BROWSER and names:
        ui = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "j2_ui.html"), encoding="utf-8").read()

        def probe(name, js, flags=()):
            tmp = tempfile.mkdtemp(prefix="j2-focus-")
            open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(ui.replace("</body>", "<script>window.onerror = (m, u, l, c, e) => document.body.setAttribute('data-r', JSON.stringify({error: String(m) + ' ' + (e && e.stack || '')})); setTimeout(() => { try { " + js + " } catch (e) { document.body.setAttribute('data-r', JSON.stringify({error: String(e.stack || e)})); } }, 2500)</script></body>"))
            keep_here, j2_server.HERE = j2_server.HERE, tmp
            srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            try:
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", "--window-size=1440,900", "--virtual-time-budget=40000", *flags, "--dump-dom",
                                  f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={name}"], capture_output=True, text=True, timeout=240).stdout
            finally:
                j2_server.HERE = keep_here
                srv.shutdown()
            hit_ = re.search(r'data-r="([^"]*)"', dom)
            assert hit_, ("the page did not finish its steps", dom[-300:])
            got = json.loads(htmllib.unescape(hit_.group(1)))
            assert "error" not in got, got
            return got
        base = ("const q = s => [...document.querySelectorAll(s)], r = {}, ev = (el, t) => el.dispatchEvent(new MouseEvent(t, {bubbles: true})), vis = el => getComputedStyle(el).display !== 'none', esc = () => document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})),"
                " rc = el => { const b = el.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom]; }, stage = () => q('.tnode.tstage').find(x => (MAPTREE.nodes.find(n => n.id === x.dataset.id) || {workflows: []}).workflows.includes('W-8')),"
                " pos = () => Object.fromEntries(q('[data-k]').map(e => [e.dataset.k, [+e.dataset.ax, +e.dataset.ay]])), w8 = () => q('.tring .twf').find(x => x.dataset.wf === 'W-8'), t_ = v => Math.round(v * 10) / 10,"
                " settled = () => q('[data-k]').every(e => e.getAttribute('transform') === 'translate(' + t_(+e.dataset.ax) + ',' + t_(+e.dataset.ay) + ')'), same = ref => { const p = pos(); return Object.keys(ref).every(k => p[k] && Math.abs(p[k][0] - ref[k][0]) < 0.2 && Math.abs(p[k][1] - ref[k][1]) < 0.2) && settled(); },"
                " snap = k => { const nodes = q('.treesvg .tnode').filter(vis), items = nodes.map(n => ({id: n.dataset.wf || n.dataset.id, dot: rc(n.querySelector('.tdot')), texts: [...n.querySelectorAll('text')].filter(vis).map(rc)}));"
                " r[k] = {items, vb: q('.treesvg')[0].getAttribute('viewBox'), data: [q('.treesvg')[0].dataset.w, q('.treesvg')[0].dataset.h], moving: q('.treesvg.tmoving').length, settled: settled(), faded: q('.tnode.thide').length, words: q('.tnode.thide .tlab').filter(vis).length, panel: q('.treepanel').length,"
                " edges: q('.fedge').filter(vis).map(e => { const L = e.getTotalLength(), m = e.getScreenCTM(), pts = []; for (let i = 0; i <= 60; i++){ const p = e.getPointAtLength(L * i / 60); pts.push([m.a * p.x + m.c * p.y + m.e, m.b * p.x + m.d * p.y + m.f]); } return {from: e.dataset.from, to: e.dataset.to, d: e.getAttribute('d'), pts}; })}; };"
                " const steps = [], go = fs => { let i = 0; const run = () => { if (i >= fs.length){ document.body.setAttribute('data-r', JSON.stringify(r)); return; } fs[i++](); setTimeout(run, 1000); }; run(); };")      # each step after the spring has landed
        for name in ("j2-20261026-174314", "j2-20261026-155610"):
            if name not in names:
                continue
            if not os.path.exists(os.path.join(j2.RUNS_DIR, name)):
                shutil.copytree(os.path.join(repo, name), os.path.join(j2.RUNS_DIR, name))      # read only: the test's own copy
            js = (base + "go(["
                  "() => { r.tree0 = pos(); r.treeEdges = q('.tedge').filter(vis).map(e => e.getAttribute('d')); ev(stage(), 'click'); },"
                  "() => { r.teamFlags = [q('.treesvg.tfocused').length, q('.tpill').length, q('[data-treeopen]').length, q('.tflow').length, q('.treepanel a, .treepanel [data-mapgo]').length]; r.teamPanelText = q('.treepanel')[0].textContent; snap('team'); ev(q('.tpill')[0], 'click'); },"
                  "() => { const c = q('.consvg')[0]; r.opened = [c ? c.dataset.kind : '', c ? c.dataset.cons : '', stage() ? 1 : 0, q('.consvg .cnode.k-wf').length]; ev(q('[data-consback]')[0], 'click'); },"
                  "() => { r.backFromTeam = [q('.consvg').length, q('.treesvg.tfocused').length]; esc(); },"
                  "() => { r.escTeam = [q('.treesvg.tfocused').length, same(r.tree0)]; ev(stage(), 'click'); },"
                  "() => { ev(q('[data-treeback]')[0], 'click'); },"
                  "() => { r.backTeam = [q('.treesvg.tfocused').length, same(r.tree0)]; ev(stage(), 'click'); },"
                  "() => { ev(q('.treesvg')[0], 'click'); },"
                  "() => { r.emptyTeam = [q('.treesvg.tfocused').length, same(r.tree0)]; }"
                  "]);")
            got = probe(name, js)
            team = next(n for n in M.build(os.path.join(repo, name))["nodes"] if n["kind"] == "engine" and "W-8" in (n.get("workflows") or []))
            assert all(re.fullmatch(r"M[-\d. ]+ C[-\d. ]+", d) for d in got["treeEdges"]), (name, "the Tree's edges on the page are one cubic bend each")
            assert got["teamFlags"][:3] == [1, 1, 1] and got["teamFlags"][4] == 0 and got["teamPanelText"].count("Open") == 1 and "Open these workflows" not in got["teamPanelText"], (name, "a team is focused by a click; its panel has one open button", got["teamFlags"], got["teamPanelText"])
            assert got["opened"][0] == "team" and got["opened"][2] == 0 and got["opened"][3] > 0, (name, "a second click on the focused team opens its solar system", got["opened"])
            assert got["backFromTeam"] == [0, 1], (name, "Back from the team returns to the team focused in the Tree", got["backFromTeam"])
            assert got["escTeam"] == [0, True] and got["backTeam"] == [0, True] and got["emptyTeam"] == [0, True], (name, "Esc, Back and empty space bring the Tree back", got["escTeam"], got["backTeam"], got["emptyTeam"])
            for state in ("team",):
                s_ = got[state]
                assert s_["settled"] and s_["moving"] == 0 and s_["vb"] == f"0 0 {s_['data'][0]} {s_['data'][1]}" and s_["faded"] > 0 and s_["words"] == 0 and s_["panel"] == 1, (name, state, "the nodes land on the drawing, the rest fades without words, one panel")
                rects = [(it["id"], k, r_) for it in s_["items"] for k, r_ in [("dot", it["dot"])] + [("text", t_) for t_ in it["texts"]]]
                for i in range(len(rects)):
                    for j in range(i + 1, len(rects)):
                        if rects[i][0] != rects[j][0]:
                            assert not meets(rects[i][2], rects[j][2]), (name, state, "on the page, shapes or labels overlap", rects[i][:2], rects[j][:2])
                assert s_["edges"], (name, state)
                for e in s_["edges"]:
                    arc_points(e["d"])
                    for it in s_["items"]:
                        for k, bx in [("dot", it["dot"])] + [("text", t_) for t_ in it["texts"]]:
                            if it["id"] in (e["from"], e["to"]) and k == "dot":
                                continue
                            assert not hit(e["pts"], bx), (name, state, e["from"], e["to"], it["id"], k, "on the page, an edge runs through a shape or a label")
            seen["browser"] += 1
        # reduced motion: no animation, the same layout at once
        name = "j2-20261026-174314"
        if name in names:
            rm = probe(name, base + "ev(stage(), 'click'); r.a = [q('.treesvg.tmoving').length, q('.treesvg.tfocused').length, settled()]; ev(q('[data-treeopen]')[0], 'click'); r.b = [q('.consvg.cmoving').length, q('.consvg[data-kind=team]').length, 1, 1];"
                       " document.body.setAttribute('data-r', JSON.stringify(r));", ("--force-prefers-reduced-motion",))
            assert rm["a"] == [0, 1, True] and rm["b"] == [0, 1, True, True], ("reduced motion: the layout is there at once", rm)
    print(f"map focus: {seen['runs']} runs: every edge of the Tree ({seen['tree edges']}) and of {seen['teams']} focused teams ({seen['focus edges']} edges) is one line or one arc, none through a shape or a label, "
          "no overlaps, every line a team making or reading an artifact (no team-team line): makers of its inputs above them, readers of its outputs below them; same run, same picture"
          + (f"; real page, {seen['browser']} runs: team focus, a second click opens the team's solar system, Back returns to the focus, Esc / Back / empty space return, reduced motion sits at once" if seen.get("browser") else "") + " ok")


def map_line():
    """Map, Line view, on every saved run, on the real page (--browser; skipped without Chrome): on open the drawing fits the card (content box inside it
    with a margin and filling at least 85% of one side) but never with a label under 11px (then it is held at 11px and the side that overflows pans, from
    the margin); no horizontal page scroll; the legend and Not recorded list sit in a collapsed overlay chip in the card corner that covers nothing at fit and
    remembers its state; + and - stay between 0.25x and 4x of the fit; Fit after a wheel zoom and a pan gives back the very same transform, twice; a click on a
    dot (and Esc) keeps the transform; a narrower card refits (and picks the tall drawing when the wide one would have labels under 11px)."""
    import threading
    import html as htmllib
    import j2_server
    chrome = j2.j2_check.find_chrome()
    here = os.path.dirname(os.path.abspath(__file__))
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    if not (chrome and BROWSER and names):
        print("map line: skipped (Chrome not found, or --fast without --browser)")
        return
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    # the first fit may precede the last font metrics by a fraction of a pixel, so Fit (after a short wait) is the reference transform
    js = ("(async () => { const names = %s, out = {}, wait = ms => new Promise(r => setTimeout(r, ms)), q = s => [...document.querySelectorAll(s)], tr = s => s.querySelector('.lview').getAttribute('transform'),"
          " cur = () => q('.mapsvgwrap[data-view=line] .mapsvg').find(x => x.clientWidth), click = el => el.dispatchEvent(new MouseEvent('click', {bubbles: true}));"
          " const rc = el => { const b = el.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom]; }, measure = s => { const g = s.querySelector('.lview'), c = s.getBoundingClientRect(), b = g.getBoundingClientRect(); return {fit: s.dataset.fit, font: +s.dataset.fontpx, rel: +s.dataset.rel, card: [c.left, c.top, c.right, c.bottom], box: [b.left, b.top, b.right, b.bottom], layout: s.closest('.mapsvgwrap').dataset.layout, sw: document.documentElement.scrollWidth, iw: innerWidth, ih: innerHeight, k: +s.dataset.k, chip: rc(q('.maplay')[0]), nodes: [...s.querySelectorAll('.mapnode')].map(rc)}; };"
          " for (const name of names){ try { const m = await (await fetch('/api/map?run=' + name, {cache: 'no-store'})).json(); for (const k of Object.keys(MAP)) delete MAP[k]; Object.assign(MAP, m); MAPPIN = ''; LINE.zoom = {}; paintMap();"
          "   const s = cur(), r = {nodes: (m.nodes || []).length, edges: (m.edges || []).length}; if (!s){ out[name] = {error: 'no line drawing'}; continue; }"
          "   r.fit0 = measure(s); await wait(100); click(q('[data-linefit]')[0]); r.t0 = tr(s);"
          "   const c = s.getBoundingClientRect(); s.dispatchEvent(new WheelEvent('wheel', {deltaY: -400, clientX: c.left + c.width / 2, clientY: c.top + c.height / 2, bubbles: true, cancelable: true})); r.wheel = +s.dataset.rel;"
          "   s.__zoom_b.translateBy(d3.select(s), 40, -30); r.moved = tr(s) !== r.t0; click(q('[data-linefit]')[0]); r.fit1 = tr(s) === r.t0;"
          "   click(q('[data-linezoom]')[0]); r.plus = +s.dataset.rel; for (let i = 0; i < 12; i++) click(q('[data-linezoom]')[0]); r.max = +s.dataset.rel; for (let i = 0; i < 30; i++) click(q('[data-linezoom]')[1]); r.min = +s.dataset.rel;"
          "   click(q('[data-linefit]')[0]); r.fit2 = tr(s) === r.t0; s.__zoom_b.scaleBy(d3.select(s), 2); const t2 = tr(s), z2 = +s.dataset.rel;"
          "   const id = q('.mapsvg .mapnode').find(x => x.closest('.mapsvg') === s).dataset.id; mapSelect(id); r.keep = [tr(cur()) === t2, +cur().dataset.rel === z2, q('.mappanel').length]; document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); r.esc = [tr(cur()) === t2, q('.mappanel').length]; click(q('[data-linefit]')[0]);"
          "   if (name === names[0] || m.nodes.length > 0){ const w = q('.mapsvgwrap[data-view=line]')[0], w0 = w.clientWidth; /* the resize observer calls the same lineMount(true) */ w.style.width = '560px'; lineMount(true); const s2 = cur(); r.narrow = measure(s2); w.style.width = ''; lineMount(true); r.back = [measure(cur()).layout, tr(cur()) === r.t0, w.clientWidth === w0, !!w.__ro]; }"
          "   const d = q('.maplay')[0]; r.lay0 = [d.open, localStorage.getItem('j2maplay')]; d.open = true; await wait(60); r.lay1 = [MAPLAY, localStorage.getItem('j2maplay')]; paintMap(); r.lay2 = q('.maplay')[0].open; q('.maplay')[0].open = false; await wait(60); r.lay3 = [MAPLAY, localStorage.getItem('j2maplay'), q('.maplay')[0].open, q('.legnarrow').length];"
          "   out[name] = r; } catch (e) { out[name] = {error: String(e.stack || e)}; } }"
          " document.body.setAttribute('data-r', JSON.stringify(out)); })()") % json.dumps(names)
    tmp = tempfile.mkdtemp(prefix="j2-line-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(ui.replace("</body>", "<script>setTimeout(() => { " + js + " }, 2500)</script></body>"))
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    keep_dir, keep_here, j2.RUNS_DIR, j2_server.HERE = j2.RUNS_DIR, j2_server.HERE, repo, tmp
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    try:
        dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", "--window-size=1440,900", "--virtual-time-budget=600000", "--dump-dom",
                          f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&mapview=line&run={names[0]}"], capture_output=True, text=True, timeout=590).stdout
    finally:
        j2.RUNS_DIR, j2_server.HERE = keep_dir, keep_here
        srv.shutdown()
    hit_ = re.search(r'data-r="([^"]*)"', dom)
    assert hit_, ("the page did not finish its steps", dom[-300:])
    got = json.loads(htmllib.unescape(hit_.group(1)))
    assert sorted(got) == names, "every run was measured"
    M_ = 12
    kinds = {"all": 0, "pan": 0}
    meets_ = lambda p, q_: p[0] < q_[2] and q_[0] < p[2] and p[1] < q_[3] and q_[1] < p[3]
    for name, r in got.items():
        assert "error" not in r, (name, r)
        for label, f in (("open", r["fit0"]), ("narrower card", r["narrow"])):
            c_, b_ = f["card"], f["box"]
            assert f["fit"] in ("all", "pan"), (name, label, f["fit"])
            assert f["font"] >= 11 and f["k"] > 0, (name, label, "labels are never under 11px at fit", f["font"])
            for lo, hi, ax in ((0, 2, "horizontally"), (1, 3, "vertically")):      # an axis that fits: inside the card with a margin; one that does not: starts at the margin and pans
                inside_ = b_[lo] >= c_[lo] + M_ - 1.5 and b_[hi] <= c_[hi] - M_ + 1.5
                assert inside_ or abs(b_[lo] - (c_[lo] + M_)) <= 1.5, (name, label, "the content box is inside the card or starts at its margin and pans", ax, b_, c_)
            if f["fit"] == "all":
                assert b_[0] >= c_[0] + M_ - 1.5 and b_[2] <= c_[2] - M_ + 1.5 and b_[1] >= c_[1] + M_ - 1.5 and b_[3] <= c_[3] - M_ + 1.5, (name, label, "fitted: inside the card", b_, c_)
                assert max((b_[2] - b_[0]) / (c_[2] - c_[0]), (b_[3] - b_[1]) / (c_[3] - c_[1])) >= 0.85, (name, label, "fills 85% of one side")
            assert f["sw"] <= f["iw"], (name, label, "no horizontal page scroll")
            ch_ = f["chip"]
            assert c_[0] <= ch_[0] and ch_[2] <= c_[2] and c_[1] <= ch_[1] and ch_[3] <= c_[3] and ch_[3] <= f["ih"], (name, label, "the legend chip is in the card and on screen", ch_, c_)
            assert not any(meets_(ch_, n_) for n_ in f["nodes"]), (name, label, "the legend chip covers no node or label at fit", ch_)
        kinds[r["fit0"]["fit"]] += 1
        assert r["lay0"][0] is False and r["lay0"][1] in (None, "0") and r["lay1"] == [True, "1"] and r["lay2"] is True and r["lay3"] == [False, "0", False, 1], (name, "the legend overlay starts closed, remembers its state, keeps it over a repaint", r["lay0"], r["lay1"], r["lay2"], r["lay3"])
        assert r["moved"] and r["fit1"] and r["fit2"], (name, "Fit after zoom and pan gives back the same transform, every time", r)
        assert r["wheel"] > 1 and r["plus"] == 1.5 and abs(r["max"] - 4) < 1e-6 and abs(r["min"] - 0.25) < 1e-6, (name, "wheel zooms in, + is 1.5x, the range is 0.25x to 4x", r["wheel"], r["plus"], r["max"], r["min"])
        assert r["keep"] == [True, True, 1] and r["esc"] == [True, 0], (name, "a click on a dot opens its panel and keeps the view; Esc closes it", r["keep"], r["esc"])
        assert r["back"] == [r["fit0"]["layout"], True, True, True], (name, "the card back to its width: the same drawing, the same fit; the card is watched for resizes", r["back"])
    print(f"map line: {len(got)} runs on the real page: fitted inside the card with a margin ({kinds['all']} fill it, {kinds['pan']} are held at 11px labels and pan), no label under 11px at fit, "
          "no horizontal page scroll, the legend chip in the card corner covering nothing; wheel, + and - (0.25x to 4x), Fit after zoom and pan gives back the same transform; a click on a dot keeps the view; a narrower card refits ok")


def late_judge_run():
    """A mock run with realization on and one forced Audit failure: every planned workflow is registered with its stage and zone from
    the plan; the fix Adaptation proposes after the failure inherits the stage and zone of the workflow it revises, is judged once
    (Priority's exchanges resend it; the judgement is cached) and recorded in realization.json under "late" with a system line."""
    import j2_realization
    keep = {k: os.environ.get(k) for k in ("J2_REALIZATION", "J2_CHANGE", "J2_FORCE_AUDIT_FAIL")}
    os.environ.update(J2_REALIZATION="1", J2_CHANGE="1", J2_FORCE_AUDIT_FAIL="1")
    try:
        run = j2.J2Run(); say(run, BREW_LAB); finish(run)
    finally:
        for k, v in keep.items():
            os.environ.pop(k, None) if v is None else os.environ.__setitem__(k, v)
    wfs = run._all_wfs()
    assert run.real is not None and wfs and all(w.get("stage") and w.get("certainty") and w.get("certainty_from") == ("plan" if not w.get("revises") else "inherited from " + w["revises"]) for w in wfs), \
        [(w["id"], w.get("stage"), w.get("certainty"), w.get("certainty_from")) for w in wfs]
    late = run.real.get("late") or []
    assert late and all(x["revises"] and x["zone"] and x["stage"] and x["score"] >= j2_realization.THRESHOLD and x["ready"] for x in late), late
    names = [x["workflow"] for x in late]
    assert len(names) == len(set(names)), ("a resent proposal is judged once", names)
    src = next(w for w in wfs if w["id"] == late[0]["revises"])
    assert late[0]["zone"] == src["certainty"] and late[0]["stage"] == src["stage"], (late[0], src)
    fix = next(w for w in wfs if w.get("revises") == src["id"])
    assert fix["certainty"] == src["certainty"] and fix["stage"] == src["stage"] and fix["judge"]["score"] == late[0]["score"] and fix["judge"]["ready"],         ("the registered fix carries the inherited zone and its judgement", fix)
    posts = [m for m in run.chat if m.get("judge")]
    assert posts and "scored 0.95" in posts[0]["text"] and f"zone {src['certainty']}, stage {src['stage']}" in posts[0]["text"], posts[0]["text"]
    saved = json.load(open(os.path.join(run.dir, "realization.json"), encoding="utf-8"))
    assert saved.get("late") == late, "the late judgements are saved with the plan"
    print(f"late judge: {len(wfs)} planned workflows placed from the plan; {len(late)} late judgement(s) inherited stage and zone and were judged once")


def plan_map_view():
    """Adaptation > Map (plan-map/1): the goal, the stages the Strategist chose and every registered workflow under each, from the run's own
    records (realization.json, workflows.json, change.json, goal.json). Browser-free: the pane draws the goal, every stage, a no-stage column and
    every workflow, tints by zone, shows the judge's score against the gate, marks a revised workflow and where a change started, and dashes a held one."""
    import j2_map as M
    import j2_realization as R
    td = tempfile.mkdtemp(prefix="j2-planmap-")
    rz = {"plan": {"certainty_assessment": {"zone": "analyze"}, "stages": [{"id": "product", "thinking": "scope"}, {"id": "build", "thinking": "make it"}],
                   "workflows": [{"name": "Plan", "stage": "product", "certainty": "analyze", "goal": "fix the scope"},
                                 {"name": "Shell", "stage": "build", "certainty": "operate", "goal": "page shell"}]},
          "scores": {"Plan": {"score": 0.95, "weakest": None}, "Shell": {"score": 0.79, "weakest": "done_test"}}, "history": {"Plan": [0.95], "Shell": [0.75, 0.79]},
          "plan_confidence": 0.79, "stages": {"product": {"confidence": 0.95, "zone": "analyze"}, "build": {"confidence": 0.79, "zone": "operate"}}}
    wfs = [{"id": "W-1", "name": "Plan", "stage": "product", "cycle": 1, "status": "done", "cost": 20},
           {"id": "W-2", "name": "Shell", "stage": "build", "cycle": 1, "status": "held", "cost": 30},
           {"id": "W-3", "name": "Plan (change 1)", "stage": "product", "cycle": 2, "status": "done", "cost": 20, "revises": "W-1",
            "certainty": "analyze", "certainty_from": "inherited from W-1", "judge": {"score": 0.9, "weakest": "done_test", "rounds": [0.7, 0.9], "ready": True}},
           {"id": "W-4", "name": "Extra", "cycle": 2, "status": "registered", "cost": 10}]
    ch = [{"id": "C-1", "request": "Rename the levels", "phase": "relay",
           "nodes": {"W-1": {"name": "Plan", "verdict": "change-here", "revisions": ["W-3"], "reason": "the levels live in the plan"}},
           "relay": [{"name": "Shell", "doc": "Plan (change 1)", "affected": False, "agree": True, "round": 0}]}]
    for f, obj in (("realization.json", rz), ("workflows.json", wfs), ("change.json", ch), ("goal.json", {"site_name": "Sudoku", "statement": "a sudoku page"})):
        json.dump(obj, open(os.path.join(td, f), "w", encoding="utf-8"))
    m = M.plan_map(td)
    assert m["found"] and m["goal"] == "Sudoku" and m["zone"] == "analyze" and m["confidence"] == 0.79 and m["threshold"] == R.THRESHOLD         and [s["id"] for s in m["stages"]] == ["product", "build"] and m["stages"][0]["workflows"] == ["W-1", "W-3"] and m["unplaced"] == ["W-4"], m
    w = {x["id"]: x for x in m["workflows"]}
    assert w["W-2"]["zone"] == "operate" and w["W-2"]["score"] == 0.79 and w["W-2"]["rounds"] == [0.75, 0.79] and w["W-2"]["weakest"] == "done_test"         and w["W-3"]["zone"] == "analyze" and w["W-3"]["zone_from"] == "inherited from W-1" and w["W-3"]["score"] == 0.9 and w["W-3"]["rounds"] == [0.7, 0.9] and w["W-1"]["zone_from"] == "plan" and w["W-4"]["zone"] is None and w["W-3"]["revises"] == "W-1" and w["W-1"]["revisions"] == ["W-3"] and w["W-1"]["change_start"]["change"] == "C-1"         and w["W-2"]["read"] == [{"change": "C-1", "doc": "Plan (change 1)", "affected": False, "agree": True, "round": 0, "doc_id": "W-1"}], w
    assert M.plan_map(tempfile.mkdtemp(prefix="j2-planmap-empty-")) == {"found": False} and M.plan_map(None) == {"found": False}
    out = render_node({"workflows": wfs, "chat": []}, docs={"docs": {}, "planmap": m})["planmap"]
    assert all(f'data-pm="{i}"' in out for i in ("goal", "product", "build", "unplaced", "W-1", "W-2", "W-3", "W-4")) and "Shell" in out, "every node is drawn"
    assert "var(--warm1)" in out and "var(--bld)" in out and out.count('class="pbadge"') == 3 and 'fill="var(--ok)"' in out and 'fill="var(--validator)"' in out,         "zones tint the squares; the badge is green at the gate and amber below it"
    assert 'class="pver"' in out and ">v2<" in out and 'class="phalo"' in out and "pedge reads" in out and 'stroke-dasharray="4 3"' in out, "v2, the change halo, the reread edge, the held dash"
    assert "No plan record" in render_node({"workflows": [], "chat": []}, docs={"docs": {}, "planmap": {"found": False}})["planmap"]
    ui = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "j2_ui.html"), encoding="utf-8").read()
    nav = ui[ui.index('id="railsub"'):ui.index("</nav>", ui.index('id="railsub"'))]
    assert nav.index('data-tab="planmap"') < nav.index('data-tab="workflows"') and 'planmap: "adaptation"' in ui, "Map sits under Adaptation, before Workflows"
    # the chat follows the open section: a message belongs to its speaker and to every function it addresses, hands to or is meant for
    fns = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "msgs": [
        {"who": "priority", "text": "@Adaptation GRANT for P-R1 and P-R2 at your estimates."}, {"who": "adaptation", "text": "@Priority two workflows", "next": "priority"},
        {"who": "W-1", "text": "@Coordination done", "audience": "audit"}, {"who": "identity", "text": "@Requester thanks", "audience": "user"}, {"who": "system", "text": "cycle 2"}]})["msgfns"]
    assert fns == [["priority", "adaptation"], ["adaptation", "priority"], ["W-1", "coordination", "audit"], ["identity"], ["system"]], fns
    assert "chatFollow(name);" in ui and 'id="chseg"' in ui and 'data-chmode="all">Whole chat<' in ui and 'id="chthink"' in ui, "showTab opens the function's chat, with a toggle to the whole chat"
    # activity/1: everything a function did, in order, from the records; a question answered from them (code only, or a model given the records)
    import j2_agent as AG
    td2 = tempfile.mkdtemp(prefix="j2-activity-")
    chat = [{"id": 1, "t": "10:00:00", "who": "user", "text": "Build it"}, {"id": 2, "t": "10:00:05", "who": "identity", "text": "@Adaptation the charter is recorded", "next": "adaptation"},
            {"id": 3, "t": "10:01:00", "who": "adaptation", "text": "Plan by realization: 2 stages", "realization": True}, {"id": 4, "t": "10:01:10", "who": "adaptation", "text": "@Priority proposing 2 workflows", "next": "priority"},
            {"id": 5, "t": "10:02:00", "who": "priority", "text": "@Coordination go", "next": "coordination"}, {"id": 6, "t": "10:03:00", "who": "user", "text": "Rename the levels"}]
    open(os.path.join(td2, "chat.jsonl"), "w", encoding="utf-8").write("".join(json.dumps(m) + chr(10) for m in chat))
    calls = [{"id": 1, "fn": "adaptation", "t": "10:00:50", "step": 2, "cycle": 1, "seconds": 3.5, "reason": "two stages suffice", "inputs": [["charter", "x"]], "reply": {"say": "ok", "proposals": [1, 2]}},
             {"id": 2, "fn": "priority", "t": "10:02:00", "step": 3, "seconds": 1}]
    open(os.path.join(td2, "calls.jsonl"), "w", encoding="utf-8").write("".join(json.dumps(c) + chr(10) for c in calls))
    rz["rounds"] = [{"round": 0, "scores": {"Plan": {"score": 0.95, "weakest": None}, "Shell": {"score": 0.79, "weakest": "done_test", "missing": ["no pass line"]}}, "changes": [], "plan_faults": []}]
    rz["late"] = [{"workflow": "Plan (change 1)", "revises": "W-1", "t": "10:03:30", "score": 0.9, "weakest": "done_test", "missing": ["no pass line"], "rounds": [0.7, 0.9], "ready": True, "zone": "analyze", "stage": "product"}]
    json.dump(rz, open(os.path.join(td2, "realization.json"), "w", encoding="utf-8")); json.dump(wfs, open(os.path.join(td2, "workflows.json"), "w", encoding="utf-8"))
    json.dump([dict(ch[0], chat0=5)], open(os.path.join(td2, "change.json"), "w", encoding="utf-8"))
    act = AG.activity(td2, "adaptation"); kinds = [e["kind"] for e in act["events"]]
    assert act["found"] and act["persona"] == "Strategist" and kinds.count("msg") == 3 and kinds.count("call") == 1 and kinds.count("judge") == 2 and "revise" not in kinds and kinds.count("wf") == 2 and kinds.count("change") == 3, kinds
    late = [e for e in act["events"] if e["kind"] == "judge"][-1]
    assert late["t"] == "10:03:30" and "Judged Plan (change 1) (revises W-1): 0.90 after one improvement" in late["title"] and "rounds: 0.70 → 0.90" in late["items"][1], late
    ts = [e["t"] for e in act["events"]]
    assert ts == sorted(ts) and ts[kinds.index("call")] == "10:00:50" and all(e["t"] == "10:01:00" for e in act["events"] if e["kind"] in ("plan", "wf") or (e["kind"] == "judge" and "round" in e["title"])) \
        and all(e["t"] == "10:03:00" for e in act["events"] if e["kind"] == "change") and kinds.index("judge") > kinds.index("wf") and kinds[-1] == "judge" and kinds[-2] == "change", (kinds, ts)
    judge = next(e for e in act["events"] if e["kind"] == "judge")
    assert "1 below" in judge["title"] and any("Shell: 0.79" in x and "done_test" in x and "no pass line" in x for x in judge["items"]), judge
    assert AG.activity(td2, "audit") == {"schema": "activity/1", "who": "audit", "persona": "Quality Reviewer", "found": False, "names": act["names"], "events": []}
    ans = AG.answer(td2, "adaptation", "what did the judge say about Shell?")
    assert ans["from"] == "records" and "Shell: 0.79" in ans["answer"], ans
    assert "nothing about that" in AG.answer(td2, "adaptation", "zzzz")["answer"] and "nothing for" in AG.answer(tempfile.mkdtemp(prefix="j2-act-empty-"), "adaptation", "x")["answer"]
    asked = {}
    got = AG.answer(td2, "adaptation", "why?", ask=lambda system, user, mock, **kw: asked.update(system=system, user=user) or "Because the judge said so.")
    assert got["from"] == "model" and got["answer"] == "Because the judge said so." and "YOUR RECORDS" in asked["user"] and "Shell: 0.79" in asked["user"] and "Strategist" in asked["system"], "the model gets the records and the question"
    feed0 = render_node({"workflows": wfs, "chat": []}, docs={"docs": {}, "activity": act})["feed"]
    assert feed0.count('class="msg ') == 3 and " fev f-" not in feed0, "the switch off: the function's messages only"
    feed = render_node({"workflows": wfs, "chat": []}, docs={"docs": {}, "activity": act, "think": True})["feed"]
    assert feed.count(' fev f-') == len(act["events"]) - 3 and feed.count('class="msg ') == len(act["events"]) and feed.count('class="tag kind"') == len(act["events"]) - 3 and "f-judge" in feed and "Judge round 0" in feed and "Created Plan in product" in feed and "C-1: Rename the levels" in feed, "the feed draws every event in the chat's message style: messages as they are, the rest with a small label for their kind"
    print("plan map: the Sudoku-shaped record builds, the pane draws every node with zone, score, v2, change halo and reread edge; Map sits under Adaptation; the chat follows the section; the feed and the question answer from the records")


def left_bar():
    """Left bar data (the icon rail draws it; left_bar_toggle tests the rail itself): the tabs in sections (Conflicts only when the run has conflicts, the five functions,
    Artifacts, Actions, Other, Settings); no Internals folder. Every rail item's status line and badge come from the same records. Every run under runs/ (browser-free): every tab sits in exactly one section and Other is empty; Workflows is
    under Adaptation and Priorities under Priority; Priority's header and view come from the run's decisions, priced workflows and conflicts (a run with none says so);
    the Workflows view lists every workflow once, by cycle, each with a link to its place in the Map's Tree; the tabs whose data this run lacks are dimmed with their reason
    and exactly those; the conflicts and the actions of the run are each listed once; no artifact row says "not audited" and each guide and section row shows its
    record's mark (latest checks by code, audit of its items). With Chrome (--browser): Map and Chat rows, the active one highlighted, sections open and close and remember it, a dimmed tab still opens, a workflow's Map
    link focuses it in the Tree, the Run details line has the run id and budget."""
    import collections
    import copy
    import html as htmllib
    import threading
    import j2_map as M
    import j2_artifacts as A
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    nav = ui[ui.index('<nav class="rail tabs"'):ui.index("</nav>", ui.index('<nav class="rail tabs"'))]
    assert 'id="internals"' not in ui and "Internals" not in nav and 'id="railtoggle"' not in ui, "no Internals folder and no menu button: the icon rail"
    tabs = [t_ for t_ in re.findall(r'data-tab="(\w+)"', nav[nav.index('id="railsub"'):]) if t_ != "map"]      # the Map has its own rail item
    assert len(tabs) == len(set(tabs)) >= 17 and "priorities" in tabs, tabs
    plural = lambda n, w: f"{n} {w}{'' if n == 1 else 's'}"
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo
    seen = collections.Counter()
    order = ["conflicts", "identity", "adaptation", "priority", "coordination", "audit", "artifacts", "actions", "library", "other", "settings"]
    try:
        for name in names:
            d = os.path.join(repo, name)
            rd_ = lambda f, dflt: json.load(open(os.path.join(d, f))) if os.path.isfile(os.path.join(d, f)) else dflt
            m = M.build(d)
            rows_ = [json.loads(x) for x in open(os.path.join(d, "chat.jsonl"), encoding="utf-8") if x.strip()] if os.path.isfile(os.path.join(d, "chat.jsonl")) else []
            chat = [x for x in rows_ if not x.get("meta")]
            summ, report, wfs = rd_("summary.json", {}), rd_("report.json", None), rd_("workflows.json", [])
            site = os.path.join(d, "site")
            versions = len([f for f in os.listdir(site) if re.fullmatch(r"v\d+\.(?:html|md)", f)]) if os.path.isdir(site) else 0
            b_ = summ.get("budget") or {}
            snap = {"workflows": wfs, "chat": chat, "call_log": [], "conflicts": rd_("conflicts.json", []), "goal": rd_("goal.json", None), "stamped": True,
                    "page": j2.saved_page(d, None),      # the run's page type (/api/state "page"): its Artifacts site group is that node
                    "audits": [a for a in rd_("audits.json", []) if (a or {}).get("kind") != "recheck"], "report": report, "outcome": summ.get("outcome"), "versions": versions,
                    "docset": list(rd_("documents.json", {})), "style": rd_("style.json", None), "memory": False, "budget": b_.get("granted") or j2.BUDGET, "spent": b_.get("used") or 0,
                    "lessons_used": (summ.get("lessons") or {}).get("used", []), "lessons_saved": (summ.get("lessons") or {}).get("saved", []),
                    "playbooks_used": (summ.get("playbooks") or {}).get("used", []), "playbook_saved": (summ.get("playbooks") or {}).get("saved"), "has_templates": os.path.isfile(os.path.join(d, "templates.json"))}
            t = A.tree(d, m)
            docs_ = j2_server.docs_view(d)      # what /api/docs gives the page: the documents written, and those asked for and not written
            plan, planmap = M.plan_view(d), M.plan_map(d)
            gr = A.groups(d, m)
            out = render_node(snap, docs={"docs": docs_, "map": m, "railtabs": tabs, "plan": plan, "planmap": planmap, "artifacts": {"tree": t, "groups": gr}})
            model = out["rail"]
            assert [x["id"] for x in model] == order, (name, "the sections, in order")
            # deep links from the Map: every workflow has its row in Workflows, every artifact and section on the Map its item in Artifacts
            for w in wfs:
                assert f'data-wfrow="{htmllib.escape(w["id"])}"' in out["workflows"], (name, w["id"], "a workflow's deep link lands on no Workflows row")
            arts_html = "".join(render_node(snap, docs={"docs": {}, "map": m, "artifacts": {"groups": gr, "g": k, "sel": {}, "tab": "sum", "ver": ""}})["artifacts"]
                                for k in ("plan", "guides", "site", "documents", "records"))      # every group's list (a row's data-node lists each Map node it holds)
            arts_html = re.sub(r'data-node="([^"]*)"', lambda x: " ".join(f'data-node="{v}"' for v in x.group(1).split()), arts_html)
            map_arts = {n["id"]: n for n in m["nodes"] if n["kind"] == "work"}
            ids = set(map_arts) | {a for C in (m.get("constellations") or {}).values() for a in [C["id"]] + [s_["section"] for s_ in C["slots"] if s_["section"]]}
            def want_of(a):      # mapDeepTarget: a section's own row, else its document's item
                if a.startswith("sec:"):
                    return [f'data-sec="{htmllib.escape(":".join(a.split(":")[1:-1]) + "|" + a.split(":")[-1])}"'] + want_of(":".join(a.split(":")[1:-1]))
                f_ = (map_arts.get(a) or {}).get("file")
                return [f'data-node="{htmllib.escape(a)}"'] + ([f'data-art="{htmllib.escape(f_)}"'] if f_ else []) + (['data-art="goal.json"'] if a == "work:charter" else []) \
                    + ([f'data-agrow="{htmllib.escape(a[5:])}"'] if a.startswith("work:") and a[5:] not in ("prd", "hld", "lld") else [])      # a new type's document: its Artifacts row (mapDeepTarget)
            for a in sorted(ids):
                want = want_of(a)
                doc = re.sub(r"^work:", "", ":".join(a.split(":")[1:-1]) if a.startswith("sec:") else a)
                assert any(w_ in arts_html for w_ in want) or (doc in ("prd", "hld", "lld") and f'id="docblock-{doc}"' in out["docs"]), \
                    (name, a, "an artifact's deep link lands on no Artifacts item (a PRD, HLD or LLD: on its Documents block)", want)
                seen["deep links"] += 1
            seen["deep links"] += len(wfs)
            sec = {x["id"]: x for x in model}
            placed = [t_["tab"] for x in model for t_ in x["tabs"]]
            assert sorted(placed) == sorted(tabs), (name, "every tab is in exactly one section")
            assert sec["other"]["tabs"] == [] and not sec["other"]["shown"], (name, "Other is empty", sec["other"]["tabs"])
            assert [t_["tab"] for t_ in sec["adaptation"]["tabs"]] == ["planmap", "workflows", "lessons", "playbooks"], (name, "Map, then Workflows, under Adaptation")
            assert [t_["tab"] for t_ in sec["priority"]["tabs"]] == ["priorities"] and "workflows" not in [t_["tab"] for t_ in sec["coordination"]["tabs"]], (name, "Priorities under Priority")
            assert sorted(t_["tab"] for t_ in sec["coordination"]["tabs"]) == ["board", "story", "timeline"], (name, "Coordination keeps Timeline, Board, Board story")
            conf = snap["conflicts"]
            assert sec["conflicts"]["shown"] == bool(conf), (name, "Conflicts is there only when the run has conflicts")
            assert [i["id"] for i in sec["conflicts"]["items"]] == [c["id"] for c in conf] and all(i["fns"] == c["between"] for i, c in zip(sec["conflicts"]["items"], conf)), (name, "each conflict once, with its functions")
            # Priorities, from the records
            dec = [x for x in chat if x.get("who") == "priority" and x.get("decision")]
            has = bool(dec or wfs)
            bm = ((report or {}).get("metrics") or {}).get("budget") or {}
            total, spent = bm.get("total", snap["budget"]), bm.get("spent", snap["spent"])
            cuts = sum(1 for c in conf if isinstance(c.get("adaptation_final"), list) and isinstance(c.get("priority_final"), list)
                       for p in c["adaptation_final"] if not any(q.get("name") == p.get("name") for q in c["priority_final"]))
            ndef = sum(1 for w in wfs if w.get("status") == "held") + cuts
            want = f"{spent} of {total} credits · {ndef} deferred" if has else "no ranking records"
            assert sec["priority"]["status"] == want and out["prio"]["status"] == want, (name, "Priority's header comes from the records", sec["priority"]["status"], want)
            cycles = sorted({(x.get("cycle") or 1) for x in dec} | {(w.get("cycle") or 1) for w in wfs})
            if has:
                assert out["priorities"].count("<details") == len(cycles) and all(f"<b>Cycle {c}</b>" in out["priorities"] for c in cycles), (name, "one block per cycle")
                assert out["priorities"].count("<li><b>GRANT") + out["priorities"].count("<li><b>COUNTER") + out["priorities"].count("<li><b>REFUSE") == len(dec), (name, "every decision once")
                assert sum(len(c["ranked"]) for c in out["prio"]["per"]) == sum(1 for w in wfs if w.get("status") != "held") and sum(len(c["deferred"]) for c in out["prio"]["per"]) == ndef, (name, "funded and deferred work")
            else:
                assert "No ranking records" in out["priorities"], (name, "a run with no ranking records says so")
            seen["with ranking" if has else "no ranking"] += 1
            # Workflows: every workflow once, with a link to a stage of the Tree
            wv = out["workflows"]
            assert "data-planview" in wv and "Workflows by cycle" in wv and "Replans" in wv, (name, "the Workflows view")
            stage_of = {w_: n["id"] for n in out["tree"]["nodes"] if n["kind"] == "stage" for w_ in n["workflows"]}
            lost = " ".join(x for x in m["not_recorded"] if x.startswith("workflows not placed on the map"))
            for w in wfs:
                if w["id"] in stage_of:
                    assert wv.count(f'data-wfmap="{w["id"]}"') == 1 and f'data-wfmap="{w["id"]}" data-stage="{htmllib.escape(stage_of[w["id"]], quote=True)}"' in wv, (name, w["id"], "every workflow the Map draws links to its team")
                else:      # the Map itself lists it under Not recorded: there is no node to link to
                    assert f'data-wfmap="{w["id"]}"' not in wv and re.search(rf"\b{re.escape(w['id'])}\b", lost), (name, w["id"], "a workflow the Map does not draw says so and is in the Map's Not recorded")
                    seen["workflows not on the map"] += 1
            assert wv.count("not on the map") == sum(1 for w in wfs if w["id"] not in stage_of), (name, "each such workflow says so once")
            assert (plan["found"] and all(f"<b>{htmllib.escape(x['id'])}</b>" in wv for x in plan["stages"])) or (not plan["found"] and "not recorded for this run" in wv), (name, "the stages, or that they are not recorded")
            seen["workflows linked"] += len(wfs)
            seen["with plan"] += plan["found"]
            # dimmed tabs: exactly those whose data this run lacks
            lacks = {"goal": not snap["goal"], "charter": not snap["goal"], "report": not report and not summ.get("outcome"), "workflows": not wfs, "priorities": not has, "timeline": not chat,
                     "audit": not snap["audits"], "preview": not versions, "docs": not snap["docset"] and not any(v["text"] for v in docs_.values()), "artifacts": not any(g["count"] for g in t["groups"]),
                     "lessons": not (snap["lessons_used"] or snap["lessons_saved"]), "playbooks": not (snap["playbooks_used"] or snap["playbook_saved"]),
                     "planmap": not planmap["found"]}
            dimmed = {t_["tab"] for x in model for t_ in x["tabs"] if t_["dim"]}
            assert dimmed == {k for k, v in lacks.items() if v}, (name, "dimmed tabs are the ones with no data", dimmed ^ {k for k, v in lacks.items() if v})
            assert all(t_["dim"] for x in model for t_ in x["tabs"] if t_["tab"] in ("lessons", "playbooks") and lacks[t_["tab"]]) and not any(t_["dim"] for x in model for t_ in x["tabs"] if t_["tab"] in ("rundetails", "runsettings", "conflicts", "map")), (name, "reasons given; the settings are never dimmed")
            seen["dimmed"] += len(dimmed)
            sends = [n for n in m["nodes"] if n["kind"] == "work" and n.get("tag") == "Send"]
            assert sorted(i["id"] for i in sec["actions"]["items"]) == sorted(n["id"] for n in sends) and all(i["state"] for i in sec["actions"]["items"]), (name, "each action once, with a state")
            seen["actions"] += len(sends)
            seen["conflicts"] += len(conf)
            results = {}      # Audit: a finding is a check that failed in some audit; fixed when it passes in the latest audit that has it
            for a in sorted(snap["audits"], key=lambda a: a["cycle"]):
                for i_, r in enumerate(a.get("results", []) + a.get("extra_issues", [])):
                    k_ = r.get("id") or f"x{a['cycle']}-{i_}"
                    bad_ = r.get("pass") is False or r.get("verdict") == "FAIL"
                    if bad_:
                        results.setdefault(k_, {})
                    if k_ in results:
                        results[k_]["last"] = not bad_
            n_, fx_ = len(results), sum(1 for r in results.values() if r["last"])
            wantA = (f"{plural(n_, 'finding')}, {fx_} fixed" + (f", {n_ - fx_} open" if n_ - fx_ else "")) if n_ else ("no findings" if snap["audits"] else "no audits yet")
            assert sec["audit"]["status"] == wantA, (name, sec["audit"]["status"], wantA)
            assert sec["coordination"]["status"] == (f"{sum(1 for w in wfs if w.get('status') == 'done')} of {len(wfs)} workflows done" if wfs else "no workflows yet"), name
            # artifact rows: a mark only on a guide or a section, and it is the record's (its latest version's checks by code and the audit of its items)
            rows = [x for g_ in gr["groups"] for x in g_["rows"] if x.get("versions")]
            for x in rows:
                seg = arts_html.split(f'data-agrow="{htmllib.escape(x["id"])}"', 1)[1].split("</button>", 1)[0]
                assert ("am-ok" in seg) == x["ok"] and ("am-warn" in seg) == (not x["ok"]), (name, x["id"], "a row's mark is its record's")
            lists = "".join(re.findall(r'<div class="aglist".*?</div><div class="agpane"', arts_html, re.S))
            assert "not audited" not in lists and lists.count("am-ok") + lists.count("am-warn") == len(rows), (name, "one mark per guide and section row, none says not audited")
            seen["artifact rows"] += len(rows)
            seen["artifact audit"] += sum(1 for x in rows if not x["ok"])
            # the icon rail: every tab in exactly one item; the status lines and badges come from the same records
            rs_ = out["railst"]
            flat = [t_ for v in rs_["items"].values() for t_ in v]
            assert sorted(flat) == sorted(tabs) and rs_["items"]["map"] == [], (name, "every tab in exactly one rail item", sorted(set(tabs) ^ set(flat)))
            assert rs_["items"]["priority"] == ["priorities", "conflicts"] and sorted(rs_["items"]["identity"]) == ["charter", "goal", "report"] and sorted(rs_["items"]["settings"]) == ["rundetails", "runsettings"], (name, rs_["items"])
            assert rs_["items"]["library"] == ["library"] and sorted(rs_["items"]["artifacts"]) == ["artifacts", "docs", "preview"], (name, "Library is its own rail item; Artifacts keeps Preview, Documents, Artifacts", rs_["items"])
            assert rs_["st"]["library"] == ("templates you can reuse" if snap.get("has_templates") else "no templates in this run"), (name, rs_["st"]["library"])
            settled_ = sum(1 for c in conf if c.get("status") == "settled"); open_ = len(conf) - settled_
            wantP = " · ".join(x for x in [f"{spent} of {total} credits" if has else "no ranking records", f"{ndef} deferred" if ndef else "",
                                            f"{plural(open_, 'conflict')} open" if open_ else "", f"{plural(settled_, 'conflict')} settled" if settled_ else ""] if x)
            assert rs_["st"]["priority"] == wantP and rs_["st"]["audit"] == wantA and rs_["st"]["coordination"] == sec["coordination"]["status"] and rs_["st"]["identity"] == sec["identity"]["status"], (name, rs_["st"], wantP, wantA)
            assert rs_["badge"]["priority"] == ((([open_, "", f"{plural(open_, 'conflict')} open"]) if open_ else [settled_, "ok", f"{plural(settled_, 'conflict')} settled"]) if conf else None), (name, rs_["badge"]["priority"])
            assert rs_["badge"]["audit"] == ((([n_ - fx_, "", f"{plural(n_ - fx_, 'finding')} open"]) if n_ - fx_ else [n_, "ok", f"{plural(n_, 'finding')}, all fixed"]) if n_ else None), (name, rs_["badge"]["audit"])
            last_ = next((x for x in reversed(chat) if x.get("who") != "system"), None)
            need_ = 1 if last_ and last_.get("pause") and last_.get("who") == "identity" else 0
            assert rs_["badge"]["identity"] == ([need_, "", f"{plural(need_, 'item')} waiting on you"] if need_ else None), (name, rs_["badge"]["identity"])
            ck_ = (m.get("status") or {}).get("checks") or {}
            assert (f"{ck_['passed']} of {ck_['run']} checks passed" in rs_["st"]["map"]) if ck_.get("run") else "checks passed" not in rs_["st"]["map"], (name, rs_["st"]["map"])
            seen["rail badges"] += sum(1 for v in rs_["badge"].values() if v)
            seen["runs"] += 1
        # a tab the table does not name: the function whose Map node carries it, else Other
        name = "j2-20261026-174314" if "j2-20261026-174314" in names else names[0]
        m = copy.deepcopy(M.build(os.path.join(repo, name)))
        next(n for n in m["nodes"] if n["id"] == "fn:audit")["tab"] = "futuretab"
        got = {x["id"]: x for x in render_node({"workflows": [], "chat": []}, docs={"docs": {}, "map": m, "railtabs": tabs + ["futuretab", "orphantab"]})["rail"]}
        assert [t_["tab"] for t_ in got["audit"]["tabs"] if t_["how"] == "function node tab"] == ["futuretab"] and [t_["tab"] for t_ in got["other"]["tabs"]] == ["orphantab"] and got["other"]["shown"], "derived placement, then Other"
        e_ = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "map": m, "railtabs": tabs})
        assert "No ranking records" in e_["priorities"] and e_["prio"]["status"] == "no ranking records" and all(x["dim"] for y in e_["rail"] for x in y["tabs"] if x["tab"] == "priorities"), "a run with no ranking records says so"
    finally:
        j2.RUNS_DIR = keep_dir
    print(f"left bar: {seen['runs']} runs: icon rail (every tab in exactly one item, status lines and {seen['rail badges']} badges from the records), no Internals; every one of the {len(tabs)} tabs in exactly one section, Other empty; Priorities ({seen['with ranking']} runs with ranking records, "
          f"{seen['no ranking']} without) and the Workflows view ({seen['workflows linked']} workflows, each linked to its Map team ({seen['workflows not on the map']} the Map itself lists as not placed, shown as such), {seen['with plan']} runs with a plan record) render from the records; {seen['dimmed']} dimmed tabs, exactly the ones with no data; "
          f"{seen['conflicts']} conflicts and {seen['actions']} actions each once; {seen['artifact rows']} guide and section rows with their record's mark ({seen['artifact audit']} needing a look), none \"not audited\""
          + " ok")


def left_bar_toggle():
    """The icon rail (the full view's left bar). Static: Map, Chat, the five function bots, Artifacts, Actions, Settings and the theme, in that order, each a
    labelled button; no menu button; the label colours are the theme's (warm dark in light mode, cream in dark mode); reduced motion turns it all off; hover and
    keyboard focus share every reaction. With Chrome (--browser), on two saved runs at 1440x900 and 390x844, light and dark: no page error and no sideways scroll; focus
    shows the label in the theme's colours and a bot's alert face; each item's panel opens with its name, role, status line and tabs (railStatus, from the records),
    keeps the focus inside, and closes on Esc, Close and a click outside, giving the focus back; picking a tab opens it in the main area; the Map's Run graph opens the
    Map's graph; Chat opens the Simple view; the badges show; the chat calls the Validator the Gatekeeper."""
    import html as htmllib
    import threading
    import j2_map as M
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    nav = ui[ui.index('<nav class="rail tabs"'):ui.index("</nav>", ui.index('<nav class="rail tabs"'))]
    names_ = re.findall(r'class="ri [^"]*"[^>]*data-name="([^"]+)"', nav)
    assert names_ == ["Map", "Simple view", "Identity", "Adaptation", "Priority", "Coordination", "Audit", "Artifacts", "Actions", "Library", "Settings"], names_
    assert nav.count('<button type="button" class="ri ') == 11 and nav.count("aria-label=") >= 11 and 'id="rtheme"' in nav and 'id="railtoggle"' not in ui and 'id="barbadge"' not in ui, "eleven labelled buttons and the theme; no menu button"
    for cls in ("p-id", "p-plan", "p-bud", "p-sch", "p-aud"):
        b = nav[nav.index(f'class="ri {cls}"'):]
        b = b[:b.index("</button>")]
        assert b.index('class="hb"') < b.index('<g class="hat">') and 'class="omouth"' in b and 'class="alert"' in b, (cls, "a bot: the hat in front of the head, an O mouth and a !")
    assert "56%,72%{transform:translate(2.6px,0)}" in ui, "the idle glance goes to the bots' own left: into the page"
    lib = nav[nav.index('data-ri="library"'):nav.index('data-ri="settings"')]
    assert nav.index('data-ri="actions"') < nav.index('data-ri="library"') < nav.index('data-ri="settings"') and lib.count('class="bk') == 5 and '<g class="act"><rect class="bk4"' in lib and 'Library<small>templates to start from</small>' in lib, "Library: a bookshelf between Actions and Settings, one book that tips and slides up"
    for cls in ("p-id",):
        b = nav[nav.index(f'class="ri {cls}"'):]
        assert cls != "p-id" or ('class="boom"' in b and 'class="act mic"' in b and 'class="arm"' not in b), "Identity: a headset with a mic boom and its light, no waving arm"
    T = theme_tokens(ui)
    assert (T["light"]["lblbg"], T["light"]["lblink"], T["dark"]["lblbg"], T["dark"]["lblink"]) == ("#2a2520", "#f3ebe0", "#f6eee3", "#2e2721"), "label colours"
    assert all(contrast(T[t]["lblink"], T[t]["lblbg"]) >= 4.5 and contrast(T[t]["lblsub"], T[t]["lblbg"]) >= 4.5 for t in T), "label text 4.5:1"
    assert "@media (prefers-reduced-motion:reduce){#rail *,#rail *::before,.rfly{animation:none!important;transition:none!important}}" in ui
    for rule in ("#rail .ri:is(:hover,:focus-visible) .omouth{opacity:1", "#rail .ri:is(:hover,:focus-visible) .rlbl{opacity:1", "#rail .s-art:is(:hover,:focus-visible) .lid{transform:rotate(-28deg)}",
                 "#rail .p-bud:is(:hover,:focus-visible) .act{animation:none;transform:translateY(-10px)}", "#rail .p-id:is(:hover,:focus-visible) .act{animation:rmic .5s",
                 "#rail .p-id .act{animation:rmic 2.4s", "#rail .s-lib .act{animation:rlean 4s", "#rail .s-lib:is(:hover,:focus-visible) .act{animation:none;transform:translateY(-7px)}"):
        assert rule in ui, ("hover and keyboard focus share the reaction", rule)      # Chrome is probed with focus; a real hover can't be scripted
    chrome = j2.j2_check.find_chrome()
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    if not (chrome and BROWSER and names):
        print("icon rail: static checks ok (browser steps skipped: Chrome not found, no saved run, or --fast without --browser)")
        return
    with_c = next((n for n in reversed(names) if os.path.isfile(os.path.join(repo, n, "conflicts.json")) and json.load(open(os.path.join(repo, n, "conflicts.json")))), None)
    runs = list(dict.fromkeys([n for n in ("j2-20261026-174314", with_c) if n and n in names])) or names[-1:]
    head = "<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message)));</script>"
    probe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), vis = e => !!e && e.getClientRects().length > 0, r = {}, S = id => document.getElementById(id);"
             " const fin = () => document.getAnimations().filter(a => a instanceof CSSTransition).forEach(a => a.finish()); await wait(2500); const st = railStatus(state, MAP);"
             " r.items = q('#rail .ri').map(b => [b.tagName, b.dataset.name, (b.getAttribute('aria-label') || '').startsWith(b.dataset.name + ', ')]);"
             " r.badges = q('#rail .ri').filter(b => !b.querySelector('.rbadge').hidden).map(b => (b.dataset.ri || 'chat') + ':' + b.querySelector('.rbadge').textContent + ':' + b.querySelector('.rbadge').classList.contains('ok'));"
             " r.wantBadges = Object.entries(st.badge).filter(([k, v]) => v).map(([k, v]) => k + ':' + v[0] + ':' + (v[1] === 'ok'));"
             " r.gk = q('#msgs .msg.validator .who').map(e => (e.querySelector('.whobtn') || e.firstChild).textContent.trim()); r.v = (state.allChat || []).filter(m => m.who === 'validator').length;"
             " r.themes = {}; for (const th of ['light', 'dark']){ THEME = th; themeApply(); const b = document.querySelector('#rail .p-bud'); b.focus(); fin(); const l = b.querySelector('.rlbl');"
             "   r.themes[th] = [getComputedStyle(l).opacity, getComputedStyle(l).backgroundColor, getComputedStyle(b.querySelector('.omouth')).opacity, getComputedStyle(b.querySelector('.alert')).opacity, document.documentElement.scrollWidth <= innerWidth]; b.blur(); }"
             " r.panels = {}; for (const b of q('#rail .ri[data-ri]')){ b.click(); await wait(30); const f = S('rfly'), id = b.dataset.ri;"
             "   const p = {open: !f.hidden && b.getAttribute('aria-expanded') === 'true', head: S('rflyh').textContent.trim(), role: S('rflyrole').textContent, st: S('rflyst').textContent === (st.st[id] || ''),"
             "     focusIn: f.contains(document.activeElement), tabs: q('#rfl [data-tab]').map(x => x.dataset.tab), gos: q('#rfl .rgo').map(x => x.textContent.trim()), dims: q('#rfl [data-dim]').map(x => x.dataset.tab + '=' + x.dataset.sub)};"
             "   const fs = q('#rfly button').filter(vis); fs[fs.length - 1].focus(); f.dispatchEvent(new KeyboardEvent('keydown', {key: 'Tab', bubbles: true})); p.trap = document.activeElement === fs[0];"
             "   document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); p.esc = f.hidden && document.activeElement === b && b.getAttribute('aria-expanded') === 'false';"
             "   b.click(); f.querySelector('.rclose').click(); p.close = f.hidden && document.activeElement === b;"
             "   b.click(); S('needs').click(); p.outside = f.hidden; r.panels[id] = p; }"
             " document.querySelector('#rail [data-ri=identity]').click(); q('#rfl [data-tab=goal]')[0].click(); r.pick = [vis(S('pane-goal')), S('rfly').hidden, document.querySelector('#rail [data-ri=identity]').classList.contains('cur')];"
             " document.querySelector('#rail [data-ri=map]').click(); q('#rfl [data-mapgo=line]')[0].click(); r.graph = [vis(S('pane-map')), MAPVIEW, S('rfly').hidden]; MAPVIEW = 'tree'; paintMap();"
             " r.sw = [document.documentElement.scrollWidth, innerWidth]; S('gochat').click(); r.chat = document.body.classList.contains('simple'); r.err = __e.slice();"
             " (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify(r)); })()")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-rail-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    wrap = {}

    class Wrap(j2_server.Handler):      # a phone-width frame, same origin (headless Chrome's window is at least 500px wide)
        def do_GET(self):
            return self._send(200, wrap["page"], "text/html") if self.path.startswith("/wrap") else super().do_GET()
    keep_here, runs_ = j2_server.HERE, j2.RUNS_DIR
    j2_server.HERE, j2.RUNS_DIR = tmp, repo
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), Wrap)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base, seen = f"http://127.0.0.1:{srv.server_address[1]}", 0
    want_tabs = {"identity": ["goal", "charter", "report"], "adaptation": ["planmap", "workflows", "lessons", "playbooks"], "priority": ["priorities", "conflicts"], "coordination": ["timeline", "board", "story"],
                 "audit": ["audit"], "artifacts": ["preview", "docs"], "library": ["library"], "settings": ["rundetails", "runsettings"], "map": [], "actions": []}
    try:
        for run in runs:
            sends = [n for n in M.build(os.path.join(repo, run))["nodes"] if n["kind"] == "work" and n.get("tag") == "Send"]
            for w, h in ((1440, 900), (390, 844)):
                url = f"/?view=detail&run={run}"
                if w < 500:
                    wrap["page"] = f'<!doctype html><body style="margin:0"><iframe src="{url}" style="width:{w}px;height:{h}px;border:0;display:block"></iframe></body>'
                    url = "/wrap"
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--window-size={max(w, 500)},{h}", "--virtual-time-budget=30000", "--dump-dom", base + url],
                                 capture_output=True, text=True, timeout=180).stdout
                hit = re.search(r'data-r="([^"]*)"', dom)
                assert hit, (run, w, "the page did not finish its steps", dom[-300:])
                r = json.loads(htmllib.unescape(hit.group(1)))
                assert not r["err"] and r["sw"][0] <= r["sw"][1], (run, w, r["err"], r["sw"])
                assert [x[1] for x in r["items"]] == ["Map", "Simple view", "Identity", "Adaptation", "Priority", "Coordination", "Audit", "Artifacts", "Actions", "Library", "Settings"] and all(x[0] == "BUTTON" and x[2] for x in r["items"]), (run, w, r["items"])
                assert sorted(r["badges"]) == sorted(r["wantBadges"]), (run, w, "the badges are the records'", r["badges"], r["wantBadges"])
                assert r["v"] == 0 or (r["gk"] and set(r["gk"]) == {"Gatekeeper"}), (run, w, "the chat calls the Validator the Gatekeeper", r["gk"])
                assert r["themes"]["light"][:2] == ["1", "rgb(42, 37, 32)"] and r["themes"]["dark"][:2] == ["1", "rgb(246, 238, 227)"], (run, w, "the label in the theme's colours", r["themes"])
                assert all(v[2:] == ["1", "1", True] for v in r["themes"].values()), (run, w, "a bot's alert face on focus; no sideways scroll", r["themes"])
                for id_, p in r["panels"].items():
                    assert p["open"] and p["st"] and p["focusIn"] and p["trap"] and p["esc"] and p["close"] and p["outside"], (run, w, id_, "opens, holds the focus, closes on Esc, Close and outside", p)
                    assert p["tabs"] == want_tabs[id_], (run, w, id_, "its tabs, in order", p["tabs"])
                    if id_ == "map":
                        assert p["gos"] == ["Treeteams and what they made", "Run graphevery workflow and artifact"], (run, w, p["gos"])
                    if id_ == "actions":
                        assert len(p["gos"]) == max(1, len(sends)), (run, w, "each action once, or none in this run", p["gos"])
                    if id_ == "artifacts":      # Preview and Documents, then the four groups of the Artifacts section with their counts
                        assert len(p["gos"]) == 5 and all(x.startswith(w) for x, w in zip(p["gos"], ["Run plan", "Guides", "Website", "Documents", "Run records"])) \
                            and all(re.search(r"\d|no |nothing|loading", x) for x in p["gos"]), (run, w, p["gos"])
                assert set(t_ for p in r["panels"].values() for t_ in p["tabs"]) == {t_ for v in want_tabs.values() for t_ in v}, (run, w, "no tab is lost")
                assert r["pick"] == [True, True, True] and r["graph"] == [True, "line", True] and r["chat"] is True, (run, w, "a tab opens in the main area; Run graph opens the Map's graph; Chat opens the Simple view", r["pick"], r["graph"], r["chat"])
                seen += 1
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, runs_
    print(f"icon rail: eleven labelled items and the theme, bots with hats in front, label colours per theme, reduced motion; Chrome on {len(runs)} runs x 1440x900 and 390x844 "
          f"({seen} pages), light and dark: no error, no sideways scroll, focus face and label, every panel's status line and tabs, focus kept and returned, Esc, Close and outside close, "
          "tab picks, Run graph, Chat to Simple, badges from the records, Validator shown as Gatekeeper ok")

def chat_panel():
    """The full view's chat (docs/mocks/j2-detailed-rail-mock.html): a panel that slides in from the right. Static: the pill, the panel's header, filters and an
    aria-live log; the input asks the Client Lead; reduced motion makes it instant; the rail's Chat item is now Simple view. With Chrome (--browser), on two saved runs
    at 1440x900 and 390x844, light and dark: no page error and no sideways scroll; closed, the main area has the full width and the pill shows every message as unread;
    open, the main area shrinks (1440) or the panel covers it (phone), the pill reads Hide chat, sits beside the panel and never covers the input, the count clears and
    the focus is in the panel; Esc and the X close it and give the focus back to the pill; every message has its sender's avatar (the rail's bot, the Gatekeeper's cap,
    You) and role; All, With you and Between the team show the messages the records say; a long message folds and Show more opens it; the text is 4.5:1."""
    import html as htmllib
    import threading
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    for x in ('id="chatfab" aria-expanded="false" aria-controls="chatp"', 'id="chatx" aria-label="Close chat"', 'data-cf="all">All<', 'data-cf="you">With you<', 'data-cf="team">Between the team<',
              'id="msgs" role="log" aria-live="polite"', '"Ask your Client Lead for a change…"', 'data-name="Simple view"', "@media (prefers-reduced-motion:reduce){#dview .dcol,#dview .chat,.chatfab{transition:none!important}}"):
        assert x in ui, ("chat panel markup", x)
    assert 'data-name="Chat"' not in ui, "the rail's Chat item is Simple view now"
    chrome = j2.j2_check.find_chrome()
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    if not (chrome and BROWSER and names):
        print("chat panel: static checks ok (browser steps skipped: Chrome not found, no saved run, or --fast without --browser)")
        return
    def chat_of(n):
        f = os.path.join(repo, n, "chat.jsonl")
        return [json.loads(x) for x in open(f, encoding="utf-8") if x.strip()] if os.path.isfile(f) else []
    # pinned: "the newest run with a long message" moved every time a real run was saved (runs/j2-20261111-124718);
    # the search is the fallback for a clone without these runs
    long_ = next((n for n in ("j2-20261111-013315", "j2-20261109-182842") if n in names), None) or next((n for n in reversed(names) if any(m.get("who") not in ("system", None) and not m.get("meta") and len(m.get("text") or "") > 280 for m in chat_of(n))), None)
    runs = list(dict.fromkeys([n for n in ("j2-20261026-174314", long_) if n and n in names])) or names[-1:]
    role = {"identity": "Client Lead", "adaptation": "Planner", "priority": "Budget lead", "coordination": "Scheduler", "audit": "Quality check", "validator": "checks before work starts", "user": "", "builder": "Builder"}
    head = "<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message))); try { localStorage.clear(); } catch (x) {}</script>"
    probe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), r = {};"
             " const fin = () => document.getAnimations().forEach(a => { try { a.finish(); } catch (x) {} }), box = e => { const b = e.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom, b.width]; };"
             " const lum = c => { const f = /^color\\(srgb/.test(c), v = (c.replace(/^color\\(srgb/, '').match(/[\\d.]+/g) || []).slice(0, 3).map(x => { x = f ? +x : x / 255; return x <= .03928 ? x / 12.92 : ((x + .055) / 1.055) ** 2.4; }); return .2126 * v[0] + .7152 * v[1] + .0722 * v[2]; };"
             " const ct = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }, bg = e => { while (e) { const c = getComputedStyle(e).backgroundColor; if (c && !/rgba\\(0, 0, 0, 0\\)|transparent/.test(c)) return c; e = e.parentElement; } return 'rgb(255, 255, 255)'; };"
             " const hit = (a, b) => a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3];"
             " await wait(2500); fin(); r.err0 = __e.slice(); r.closed = {on: S('dview').classList.contains('chaton'), main: box(S('dview').querySelector('.dcol'))[4], pill: S('chatfab').querySelector('span').textContent, unread: S('unread').hidden ? 0 : S('unread').textContent,"
             "   vis: getComputedStyle(S('chatp')).visibility, want: (state.allChat || []).filter(m => m.who !== 'system').length};"
             " r.msgs = q('#msgs .msg').map(e => [e.dataset.id, e.dataset.who, e.querySelector('.who b').textContent.trim(), (e.querySelector('.role') || {}).textContent || '', e.querySelector('.ava svg') ? [...e.querySelector('.ava svg').querySelectorAll('[class]')].map(x => x.getAttribute('class')).join(' ') : 'letters:' + e.querySelector('.ava').textContent]);"
             " r.toyou = q('#msgs .msg.touser').map(e => e.dataset.id); r.log = [S('msgs').getAttribute('role'), S('msgs').getAttribute('aria-live')];"
             " S('chatfab').click(); fin(); await wait(50); fin();"
             " r.open = {on: S('dview').classList.contains('chaton'), main: box(S('dview').querySelector('.dcol'))[4], pill: S('chatfab').querySelector('span').textContent, unread: S('unread').hidden, focus: S('chatp').contains(document.activeElement),"
             "   panel: box(S('chatp')), fab: getComputedStyle(S('chatfab')).display === 'none' ? null : box(S('chatfab')), input: box(S('box')), send: box(S('send')), vis: getComputedStyle(S('chatp')).visibility, sw: [document.documentElement.scrollWidth, innerWidth]};"
             " r.filters = {}; for (const f of ['you', 'team', 'all']){ q('[data-cf=' + f + ']')[0].click(); r.filters[f] = [q('#msgs .msg').filter(e => e.getClientRects().length).map(e => e.dataset.id), q('#msgs .msg.cont .who').length, q('[data-cf]').map(b => b.getAttribute('aria-pressed')).join()]; }"
             " const c = q('#msgs .text.clip')[0]; r.fold = c ? [c.scrollHeight > c.clientHeight + 4, c.nextElementSibling.textContent] : null; if (c){ c.nextElementSibling.click(); r.fold.push(!c.classList.contains('clip'), c.nextElementSibling.textContent, c.nextElementSibling.getAttribute('aria-expanded')); }"
             " r.themes = {}; for (const th of ['light', 'dark']){ THEME = th; themeApply(); await wait(20); const pr = []; for (const sel of ['#msgs .msg:not(.user) .text', '#msgs .msg.user .text', '#msgs .who b', '#msgs .role', '#msgs .tag.ok', '#msgs .tag.bad', '#msgs .tag.to', '.chat .ch b', '#chatfab']){"
             "   const e = q(sel)[0]; if (e) pr.push([sel, +ct(getComputedStyle(e).color, bg(e)).toFixed(2)]); } r.themes[th] = pr; }"
             " document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})); fin(); r.esc = [S('dview').classList.contains('chaton'), document.activeElement === S('chatfab'), S('dview').querySelector('.dcol').getBoundingClientRect().width, getComputedStyle(S('chatp')).visibility];"
             " S('chatfab').click(); fin(); S('chatx').click(); fin(); r.x = [S('dview').classList.contains('chaton'), document.activeElement === S('chatfab'), localStorage.getItem('j2chat')];"
             " r.err = __e.slice(); (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify(r)); })()")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-chat-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    wrap = {}

    class Wrap(j2_server.Handler):      # a phone-width frame, same origin (headless Chrome's window is at least 500px wide)
        def do_GET(self):
            return self._send(200, wrap["page"], "text/html") if self.path.startswith("/wrap") else super().do_GET()
    keep_here, runs_ = j2_server.HERE, j2.RUNS_DIR
    j2_server.HERE, j2.RUNS_DIR = tmp, repo
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), Wrap)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base, seen, folded = f"http://127.0.0.1:{srv.server_address[1]}", 0, 0
    try:
        for run in runs:
            chat = [m for m in chat_of(run) if not m.get("meta") and m.get("who") != "system"]
            you = [str(m["id"]) for m in chat if m["who"] == "user" or m.get("to_user") or m.get("audience") == "user"]
            team = [str(m["id"]) for m in chat if str(m["id"]) not in you]
            for w, h in ((1440, 900), (390, 844)):
                url = f"/?view=detail&run={run}"
                if w < 500:
                    wrap["page"] = f'<!doctype html><body style="margin:0"><iframe src="{url}" style="width:{w}px;height:{h}px;border:0;display:block"></iframe></body>'
                    url = "/wrap"
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--window-size={max(w, 500)},{h}", "--virtual-time-budget=30000", "--dump-dom", base + url],
                                 capture_output=True, text=True, timeout=180).stdout
                hit = re.search(r'data-r="([^"]*)"', dom)
                assert hit, (run, w, "the page did not finish its steps", dom[-300:])
                r = json.loads(htmllib.unescape(hit.group(1)))
                assert not r["err"], (run, w, r["err"])
                c, o = r["closed"], r["open"]
                assert not c["on"] and c["pill"] == "Chat" and c["vis"] == "hidden" and str(c["unread"]) == (str(c["want"]) if c["want"] <= 99 else "99+") and c["want"] == len(chat), (run, w, "closed: Chat pill with every message unread", c, len(chat))
                assert o["on"] and o["pill"] == "Hide chat" and o["unread"] and o["focus"] and o["vis"] == "visible" and o["sw"][0] <= o["sw"][1], (run, w, "open: Hide chat, count cleared, focus in the panel", o)
                assert o["fab"] is None or not (o["fab"][0] < o["input"][2] and o["input"][0] < o["fab"][2] and o["fab"][1] < o["input"][3] and o["input"][1] < o["fab"][3]) \
                    and not (o["fab"][0] < o["send"][2] and o["send"][0] < o["fab"][2] and o["fab"][1] < o["send"][3] and o["send"][1] < o["fab"][3]), (run, w, "the pill never covers the input", o["fab"], o["input"], o["send"])
                if w >= 1000:
                    assert c["main"] - o["main"] > 400 and o["fab"][2] <= o["panel"][0] and o["panel"][2] <= w, (run, w, "the main area shrinks for the panel; the pill sits beside it", c["main"], o["main"], o["fab"], o["panel"])
                else:
                    assert o["fab"] is None and o["panel"][2] <= w + 1 and o["panel"][0] >= 0, (run, w, "on a phone the panel covers the main area; its X closes it", o)
                assert r["esc"][:2] == [False, True] and abs(r["esc"][2] - c["main"]) < 2 and r["esc"][3] == "hidden" and r["x"] == [False, True, "0"], (run, w, "Esc and the X close it, the focus goes back to the pill, the choice is kept", r["esc"], r["x"])
                assert r["log"] == ["log", "polite"]
                assert [m[0] for m in r["msgs"]] == [str(m["id"]) for m in chat], (run, w, "every message once, in order")
                for (id_, who_, name_, role_, ava), m in zip(r["msgs"], chat):
                    k = m["who"]
                    want_name = "Gatekeeper" if k == "validator" else "You" if k == "user" else None
                    assert who_ == k and (want_name is None or name_ == want_name) and role_ == role.get(k, "builds one job" if re.fullmatch(r"W-\d+", k) else ""), (run, id_, k, name_, role_)
                    if k in ("identity", "adaptation", "priority", "coordination", "audit"):
                        assert ava.startswith("body hb hv eyes") and "alert" not in ava and {"identity": "headset", "adaptation": "glasses", "priority": "coin", "coordination": "hathard", "audit": "monocle"}[k] in ava, (run, id_, k, ava)
                    elif k == "validator":
                        assert "capd capb" in ava and "brows" in ava, (run, id_, ava)
                    elif k == "user":
                        assert ava == "youc yout", (run, id_, ava)
                assert sorted(r["toyou"]) == sorted(str(m["id"]) for m in chat if m.get("to_user") or m.get("audience") == "user"), (run, w, "messages to you are outlined")
                assert r["filters"]["you"][0] == you and r["filters"]["team"][0] == team and r["filters"]["all"][0] == [str(m["id"]) for m in chat], (run, w, "the filters show the records' messages")
                assert [v[2] for v in r["filters"].values()] == ["false,true,false", "false,false,true", "true,false,false"]
                if any(len(m.get("text") or "") > 280 for m in chat):
                    assert r["fold"] and r["fold"][0] and r["fold"][1] == "Show more" and r["fold"][2:] == [True, "Show less", "true"], (run, w, "a long message folds behind Show more", r["fold"])
                    folded += 1
                for th, pr in r["themes"].items():
                    assert all(v >= 4.5 for k_, v in pr), (run, w, th, "chat text 4.5:1", pr)
                seen += 1
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, runs_
    print(f"chat panel: pill, header, filters, aria-live log, Client Lead input, reduced motion, rail item Simple view; Chrome on {len(runs)} runs x 1440x900 and 390x844 ({seen} pages): "
          f"no error, main width shrinks and comes back, pill beside the panel and off the input, unread count clears on open, focus in and back, Esc and X close, avatars and roles "
          f"for every message, All / With you / Between the team from the records, Show more ({folded} pages), text 4.5:1 in light and dark ok")


def function_chat():
    """One-on-one chat with each function (activity/1 and /api/ask): with a function's view open (Identity, Adaptation, Priority, Coordination, Audit),
    the panel is "<Function> chat" with a count chip, its role and "answers from the run's records", a toggle <Function> | Whole chat (aria-pressed),
    a "Show AI calls and thinking" switch (off: messages only), the function's feed and an Ask box with its note; a question is answered from the records.
    Whole chat brings back the Team chat, its filters and the Client Lead input, and the toggle goes back. Map, Artifacts and Settings show the Team chat
    with no toggle. No text links in the header, nothing wraps at 390px, and the new controls read 4.5:1 in light and dark."""
    import html as htmllib
    import threading
    import j2_server
    import j2_agent as AG
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    head_ = ui[ui.index('<section class="chat" id="chatp"'):ui.index('id="msgs"')]
    for x in ('id="chseg" role="group"', 'data-chmode="fn"', 'data-chmode="all">Whole chat<', 'role="switch" id="chthink"', ">Show AI calls and thinking<", 'id="chatcnt"',
              ">Answers from this run's records. It cannot change the run.<"):
        assert x in ui, ("function chat markup", x)
    assert "linkbtn" not in head_ and "data-agent" not in head_ and "data-chatall" not in ui and "data-chatonly" not in ui, "no text links in the chat header"
    chrome = j2.j2_check.find_chrome()
    repo = os.path.join(here, "runs")
    run = "j2-20261106-184848"
    if not (chrome and BROWSER and os.path.isfile(os.path.join(repo, run, "chat.jsonl"))):
        print("function chat: static checks ok (browser steps skipped: Chrome not found, run missing, or --fast without --browser)")
        return
    tabs = {"identity": "goal", "adaptation": "planmap", "priority": "priorities", "coordination": "timeline", "audit": "audit"}
    names = {"identity": "Identity", "adaptation": "Adaptation", "priority": "Priority", "coordination": "Coordination", "audit": "Audit"}
    want = {k: [e["kind"] for e in AG.activity(os.path.join(repo, run), k)["events"]] for k in tabs}
    head = "<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message))); try { localStorage.clear(); localStorage.setItem('j2chat', '1'); } catch (x) {}</script>"
    probe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), r = {fns: {}};"
             " const lum = c => { const f = /^color\\(srgb/.test(c), v = (c.replace(/^color\\(srgb/, '').match(/[\\d.]+/g) || []).slice(0, 3).map(x => { x = f ? +x : x / 255; return x <= .03928 ? x / 12.92 : ((x + .055) / 1.055) ** 2.4; }); return .2126 * v[0] + .7152 * v[1] + .0722 * v[2]; };"
             " const ct = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }, bg = e => { while (e) { const c = getComputedStyle(e).backgroundColor; if (c && !/rgba\\(0, 0, 0, 0\\)|transparent/.test(c)) return c; e = e.parentElement; } return 'rgb(255, 255, 255)'; };"
             " const vis = id => !S(id).hidden && S(id).getClientRects().length > 0, until = async f => { for (let i = 0; i < 60 && !f(); i++) await wait(100); };"
             " const look = () => ({title: S('chath').textContent, sub: S('chatsub').textContent, cnt: vis('chatcnt') ? S('chatcnt').textContent : '', seg: vis('chseg'), pressed: q('[data-chmode]').map(b => b.dataset.chmode + ':' + b.getAttribute('aria-pressed')).join(),"
             "   segname: S('chsegfn').textContent, sw: vis('chsw'), on: S('chthink').checked, feed: vis('chatfeed'), msgs: vis('msgs'), filters: vis('cfil'), note: vis('asknote'), ph: S('box').placeholder, dis: S('box').disabled,"
             "   kinds: q('#chatfeed .msg').map(e => e.classList.contains('fev') ? [...e.classList].find(c => c.startsWith('f-')).slice(2) : 'msg'), links: q('#chatp .ch a, #chatp .ch .linkbtn, #chseg .linkbtn, #chsw .linkbtn').length,"
             "   wraps: ['chath', 'chatsub', 'chseg', 'chsw'].filter(id => { const e = S(id); return vis(id) && (e.scrollWidth > e.clientWidth + 1 || e.getBoundingClientRect().height > 46); }), sw_: document.documentElement.scrollWidth <= innerWidth});"
             " await wait(2500);"
             " for (const [fn, tab] of Object.entries(" + json.dumps(tabs) + ")){ showTab(tab); await until(() => FEED.who === fn && FEED.found); await wait(200); const a = look();"
             "   S('chthink').click(); await wait(200); const b = look(); S('chthink').click(); await wait(100);"
             "   q('[data-chmode=all]')[0].click(); await wait(100); const c = look(); q('[data-chmode=fn]')[0].click(); await wait(100); const d = look();"
             "   S('chseg').querySelector('[data-chmode=all]').focus(); const fo = getComputedStyle(document.activeElement).outlineStyle;"
             "   r.fns[fn] = {a, b, c, d, focus: [document.activeElement.dataset.chmode, fo]}; }"
             " showTab('priorities'); await until(() => FEED.who === 'priority' && FEED.found); S('box').value = 'Why did you grant the workflows?'; await send(); await until(() => q('#chatfeed .msg.user').length && !/Thinking/.test(S('chatfeed').lastElementChild.textContent));"
             " const last = q('#chatfeed .msg').slice(-2); r.ask = [last[0].dataset.who, last[0].querySelector('.text').textContent, last[1].dataset.who, last[1].querySelector('.text').textContent.slice(0, 40), last[1].querySelector('.tag') ? last[1].querySelector('.tag').textContent : ''];"
             " r.other = {}; for (const t of ['map', 'artifacts', 'runsettings']){ showTab(t); r.other[t] = look(); }"
             " r.themes = {}; showTab('priorities'); await wait(100); if (!S('chthink').checked) S('chthink').click(); await wait(100); for (const th of ['light', 'dark']){ THEME = th; themeApply(); await wait(30); const pr = [];"
             "   for (const sel of ['#chath', '#chatsub', '#chatcnt', '#chseg [aria-pressed=true]', '#chseg [aria-pressed=false]', '#chsw span', '#asknote', '#chatfeed .tag.kind']){ const e = q(sel)[0]; if (e) pr.push([sel, +ct(getComputedStyle(e).color, bg(e)).toFixed(2)]); }"
             "   r.themes[th] = pr; }"
             " r.err = __e.slice(); (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify(r)); })()")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-fnchat-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    wrap = {}

    class Wrap(j2_server.Handler):      # a phone-width frame, same origin (headless Chrome's window is at least 500px wide)
        def do_GET(self):
            return self._send(200, wrap["page"], "text/html") if self.path.startswith("/wrap") else super().do_GET()
    keep_here, runs_ = j2_server.HERE, j2.RUNS_DIR
    j2_server.HERE, j2.RUNS_DIR = tmp, repo
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), Wrap)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base = f"http://127.0.0.1:{srv.server_address[1]}"
    try:
        for w, h in ((1440, 900), (390, 844)):
            url = f"/?view=detail&run={run}"
            if w < 500:
                wrap["page"] = f'<!doctype html><body style="margin:0"><iframe src="{url}" style="width:{w}px;height:{h}px;border:0;display:block"></iframe></body>'
                url = "/wrap"
            dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--window-size={max(w, 500)},{h}", "--virtual-time-budget=60000", "--dump-dom", base + url],
                             capture_output=True, text=True, timeout=240).stdout
            hit = re.search(r'data-r="([^"]*)"', dom)
            assert hit, (w, "the page did not finish its steps", dom[-300:])
            r = json.loads(htmllib.unescape(hit.group(1)))
            assert not r["err"], (w, r["err"])
            for fn, v in r["fns"].items():
                a, b, c, d, nm = v["a"], v["b"], v["c"], v["d"], names[fn]
                msgs, every = want[fn].count("msg"), len(want[fn])
                assert a["title"] == nm + " chat" and a["cnt"] == str(msgs) and a["sub"].endswith(" · answers from the run's records") and a["seg"] and a["segname"] == nm \
                    and a["pressed"] == "fn:true,all:false" and a["sw"] and not a["on"] and a["feed"] and not a["msgs"] and not a["filters"] and a["note"] \
                    and a["ph"] == f"Ask {nm} about this run…" and not a["dis"], (w, fn, "the function's chat: title, chip, toggle, switch off, feed and Ask box", a)
                assert a["kinds"] == ["msg"] * msgs, (w, fn, "switch off: messages only", a["kinds"][:8])
                assert b["on"] and len(b["kinds"]) == every and b["cnt"] == str(every), (w, fn, "switch on: the AI calls and thinking too", b["kinds"][:8], every)
                assert c["title"] == "Team chat" and c["sub"] == "Client Lead and the team, as it happens" and c["seg"] and c["pressed"] == "fn:false,all:true" and not c["sw"] and c["msgs"] and not c["feed"] \
                    and c["filters"] and not c["note"] and not c["cnt"] and "Client Lead" in c["ph"], (w, fn, "Whole chat: the Team chat, its filters and the Client Lead input", c)
                assert d == a, (w, fn, "the toggle goes back to the function's chat", d)
                assert a["links"] == 0 and not a["wraps"] and not c["wraps"] and a["sw_"], (w, fn, "no links in the header, nothing wraps, no sideways scroll", a["wraps"], c["wraps"])
                assert v["focus"][0] == "all" and v["focus"][1] != "none", (w, fn, "the toggle takes the focus with a visible ring", v["focus"])
            assert r["ask"][0] == "user" and r["ask"][1] == "Why did you grant the workflows?" and r["ask"][2] == "priority" and r["ask"][3].startswith("From the records") and r["ask"][4] == "from its records, no AI call", (w, "a question is answered from the records", r["ask"])
            for t, o in r["other"].items():
                assert o["title"] == "Team chat" and not o["seg"] and not o["sw"] and o["filters"] and o["msgs"] and not o["note"], (w, t, "a page with no function keeps the Team chat, no toggle", o)
            for th, pr in r["themes"].items():
                assert len(pr) == 8 and all(x >= 4.5 for _, x in pr), (w, th, "the chat controls 4.5:1", pr)
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, runs_
    print("function chat: Identity, Adaptation, Priority, Coordination and Audit each open their chat (title and count, toggle, switch off: messages only, on: every record, feed, Ask box "
          "and its note); a question answered from the records; Whole chat and back; Map, Artifacts and Settings keep the Team chat with no toggle; no header links, no wrap at 390, focus ring, 4.5:1 in light and dark ok")

def view_kept():
    """The view is kept (Simple only on a fresh visit with no view chosen): ?view= in the URL plus a per-viewer preference. With Chrome (--browser), on saved
    runs: a fresh visit with no preference opens Simple; from the detailed view, opening another run from Run settings stays detailed and the URL names the run and
    the view; a reload keeps it; the rail's Simple view item and the team card's "Open detailed view" switch both ways, and each choice survives a reload."""
    import html as htmllib
    import threading
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    assert 'location.search = viewHref(b.dataset.openrun === RUNS.live ? "" : b.dataset.openrun);' in ui and "location.search = viewHref(\"\")" in ui, "run links keep the view"
    chrome = j2.j2_check.find_chrome()
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    if not (chrome and BROWSER and len(names) >= 2):
        print("view kept: static checks ok (browser steps skipped: Chrome not found, fewer than two saved runs, or --fast without --browser)")
        return
    a_, b_ = names[-1], names[-2]
    # one tab, several page loads: the steps and results live in sessionStorage; the first load starts with no preference
    head = ("<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message))); try { if (!sessionStorage.getItem('vk')){ localStorage.clear(); sessionStorage.setItem('vk', '[]'); } } catch (x) {}</script>")
    probe = ("(async () => { const wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), log = JSON.parse(sessionStorage.getItem('vk') || '[]');"
             " const v = () => document.body.classList.contains('simple') ? 'simple' : 'detail', u = () => new URLSearchParams(location.search), rec = k => log.push([k, v(), u().get('view'), u().get('run') || '', __e.length]);"
             " const save = () => sessionStorage.setItem('vk', JSON.stringify(log)), done = () => { save(); document.body.setAttribute('data-r', JSON.stringify(log)); };"
             " const step = log.length ? log[log.length - 1][0] : '';"
             " if (u().get('fresh')){ rec('fresh'); return done(); }"
             " if (!step){ rec('start'); showTab('runsettings'); for (let i = 0; i < 50 && !RUNS.all.length; i++) await wait(100); RUNS.show = 1e4; renderRuns(); const o = document.querySelector('#runlist [data-openrun=\"" + b_ + "\"]');"
             "   if (!o){ rec('no-run-row'); return done(); } save(); o.click(); return; }"
             " if (step === 'start'){ rec('opened'); save(); location.reload(); return; }"
             " if (step === 'opened'){ rec('reloaded'); S('gochat').click(); rec('to-simple'); save(); location.reload(); return; }"
             " if (step === 'to-simple'){ rec('simple-reloaded'); S('steamfull').click(); rec('to-detail'); save(); location.reload(); return; }"
             " if (step === 'to-detail'){ rec('detail-reloaded'); return done(); } })()")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-view-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    keep_here, runs_ = j2_server.HERE, j2.RUNS_DIR
    j2_server.HERE, j2.RUNS_DIR = tmp, repo
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base = f"http://127.0.0.1:{srv.server_address[1]}"
    def run_(url):
        dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", "--window-size=1440,900", "--virtual-time-budget=60000", "--dump-dom", base + url], capture_output=True, text=True, timeout=240).stdout
        hit = re.search(r'data-r="([^"]*)"', dom)
        assert hit, (url, "the page did not finish its steps", dom[-300:])
        return json.loads(htmllib.unescape(hit.group(1)))
    try:
        fresh = run_(f"/?fresh=1&run={a_}")
        assert fresh == [["fresh", "simple", "simple", a_, 0]], ("a fresh visit with no preference opens the Simple view", fresh)
        got = run_(f"/?view=detail&run={a_}")
        want = [["start", "detail", "detail", a_, 0], ["opened", "detail", "detail", b_, 0], ["reloaded", "detail", "detail", b_, 0], ["to-simple", "simple", "simple", b_, 0],
                ["simple-reloaded", "simple", "simple", b_, 0], ["to-detail", "detail", "detail", b_, 0], ["detail-reloaded", "detail", "detail", b_, 0]]
        assert got == want, ("the view is kept across a run switch and reloads; the two switches work both ways", got)
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, runs_
    print(f"view kept: a fresh visit opens Simple; from the detailed view another run opens detailed ({a_} -> {b_}); reloads keep the view; Simple view and "
          "Open detailed view switch both ways and survive a reload; no page error ok")

def run_settings():
    """Run settings (docs/mocks/j2-run-settings-mock.html): no What to build and no Back to simple view; Appearance as three cards; the run list from
    /api/runlist (j2_server.run_list) against the records on every saved run: each run once, newest first, its ID, title (goal.json site_name, else the
    statement's first sentence, else the ID), status (summary.json status: done*, stopped/crashed/stuck/out_of_budget or no summary -> stopped, the
    live run while it runs -> running). With Chrome (--browser) at 1440x900 and 390x844, light and dark: the current run is highlighted, the chips'
    counts are the records', a full run ID finds exactly that run, 50+ runs load 20 at a time, a Running row (one run marked running) is as tall as a
    normal row and the list stacks from the top, the page's scroll height is the window's and only the list scrolls, text 4.5:1, no page error."""
    import collections
    import html as htmllib
    import threading
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    rs = ui[ui.index('id="pane-runsettings"'):ui.index('id="pane-rundetails"')]
    assert "What to build" not in ui and "Back to simple view" not in ui and 'id="outsel"' not in ui and 'id="runsel"' not in ui, "the old controls are gone"
    assert rs.count("data-themepick=") == 3 and "Applies to this browser only." in rs and all(f'class="sw sw-{k}"' in rs for k in "lds"), "Appearance: three cards with swatches"
    assert [x for x in re.findall(r'data-rf="(\w+)"', rs)] == ["all", "running", "done", "stopped"] and 'id="runq"' in rs and 'id="reset"' in rs
    repo = os.path.join(here, "runs")
    keep_runs = j2.RUNS_DIR
    j2.RUNS_DIR = repo
    try:
        got = j2_server.run_list()
        names = sorted((n for n in os.listdir(repo) if j2.saved_dir(n) and os.path.isfile(os.path.join(repo, n, "chat.jsonl"))), reverse=True) if os.path.isdir(repo) else []
    finally:
        j2.RUNS_DIR = keep_runs
    def want(n):
        d = os.path.join(repo, n)
        rd = lambda f: json.load(open(os.path.join(d, f))) if os.path.isfile(os.path.join(d, f)) else {}
        st = str((rd("summary.json") or {}).get("status") or "")
        g = rd("goal.json") or {}
        stmt = re.split(r"(?<=[.!?])\s", str(g.get("statement") or "").strip())[0]
        return {"status": "done" if st.startswith("done") else "stopped", "title": str(g.get("site_name") or "").strip() or (stmt[:70] + ("…" if len(stmt) > 70 else "")) or n}
    ids = [x["id"] for x in got["runs"]]
    assert sorted(ids) == sorted(names) and len(ids) == len(set(ids)), ("every saved run once", sorted(set(ids) ^ set(names)))
    assert [x["when"] for x in got["runs"]] == sorted((x["when"] for x in got["runs"]), reverse=True), "newest first"
    for x in got["runs"]:
        w_ = want(x["id"])
        assert x["status"] == ("running" if x["id"] == got["live"] and j2_server.RUN.status == "running" else w_["status"]) and x["title"] == w_["title"], (x, w_)
        # a run's type: a built-in or local one (with its label and form), else one this clone no longer has (no label)
        known = x["output"] in j2.j2_types.names()
        assert (known or x["output"] in ("docset", "") or j2.j2_types.NAME_RE.match(x["output"])) and re.fullmatch(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d", x["when"]), x
        assert (x["label"], x["form"]) == ((j2.j2_types.info(x["output"])["label"], j2.j2_types.info(x["output"])["form"]) if known else ("", "")), x
    counts = collections.Counter(x["status"] for x in got["runs"])
    chrome = j2.j2_check.find_chrome()
    if not (chrome and BROWSER and len(names) >= 50):
        print(f"run settings: no old controls, Appearance cards; run list = the records on {len(ids)} runs ({dict(counts)}) ok (browser steps skipped: Chrome not found, fewer than 50 runs, or --fast without --browser)")
        return
    cur, mark = names[3], names[5]      # the run opened, and one marked running for the row-height check
    head = "<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message)));</script>"
    probe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), r = {};"
             " const lum = c => { const f = /^color\\(srgb/.test(c), v = (c.replace(/^color\\(srgb/, '').match(/[\\d.]+/g) || []).slice(0, 3).map(x => { x = f ? +x : x / 255; return x <= .03928 ? x / 12.92 : ((x + .055) / 1.055) ** 2.4; }); return .2126 * v[0] + .7152 * v[1] + .0722 * v[2]; };"
             " const ct = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }, bg = e => { while (e) { const c = getComputedStyle(e).backgroundColor; if (c && !/rgba\\(0, 0, 0, 0\\)|transparent/.test(c)) return c; e = e.parentElement; } return 'rgb(255, 255, 255)'; };"
             " showTab('runsettings'); for (let i = 0; i < 80 && !RUNS.all.length; i++) await wait(100); await wait(300);"
             " const rows = () => q('#runlist .runrow'), fit = () => [document.documentElement.scrollHeight, innerHeight, document.querySelector('#dview .dcol').scrollHeight <= document.querySelector('#dview .dcol').clientHeight + 1, S('runlist').scrollHeight > S('runlist').clientHeight];"
             " r.first = [rows().length, (S('runmore') || {}).textContent || '', S('runcount').textContent]; r.fit = fit();"
             " r.cur = q('#runlist .runrow.cur').map(e => [e.dataset.openrun, e.querySelector('.ropen').textContent, e.getAttribute('aria-current')]);"
             " r.chips = q('[data-rf]').map(b => [b.dataset.rf, +b.querySelector('i').textContent]);"
             " while (S('runmore')) { S('runmore').click(); }"
             " r.all = rows().map(e => [e.dataset.openrun, e.querySelector('code').textContent, e.querySelector('.rst').textContent, e.querySelector('.rt').textContent]); r.groups = q('#runlist .rgrp').map(e => e.textContent);"
             " r.sticky = getComputedStyle(q('#runlist .rgrp')[0]).position; const normal = rows()[1].getBoundingClientRect().height;"
             " S('runq').value = '" + cur + "'; S('runq').dispatchEvent(new Event('input')); r.search = [rows().map(e => e.dataset.openrun), S('runcount').textContent];"
             " S('runq').value = ''; S('runq').dispatchEvent(new Event('input')); q('[data-rf=running]')[0].click(); const one = rows();"
             " r.running = [one.map(e => e.dataset.openrun), one.length ? +one[0].getBoundingClientRect().height.toFixed(1) : 0, +normal.toFixed(1), one.length ? Math.round(one[0].getBoundingClientRect().top - S('runlist').getBoundingClientRect().top) : -1, S('runcount').textContent, q('[data-rf]').map(b => b.getAttribute('aria-pressed')).join()];"
             " r.fit1 = fit().slice(0, 3); q('[data-rf=all]')[0].click();"
             " r.themes = {}; for (const th of ['light', 'dark']){ THEME = th; themeApply(); await wait(30); const pr = [];"
             "   for (const sel of ['#runlist .runrow:not(.cur) .rt', '#runlist .runrow.cur .rt', '#runlist .rm', '#runlist code', '#runlist .rst.done', '#runlist .rst.stopped', '#runlist .rst.running', '#runlist .ropen', '#runlist .rgrp', '.rfil button[aria-pressed=true]', '.rfil button[aria-pressed=false]', '.newrun', '.themecards button']){"
             "     const e = q(sel)[0]; if (e) pr.push([sel, +ct(getComputedStyle(e).color, bg(e)).toFixed(2)]); }"
             "   r.themes[th] = [pr, fit(), q('.themecards [aria-pressed=true]').map(b => b.dataset.themepick + ':' + getComputedStyle(b).borderTopColor)]; }"
             " r.err = __e.slice(); (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify(r)); })()")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-runs-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    wrap = {}

    class Wrap(j2_server.Handler):      # a phone-width frame, same origin (headless Chrome's window is at least 500px wide)
        def do_GET(self):
            return self._send(200, wrap["page"], "text/html") if self.path.startswith("/wrap") else super().do_GET()
    keep_here, keep_list = j2_server.HERE, j2_server.run_list
    def marked():      # one run reported running, so the Running filter has a row (saved runs have none)
        o = keep_list()
        for x in o["runs"]:
            if x["id"] == mark:
                x["status"] = "running"
        return o
    j2_server.HERE, j2.RUNS_DIR, j2_server.run_list = tmp, repo, marked
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), Wrap)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base, seen = f"http://127.0.0.1:{srv.server_address[1]}", 0
    try:
        L = marked()["runs"]
        cnt = collections.Counter(x["status"] for x in L)
        for w, h in ((1440, 900), (390, 844)):
            url = f"/?view=detail&run={cur}"
            if w < 500:
                wrap["page"] = f'<!doctype html><body style="margin:0"><iframe src="{url}" style="width:{w}px;height:{h}px;border:0;display:block"></iframe></body>'
                url = "/wrap"
            dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--window-size={max(w, 500)},{h}", "--virtual-time-budget=40000", "--dump-dom", base + url],
                             capture_output=True, text=True, timeout=240).stdout
            hit = re.search(r'data-r="([^"]*)"', dom)
            assert hit, (w, "the page did not finish its steps", dom[-300:])
            r = json.loads(htmllib.unescape(hit.group(1)))
            assert not r["err"], (w, r["err"])
            n = len(L)
            assert r["first"] == [20, f"Show 20 more · {n - 20} left", f"{n} runs"], (w, "20 at a time", r["first"])
            assert [x[0] for x in r["all"]] == [x["id"] for x in L] and all(a[1] == a[0] for a in r["all"]), (w, "every run once, newest first, with its ID")
            assert [x[2] for x in r["all"]] == [x["status"] for x in L] and [x[3] for x in r["all"]] == [x["title"] for x in L], (w, "status and title from the records")
            assert r["cur"] == [[cur, "Open now", "true"]], (w, "the current run is highlighted", r["cur"])
            assert dict(r["chips"]) == {"all": n, "running": cnt["running"], "done": cnt["done"], "stopped": cnt["stopped"]}, (w, r["chips"], cnt)
            assert set(r["groups"]) <= {"Today", "Yesterday", "This week", "Earlier this month", "Older"} and r["sticky"] == "sticky", (w, r["groups"])
            assert r["search"] == [[cur], f"1 of {n} runs"], (w, "a full run ID finds exactly that run", r["search"])
            assert r["running"][0] == [mark] and r["running"][1] == r["running"][2] and 0 <= r["running"][3] <= 40 and r["running"][4] == f"1 of {n} runs" and r["running"][5] == "false,true,false,false", (w, "a lone row keeps its height, at the top", r["running"])
            for f_ in (r["fit"], r["fit1"]):
                assert f_[0] == f_[1] and f_[2], (w, "the page fits the window; only the list scrolls", f_)
            assert r["fit"][3], (w, "the list scrolls inside its card", r["fit"])
            for th, (pr, fit_, act) in r["themes"].items():
                assert all(v >= 4.5 for k_, v in pr) and len(pr) >= 12, (w, th, "readable", pr)
                assert fit_[0] == fit_[1] and fit_[2], (w, th, fit_)
                assert len(act) == 1 and act[0].startswith(th + ":"), (w, th, "the active card", act)
            seen += 1
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR, j2_server.run_list = keep_here, keep_runs, keep_list
    print(f"run settings: no What to build or Back to simple view, Appearance cards; run list = the records on {len(ids)} runs ({dict(counts)}): each once, newest first, ID, title, status; "
          f"Chrome at 1440x900 and 390x844 ({seen} pages), light and dark: current run highlighted, chip counts, search by ID finds one, 20 at a time, a lone Running row keeps its height "
          "at the top, page height = window height with only the list scrolling, text 4.5:1, no error ok")

def artifacts_groups():
    """Artifacts as four groups (docs/mocks/j2-artifacts-mock.html; j2_artifacts.groups, /api/artifacts/groups), on run j2-20261103-132506. Browser-free: each
    guide is one row per output file with its revisions as versions, each website section one row per sections.json entry with every workflow recorded on it,
    the old copies of a guide paired with its versions, a missing maker left None, tree() untouched; a file's text is escaped. With Chrome (--browser) at
    1440x900 and 390x844, light and dark: the rail panel keeps Preview and Documents and lists the four groups with counts; each group sets the title and
    subtitle; no file is fetched until its item opens; a guide's assumptions, sections, Read document and version switcher; a section's Code and a script's
    Script tab in JS, CSS and HTML blocks with line numbers and Copy; the style guide row; the audits as bars; the page's scroll height is the window's with
    no sideways scroll and only the list and the item scrolling; text 4.5:1; no emoji; no page error."""
    import collections
    import html as htmllib
    import shutil
    import threading
    import j2_server
    A = j2_artifacts
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    assert 'data-artgo="${k}"' in ui and "/api/artifacts/groups" in ui and 'b.dataset.tab === "artifacts"' in ui, "the rail lists the groups instead of one Artifacts entry"
    assert all(x not in ui for x in ("renderArtTree", "artNode(", "data-artopen=")), "the old tree view is gone"
    assert not re.search("[\U0001F300-\U0001FAFF☀-➿]", ui[ui.index("const ARTGROUPS"):ui.index("function railArtCounts")]), "no emoji in the Artifacts code"
    name = "j2-20261103-132506"
    d = os.path.join(here, "runs", name)
    if not os.path.isdir(d):
        print(f"artifacts groups: static checks ok (skipped the rest: runs/{name} not found)")
        return
    g = A.groups(d)
    G = {x["id"]: x for x in g["groups"]}
    assert [x["id"] for x in g["groups"]] == ["plan", "guides", "site", "documents", "records"] and [x["label"] for x in g["groups"]] == ["Run plan", "Guides the makers read", "Website sections", "Documents", "Run records"]
    wfs = json.load(open(os.path.join(d, "workflows.json")))
    num = lambda w: int(w.split("-")[1])
    secs = json.load(open(os.path.join(d, "sections.json")))
    want_site = {s: [s] + sorted((w["id"] for w in wfs if w.get("section") == s and w["id"] != s), key=num) for s in secs if s != "style"}
    got_site = {x["id"]: [v["workflow"] for v in x["versions"]] for x in G["site"]["rows"] if x["kind"] != "style"}
    assert got_site == want_site, ("a section's versions are the workflows recorded on it", got_site, want_site)
    assert [x["id"] for x in G["site"]["rows"]][-1] == "style" and G["site"]["rows"][-1]["maker"] == "Web Developer", "the style guide is a row under Website sections"
    outs = collections.defaultdict(list)
    for w in sorted(wfs, key=lambda w: num(w["id"])):
        if (w.get("outputs") or [""])[0].endswith(".md"):
            outs[w["outputs"][0]].append(w["id"])
    assert {x["file"]: [v["workflow"] for v in x["versions"]] for x in G["guides"]["rows"]} == {"artifacts/" + k: v for k, v in outs.items()}, "a guide: one row per file"
    arch = next(x for x in G["guides"]["rows"] if x["file"] == "artifacts/architecture.md")
    assert [(v["label"], v["workflow"]) for v in arch["versions"]] == [("first version", "W-2"), ("change 1", "W-23"), ("change 2", "W-27")], arch["versions"]
    assert [(x["label"], x["file"], x["workflow"]) for x in arch["docs"]] == [("v1", "artifacts/architecture.v1.md", "W-2"), ("v2", "artifacts/architecture.v2.md", "W-23"), ("current", "artifacts/architecture.md", "W-27")]
    assert next(x for x in G["guides"]["rows"] if x["id"] == "W-31")["maker"] is None, "no step recorded for W-31: its maker is left out, not guessed"
    eng = next(x for x in G["site"]["rows"] if x["id"] == "W-6")
    assert eng["kind"] == "script" and {r["id"] for r in eng["reused_by"]} == {w["id"] for w in wfs if "puzzle-engine" in (w.get("dependencies") or [])}, eng["reused_by"]
    last = json.load(open(os.path.join(d, "audits.json")))[-1]
    assert all(a["pass"] == next(r["pass"] for r in last["results"] if r.get("item") == a["item"]) for x in G["site"]["rows"] for a in x.get("audit") or []), "audit results are the latest audit's"
    for x in G["guides"]["rows"] + [r for r in G["site"]["rows"] if r.get("versions")]:
        for c in x["checks"]:
            w = next(w for w in wfs if w["id"] == c["workflow"])
            rs = [r for a in w["atoms"] for r in a.get("results") or []]
            assert any(r.get("check") == c["check"] and r.get("attempt", 1) == max(q.get("attempt", 1) for q in rs) for r in rs), ("checks by code: the final attempt only", c)
    assert {x["id"] for x in G["records"]["rows"] if not x["id"].startswith("A-")} == {"receipts", "audits", "conditions", "shots"} and len(next(x for x in G["records"]["rows"] if x["id"] == "audits")["audits"]) == len(json.load(open(os.path.join(d, "audits.json"))))
    assert "realization.md" == next(x for x in G["plan"]["rows"] if x["id"] == "realization")["text"] and A.groups(None)["groups"][0]["rows"] == []
    assert not re.search(r'"(head|body)":', json.dumps(g)) and "<script" not in json.dumps(g), "no file contents in the groups: they load when an item opens"
    for x in [r for G_ in g["groups"] for r in G_["rows"]] + list(g["documents"].values()):
        v = x["views"]
        assert v["summary"] is True and set(v) == {"summary", "agent", "human"}, x.get("id")
        for vv in (v["agent"], v["human"]):
            assert vv is None or A.served(d, vv["file"]), ("every file a view names is served", x.get("id"), vv)
    V = {r["id"]: r["views"] for G_ in g["groups"] for r in G_["rows"]}
    assert V["charter"]["agent"]["file"] == "goal.json" and V["realization"]["human"]["file"] == "realization.md" and V["W-5"]["agent"]["format"] == "code" \
        and V["W-2"]["agent"] == {"format": "text", "file": "artifacts/architecture.md", "schema": None, "model": None, "valid": None} and V["shots"]["agent"] is None, V
    tmpd = tempfile.mkdtemp(prefix="j2-views-")      # a teammate's Pydantic JSON beside a guide, and one for a section: picked up, served, drawn
    try:
        d2 = os.path.join(tmpd, name)
        shutil.copytree(d, d2)
        json.dump({"schema": "guide/1", "model": "ArchitectureGuide", "valid": False, "x": "<b>"}, open(os.path.join(d2, "artifacts", "architecture.json"), "w"))
        os.makedirs(os.path.join(d2, "site", "sections"))
        json.dump({"schema": "section/1", "model": "Hero", "valid": True}, open(os.path.join(d2, "site", "sections", "W-5.json"), "w"))
        g2 = A.groups(d2)
        R2 = {r["id"]: r for G_ in g2["groups"] for r in G_["rows"]}
        assert R2["W-2"]["views"]["agent"] == {"format": "json", "file": "artifacts/architecture.json", "schema": "guide/1", "model": "ArchitectureGuide", "valid": False}, R2["W-2"]["views"]
        assert R2["W-5"]["views"]["agent"]["file"] == "site/sections/W-5.json" and R2["W-5"]["views"]["agent"]["valid"] is True
        assert A.served(d2, "artifacts/architecture.json") and A.served(d2, "site/sections/W-5.json")
        if shutil.which("node"):
            out = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "artifacts": {"groups": g2, "g": "guides", "sel": {"guides": "W-2"}, "tab": "agent", "ver": ""},
                                                                 "arttext": {"artifacts/architecture.json": open(os.path.join(d2, "artifacts", "architecture.json")).read()}})["artifacts"]
            assert "ArchitectureGuide" in out and "guide/1" in out and "Invalid" in out and "Open file" in out and "&quot;&lt;b&gt;&quot;" in out and "Source text" not in out, out[-600:]
            out = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "artifacts": {"groups": g2, "g": "records", "sel": {"records": "shots"}, "tab": "agent", "ver": ""}, "arttext": {}})["artifacts"]
            assert "Not saved for this artifact yet." in out, out[-300:]
    finally:
        shutil.rmtree(tmpd, ignore_errors=True)
    for dn in [n for n in sorted(os.listdir(os.path.join(here, "runs"))) if os.path.isfile(os.path.join(here, "runs", n, "prd.md"))][-3:]:      # a document run: no website wording
        gd = A.groups(os.path.join(here, "runs", dn))
        if not os.path.isfile(os.path.join(here, "runs", dn, "site", "index.html")):
            assert gd["site"] is None and not next(x for x in gd["groups"] if x["id"] == "site")["rows"], (dn, "a document run lists no website sections")
        assert gd["documents"]["prd"]["views"]["human"] == {"format": "markdown", "file": "prd.md"}, (dn, gd["documents"]["prd"]["views"])
    if shutil.which("node"):      # escaped: a guide whose text holds markup shows it as text
        out = render_node({"workflows": [], "chat": []}, docs={"docs": {}, "artifacts": {"groups": g, "g": "guides", "sel": {"guides": arch["id"]}, "tab": "human", "ver": ""},
                                                             "arttext": {arch["file"]: "## Heading <b>x</b>\nAssumption: <img src=x onerror=alert(1)>"}})["artifacts"]
        assert "&lt;b&gt;x&lt;/b&gt;" in out and "<img src=x" not in out and "<b>x</b>" not in out, out[-400:]
    chrome = j2.j2_check.find_chrome()
    if not (chrome and BROWSER):
        print("artifacts groups: four groups from the run's files, guides by output file, sections by sections.json with their versions, maker not guessed, checks "
              "final attempt, escaped text ok (browser steps skipped: Chrome not found, or --fast without --browser)")
        return
    asm = sum("Assumption:" in l for l in open(os.path.join(d, "artifacts", "architecture.md"), encoding="utf-8"))
    heads = sum(l.startswith("## ") for l in open(os.path.join(d, "artifacts", "architecture.md"), encoding="utf-8"))
    v1 = next(l for l in open(os.path.join(d, "artifacts", "architecture.v1.md"), encoding="utf-8") if l.strip()).lstrip("# ").strip()
    head = "<script>window.__e = []; addEventListener('error', e => __e.push(String(e.message))); window.__f = []; const __of = window.fetch; window.fetch = (u, o) => { __f.push(String(u)); return __of(u, o); };</script>"
    probe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), r = window.__r = {};"
             " const lum = c => { const f = /^color\\(srgb/.test(c), v = (c.replace(/^color\\(srgb/, '').match(/[\\d.]+/g) || []).slice(0, 3).map(x => { x = f ? +x : x / 255; return x <= .03928 ? x / 12.92 : ((x + .055) / 1.055) ** 2.4; }); return .2126 * v[0] + .7152 * v[1] + .0722 * v[2]; };"
             " const ct = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }, bg = e => { while (e) { const c = getComputedStyle(e).backgroundColor; if (c && !/rgba\\(0, 0, 0, 0\\)|transparent/.test(c)) return c; e = e.parentElement; } return 'rgb(255, 255, 255)'; };"
             " const fit = () => [document.documentElement.scrollHeight, innerHeight, document.documentElement.scrollWidth <= innerWidth, document.querySelector('#dview .dcol').scrollHeight <= document.querySelector('#dview .dcol').clientHeight + 1];"
             " const contrast = sels => sels.map(sel => { const e = q(sel).find(x => x.getClientRects().length); return e ? [sel, +ct(getComputedStyle(e).color, bg(e)).toFixed(2)] : [sel, 0]; });"
             " const row = id => q('#pane-artifacts [data-agrow]').find(e => e.dataset.agrow === id), rows = () => q('#pane-artifacts [data-agrow]').map(e => e.dataset.agrow), pane = () => document.querySelector('#pane-artifacts .agpane');"
             " const files = () => __f.filter(u => /\\/api\\/(artifact\\?|code\\?)/.test(u)).map(u => decodeURIComponent((u.match(/name=([^&]+)/) || u.match(/section=([^&]+)/) || ['', ''])[1]));"
             " for (let i = 0; i < 80 && !document.querySelector('#rail [data-ri=artifacts]'); i++) await wait(100); await wait(500);"
             " document.querySelector('#rail [data-ri=artifacts]').click(); for (let i = 0; i < 80 && !ARTS.groups; i++) await wait(100); await wait(200);"
             " r.fly = [q('#rfl [data-tab]').map(b => b.dataset.tab), q('#rfl [data-artgo]').map(b => b.firstChild.textContent.trim() + '|' + b.querySelector('small').textContent)];"
             " r.flyc = contrast(['#rfl [data-artgo] small', '#rfly .rnh']);"
             " r.f0 = files().length; r.heads = {}; r.err0 = __e.slice();"
             " q('#rfl [data-artgo=guides]')[0].click(); await wait(300); r.heads.guides = [S('wtitle').textContent, S('wsub').textContent, S('rfly').hidden]; r.grows = rows();"
             " const vh = id => !S(id).hidden && S(id).getClientRects().length > 0; r.hdr = [S('wcrumb').textContent.replace(/\\s+/g, ' ').trim(), S('wcnt').textContent, vh('wcnt'), vh('backmap'), S('wtheme') === null, S('wsub').getClientRects().length === 1 && S('wsub').getBoundingClientRect().height < 24];"
             " showTab('charter'); r.hdrOther = [vh('backmap'), vh('wcrumb'), vh('wcnt')]; showTab('artifacts');"
             " row('W-2').click(); await wait(400); r.f1 = files(); r.guide = [q('.aasm .ackl li').length, q('.atoc [data-ajump]').length, !!q('.aasm')[0], pane().textContent.includes('Guides are not audited')];"
             " r.mk = row('W-31').textContent.includes('Maker not recorded');"
             " q('[data-atab=agent]')[0].click(); await wait(400); r.gagent = [pane().textContent.includes('Source text: no structured form saved yet'), !!q('.ameta a')[0] && q('.ameta a')[0].textContent, q('.agpane pre.code .ln').length > 5]; q('[data-atab=human]')[0].click(); await wait(300); r.vers = q('.avers button').map(b => b.textContent + ':' + b.getAttribute('aria-pressed')); r.doch = q('.amd h3').length; r.scrolls = pane().scrollHeight > pane().clientHeight; r.fitDoc = fit();"
             " q('.avers button')[0].click(); await wait(400); r.v1 = [q('.amd h2, .amd h3, .amd p')[0] ? q('.amd h2, .amd h3, .amd p')[0].textContent.trim() : '', files().includes('artifacts/architecture.v1.md')];"
             " q('[data-atab=sum]')[0].click(); await wait(200); q('.atoc [data-ajump]')[2].click(); await wait(300); const h2 = S('ah-2'); r.jump = [q('[data-atab=human]')[0].getAttribute('aria-selected'), !!h2 && h2.getBoundingClientRect().top >= pane().getBoundingClientRect().top - 2 && h2.getBoundingClientRect().top < pane().getBoundingClientRect().top + 80];"
             " q('#rail [data-ri=artifacts]')[0].click(); await wait(200); q('#rfl [data-artgo=site]')[0].click(); await wait(300); r.heads.site = [S('wtitle').textContent, S('wsub').textContent]; r.srows = rows();"
             " row('W-6').click(); await wait(300); r.script = [q('[data-atab]').map(b => b.textContent).join(','), pane().textContent.includes('Reused by'), !!pane().querySelector('.ashot img')];"
             " r.f2 = files().length; q('[data-atab=agent]')[0].click(); await wait(500); r.sblocks = q('.acode').map(b => b.dataset.acode + ':' + b.querySelectorAll('.ln').length + ':' + !!b.querySelector('[data-codecopy]'));"
             " row('W-5').click(); await wait(200); r.f3 = files().length; q('[data-atab=agent]')[0].click(); await wait(500); r.cblocks = q('.acode').map(b => b.dataset.acode); r.mono = getComputedStyle(q('.acode pre.code')[0]).fontFamily; r.fitCode = fit();"
             " row('W-6').click(); await wait(200); q('[data-atab=human]')[0].click(); await wait(600); r.shuman = [pane().textContent.includes('This section has no visible part; it runs behind the page'), !q('iframe.asecview').length, q('.agpane .ackl li').length]; row('W-5').click(); await wait(200); q('[data-atab=human]')[0].click(); await wait(1500); const fr = q('iframe.asecview')[0], fe = fr && fr.contentDocument.querySelector(q('[data-aselname]')[0].textContent); r.viewer = [!!fr, fr ? fr.getAttribute('sandbox') : null, !!fe && /solid/.test(fe.style.outline), !!fe && fe.getBoundingClientRect().top < fr.clientHeight && fe.getBoundingClientRect().bottom > 0]; row('style').click(); await wait(400); q('[data-atab=human]')[0].click(); await wait(500); r.style = [!!q('.astyle')[0], q('[data-atab]').map(b => b.textContent).join(',')];"
             " q('#rail [data-ri=artifacts]')[0].click(); await wait(200); q('#rfl [data-artgo=plan]')[0].click(); await wait(300); r.heads.plan = [S('wtitle').textContent, S('wsub').textContent];"
             " row('realization').click(); await wait(200); q('[data-atab=human]')[0].click(); await wait(400); r.rz = [q('.amd h2, .amd h3').length, files().includes('realization.md')];"
             " q('#rail [data-ri=artifacts]')[0].click(); await wait(200); q('#rfl [data-artgo=records]')[0].click(); await wait(300); r.heads.records = [S('wtitle').textContent, S('wsub').textContent];"
             " row('audits').click(); await wait(200); q('[data-atab=agent]')[0].click(); await wait(500); r.aagent = [q('.agpane pre.code .ln').length > 10, !!q('.ameta [data-codecopy]')[0], !!q('.ameta a')[0]]; row('shots').click(); await wait(200); q('[data-atab=agent]')[0].click(); await wait(200); r.nosaved = pane().textContent.includes('Not saved for this artifact yet.'); row('audits').click(); await wait(200); q('[data-atab=human]')[0].click(); await wait(200); r.bars = q('.abar').length; r.fit = fit(); r.listScroll = getComputedStyle(document.querySelector('.aglist')).overflowY;"
             " r.emoji = /[\\u{1F300}-\\u{1FAFF}\\u{2600}-\\u{27BF}]/u.test(S('pane-artifacts').innerText + S('rfly').innerText);"
             " r.themes = {}; for (const th of ['light', 'dark']){ THEME = th; themeApply(); await wait(30); const out = [];"
             "   for (const [g_, id] of [['guides', 'W-2'], ['site', 'W-8'], ['plan', 'charter'], ['records', 'conditions']]){ await artOpenGroup(g_, id); await wait(250);"
             "     out.push(...contrast(['#wcrumb', '#wcrumb b', '#wcnt', '.agrow.on .agt b', '.agrow:not(.on) .agt span', '.agrow .mono', '.aby', '.ablk h5', '.ackl li span', '.atabs button[aria-selected=false]', '.atabs button[aria-selected=true]', '.aasm p', '.atoc .linkbtn', '.agpane .empty', '.aev']).filter(x => x[1])); }"
             "   r.themes[th] = [out, fit()]; }"
             " r.err = __e.slice(); (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify(r)); })().catch(e => (parent !== window ? parent : window).document.body.setAttribute('data-r', JSON.stringify({err: [String(e.stack || e), Object.keys(window.__r || {}).join(',')]})))")
    page = ui.replace("<head>", "<head>" + head, 1).replace("</body>", "<script>setTimeout(() => { " + probe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-arts-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    wrap = {}

    class Wrap(j2_server.Handler):      # a phone-width frame, same origin (headless Chrome's window is at least 500px wide)
        def do_GET(self):
            return self._send(200, wrap["page"], "text/html") if self.path.startswith("/wrap") else super().do_GET()
    keep_here, keep_runs = j2_server.HERE, j2.RUNS_DIR
    j2_server.HERE, j2.RUNS_DIR = tmp, os.path.join(here, "runs")
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), Wrap)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    base, seen = f"http://127.0.0.1:{srv.server_address[1]}", 0
    counts = {x["id"]: x for x in g["groups"]}
    n_audits = sum(1 for x in counts["records"]["rows"] if x["kind"] == "audit")      # A-1, A-2, ... (agent-views/1) sit beside the four record rows
    try:
        for w, h in ((1440, 900), (390, 844)):
            url = f"/?view=detail&run={name}"
            if w < 500:
                wrap["page"] = f'<!doctype html><body style="margin:0"><iframe src="{url}" style="width:{w}px;height:{h}px;border:0;display:block"></iframe></body>'
                url = "/wrap"
            dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--window-size={max(w, 500)},{h}", "--virtual-time-budget=60000", "--dump-dom", base + url],
                             capture_output=True, text=True, timeout=300).stdout
            hit = re.search(r'data-r="([^"]*)"', dom)
            assert hit, (w, "the page did not finish its steps", dom[-300:])
            r = json.loads(htmllib.unescape(hit.group(1)))
            assert not r["err"], (w, r["err"])
            nv = sum(len(x["versions"]) for x in counts["guides"]["rows"])
            assert r["fly"][0] == ["preview", "docs"] and [x for x in r["fly"][1] if not x.startswith("Documents|")] == [f"Run plan|3 files", f"Guides the makers read|5 guides · {nv} versions", "Website sections|13 sections · 1 script", f"Run records|{4 + n_audits} records"] \
                and any(x.startswith("Documents|") for x in r["fly"][1]), r["fly"]      # agent-views/1: the Documents group sits between the sections and the records, (w, r["fly"])
            assert r["f0"] == 0 and r["f1"] == ["artifacts/product-plan.md", "artifacts/architecture.md"] and r["f2"] == 3 and r["f3"] == 4, (w, "a file loads only when its item opens (a group opens its first item)", r["f0"], r["f1"], r["f2"], r["f3"])
            assert r["heads"]["guides"][:2] == ["Guides the makers read", "Each guide, who wrote it, and how it was checked."] and r["heads"]["guides"][2] is True, (w, r["heads"])
            assert r["heads"]["site"] == ["Website sections", "Website v33: the latest audit passes 19 of 19 items."] and r["heads"]["plan"][0] == "Run plan" and r["heads"]["records"][0] == "Run records", (w, r["heads"])
            assert r["hdr"] == ["Artifacts / Guides the makers read", f"5 guides · {nv} versions", True, False, True, True], (w, "the header: breadcrumb, count chip, no Back to map, no theme button (the rail has one), a one-line subtitle", r["hdr"])
            assert r["hdrOther"] == [True, False, False], (w, "Back to map stays on the other views", r["hdrOther"])
            assert r["grows"] == [x["id"] for x in counts["guides"]["rows"]] and r["srows"] == [x["id"] for x in counts["site"]["rows"]], (w, r["grows"], r["srows"])
            assert r["guide"] == [asm, heads, True, True] and r["mk"], (w, "assumptions, sections, guides not audited, maker not recorded", r["guide"], asm, heads)
            assert r["vers"] == ["v1 · W-2:false", "v2 · W-23:false", "current · W-27:true"] and r["doch"] == heads and r["scrolls"], (w, r["vers"], r["doch"])
            assert r["v1"] == [v1, True] and r["jump"] == ["true", True], (w, "the version switcher and a section link", r["v1"], r["jump"])
            TABS = "Summary,Agent-readable,Human-readable"
            assert r["gagent"] == [True, "Open file", True], (w, "a guide with no JSON shows its source text", r["gagent"])
            assert r["shuman"][:2] == [True, True] and r["viewer"] == [True, "allow-same-origin", True, True], (w, "a script has no visible part; a section is outlined in view in the latest page", r["shuman"], r["viewer"])
            assert r["aagent"] == [True, True, True] and r["nosaved"], (w, "audits.json in the code viewer with Copy and Open file; nothing saved says so", r["aagent"], r["nosaved"])
            assert r["script"] == [TABS, True, True] and r["sblocks"] and r["sblocks"][0].split(":")[0] == "JavaScript" and int(r["sblocks"][0].split(":")[1]) >= 200 and r["sblocks"][0].endswith(":true"), (w, r["script"], r["sblocks"])
            assert r["cblocks"] == ["JavaScript", "CSS", "HTML"] and "mono" in r["mono"].lower() or "menlo" in r["mono"].lower(), (w, r["cblocks"], r["mono"])
            assert r["style"] == [True, TABS] and r["rz"][0] >= 3 and r["rz"][1] and r["bars"] == len(counts["records"]["rows"][1]["audits"]), (w, r["style"], r["rz"], r["bars"])
            for f_ in (r["fit"], r["fitDoc"], r["fitCode"]) + tuple(v[1] for v in r["themes"].values()):
                assert f_[0] == f_[1] and f_[2] and f_[3], (w, "the page fits the window with no sideways scroll; only the panes scroll", f_)
            assert r["listScroll"] == "auto" and not r["emoji"], (w, r["listScroll"], r["emoji"])
            for th, (pr, _) in r["themes"].items():
                assert len(pr) >= 30 and all(v >= 4.5 for _, v in pr), (w, th, "readable", [x for x in pr if x[1] < 4.5], len(pr))
            assert all(v >= 4.5 for _, v in r["flyc"]), (w, r["flyc"])
            seen += 1
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, keep_runs
        shutil.rmtree(tmp, ignore_errors=True)
    # document runs: every saved run with a PRD, HLD or LLD; each document and each of its sections is reachable from the rail's Documents entry and from Map links
    repo = os.path.join(here, "runs")
    docruns = [n for n in sorted(os.listdir(repo)) if any(os.path.isfile(os.path.join(repo, n, k + ".md")) for k in ("prd", "hld", "lld"))]
    dprobe = ("(async () => { const q = s => [...document.querySelectorAll(s)], wait = ms => new Promise(r => setTimeout(r, ms)), S = id => document.getElementById(id), r = {docs: {}, links: [], err: []};"
              " const vis = () => q('#dview .pane').filter(p => !p.hidden).map(p => p.id.slice(5)).join(','), inview = e => { const b = e.getBoundingClientRect(), p = S('pane-docs').getBoundingClientRect(); return b.top >= p.top - 2 && b.top < p.bottom; };"
              " for (let i = 0; i < 80 && !document.querySelector('#rail [data-ri=artifacts]'); i++) await wait(100); await wait(800);"
              " document.querySelector('#rail [data-ri=artifacts]').click(); await wait(300); q('#rfl [data-tab=docs]')[0].click(); for (let i = 0; i < 50 && !q('#pane-docs .docbody h4').length; i++) await wait(100);"
              " r.pane = vis(); for (const b of q('#pane-docs [data-doc-kind]')) r.docs[b.dataset.docKind] = q('#docblock-' + b.dataset.docKind + ' [data-head]').map(h => h.dataset.head);"
              " for (let i = 0; i < 50 && !ARTS.groups; i++) await wait(100); const D = (ARTS.groups || {}).documents || {};"
              " for (const k of Object.keys(D)){ showTab('map'); let el = await mapOpenIn('art', 'work:' + k); r.links.push(['work:' + k, vis(), el ? el.id : '', '']);"
              "   for (const [sid, h] of Object.entries(D[k].sections)){ showTab('map'); el = await mapOpenIn('art', 'sec:work:' + k + ':' + sid); r.links.push([sid, vis(), el ? (el.dataset.head || el.id) : '', h, el ? inview(el) && el.classList.contains('dlhit') && !!el.closest('#docblock-' + k) : false]); } }"
              " r.groups = D; r.err = __e.slice(); document.body.setAttribute('data-r', JSON.stringify(r)); })()")
    page = ui.replace("<head>", "<head><script>window.__e = []; addEventListener('error', e => __e.push(String(e.message)));</script>", 1).replace("</body>", "<script>setTimeout(() => { " + dprobe + " }, 1500)</script></body>")
    tmp = tempfile.mkdtemp(prefix="j2-docs-")
    open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
    os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
    j2_server.HERE, j2.RUNS_DIR = tmp, repo
    srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    nsec = 0
    try:
        for n in docruns:
            dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", "--window-size=1440,900", "--virtual-time-budget=40000", "--dump-dom",
                              f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={n}"], capture_output=True, text=True, timeout=240).stdout
            hit = re.search(r'data-r="([^"]*)"', dom)
            assert hit, (n, "the page did not finish its steps", dom[-300:])
            r = json.loads(htmllib.unescape(hit.group(1)))
            made = [k for k in ("prd", "hld", "lld") if os.path.isfile(os.path.join(repo, n, k + ".md"))]
            heads = {k: [l[3:].strip() for l in open(os.path.join(repo, n, k + ".md"), encoding="utf-8") if l.startswith("## ")] for k in made}
            assert not r["err"] and r["pane"] == "docs", (n, r["err"], r["pane"])
            assert all(r["docs"].get(k) and set(heads[k]) <= set(r["docs"][k]) for k in made), (n, "the Documents entry shows every document and its sections", r["docs"], heads)
            assert set(r["groups"]) <= set(made) and all(set(v["sections"].values()) <= set(heads[k]) for k, v in r["groups"].items()), (n, r["groups"])
            for x in r["links"]:
                if x[0].startswith("work:"):
                    assert x[1] == "docs" and x[2] == "docblock-" + x[0][5:], (n, "a document's Map link opens it in Documents", x)
                else:
                    assert x[1] == "docs" and x[2] == x[3] and x[4], (n, "a section's Map link lands on its heading in Documents, lit and in view", x)
                    nsec += 1
    finally:
        srv.shutdown()
        j2_server.HERE, j2.RUNS_DIR = keep_here, keep_runs
        shutil.rmtree(tmp, ignore_errors=True)
    print(f"artifacts groups: four groups from {name}'s files (guides by output file, sections by sections.json, versions folded, maker not guessed, checks final "
          f"attempt, escaped text); Chrome at 1440x900 and 390x844 ({seen} pages), light and dark: the rail keeps Preview and Documents and lists the groups with "
          "counts, title and subtitle per group, files load on open, three tabs (Summary, Agent-readable, Human-readable), a saved JSON picked up with its model, schema and valid mark, "
          "the section viewer outlining its first visible element, assumptions, sections, the document and its versions, Code and Script blocks with line numbers "
          "and Copy, the style guide, audit bars, page = window with only the panes scrolling, text 4.5:1, no emoji, no error; "
          f"{len(docruns)} document runs: every PRD, HLD and LLD and its sections in Documents, and {nsec} Map section links landing on their heading ok")

def graph_map():
    """Map, open team as a workflow-artifact graph (m["teams"], j2_map.team_graphs), on every saved run and every team that has workflows: no team node (the team is a
    frame label); nodes are workflows and artifacts (a section of a multi-section file is its own artifact) and every edge joins one workflow and one artifact
    (artifact -> workflow reads, workflow -> artifact makes), never two workflows; a workflow stands in a later column than every artifact it reads and before every
    artifact it makes (a read-back loop aside); every read of another workflow is an edge from an artifact or section it made, or is listed unresolved; the same run
    draws the same layout twice. Unresolved reads and cycles are printed, not hidden.
    Solar system (an artifact clicked on the Map is the sun): every section and every recorded builder and fix once, ring in run order (chat.jsonl), a workflow
    with no output in a dashed slot; with node, on every artifact: no label overlaps and no line through a label at rest, an input's focus lights only its own
    lines, a workflow's exactly its recorded reads (marked consumed), the same layout twice; every workflow as the sun: exactly its reads on the left and outputs
    on the right, artifacts only; the scale rules at their thresholds, and 24 sections with 50 workflows on one ring. With Chrome (--browser): 174314 on the real
    page at 1440x900, the walk Website -> W-8 -> Website and Esc back."""
    import html as htmllib
    import shutil
    import socket
    import subprocess
    import threading
    import j2_map as M
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    maps, unresolved, cycles, loops, teams_n, empty_n = {}, [], [], 0, 0, 0
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo
    try:
        for name in names:
            d = os.path.join(repo, name)
            m = maps[name] = M.build(d)
            again = M.build(d)
            assert json.dumps(m["teams"], sort_keys=True) == json.dumps(again["teams"], sort_keys=True), (name, "the team graphs differ between two builds")
            flows = {w["id"]: w for w in m["workflows"]}
            for t in m["teams"]:
                if not t["workflows"]:
                    empty_n += 1      # a team no workflow is on has nothing to draw: the open view keeps its old drawing
                    continue
                teams_n += 1
                nodes = {n["id"]: n for n in t["nodes"]}
                assert all(n["kind"] in ("wf", "artifact") for n in t["nodes"]) and not any(i.startswith("stage:") or i.startswith("team") for i in nodes), (name, t["id"], "a team node")
                assert {i for i, n in nodes.items() if n["kind"] == "wf"} == set(t["workflows"]), (name, t["id"], "the team's workflows are its workflow nodes")
                for e in t["edges"]:
                    a, b = nodes[e["from"]], nodes[e["to"]]
                    assert {a["kind"], b["kind"]} == {"wf", "artifact"}, (name, t["id"], "an edge between two workflows or two artifacts", e)
                    assert (a["kind"] == "artifact") == (e["kind"] == "reads"), (name, t["id"], "reads go artifact -> workflow, makes workflow -> artifact", e)
                    w, art = (b, a) if e["kind"] == "reads" else (a, b)
                    if not e["loop"] and not t["cycles"]:      # a team with a planning cycle is listed, its columns are not promised
                        assert (w["col"] > art["col"]) if e["kind"] == "reads" else (art["col"] > w["col"]), (name, t["id"], "a workflow stands after what it reads and before what it makes", e["from"], e["to"], w["col"], art["col"])
                for w in t["workflows"]:
                    got = {(e["from"], x) for e in t["edges"] if e["to"] == w and e["kind"] == "reads" for x in e["via"]}
                    lost = {u["read"] for u in t["unresolved"] if u["workflow"] == w}
                    for x in flows[w]["reads"]:
                        assert any(v == x for _, v in got) or x in lost, (name, t["id"], w, "a read that is neither an edge from what that workflow made nor listed unresolved", x)
                unresolved += [(name, t["id"], u["workflow"], u["read"], u["why"]) for u in t["unresolved"]]
                cycles += [(name, t["id"], c) for c in t["cycles"]]
                loops += len(t["loops"])
    finally:
        j2.RUNS_DIR = keep_dir
    assert teams_n > 40, ("every saved run's teams are checked", teams_n)
    if "j2-20261026-174314" in maps:      # the golden run; not on every machine (see "map tree" above)
        wd = next(t for t in maps["j2-20261026-174314"]["teams"] if t["id"] == "stage:Web Developer")
        col = {n["id"]: n["col"] for n in wd["nodes"] if n["kind"] == "wf"}
        assert col["W-6"] < col["W-7"] < col["W-8"] < col["W-9"] < col["W-10"] < col["W-14"] < col["W-15"] < col["W-17"] and col["W-7"] == col["W-13"] and col["W-9"] == col["W-11"] and col["W-10"] == col["W-12"], ("174314 Web Developer columns", col)
        assert any(n["kind"] == "artifact" and n["section"] and n["file"] == "Website" for n in wd["nodes"]) and sum(1 for n in wd["nodes"] if n["kind"] == "artifact" and n["section"]) == 10, "its Website sections are artifacts"
    # constellations (m["constellations"], j2_map.constellations): the data, on every run and every artifact
    def run_order(d, ids):
        first = {}
        for i, c in enumerate(M._jsonl(d, "chat.jsonl") or []):
            for k in ("who", "workflow"):
                if c.get(k) in ids and c[k] not in first:
                    first[c[k]] = i
        return sorted(first, key=first.get) + sorted((w for w in ids if w not in first), key=lambda w: int(w.split("-")[1])), set(first)
    arts_n, no_out, empty_slots, sec_n, fix_n = 0, [], 0, 0, 0
    for name in names:
        d = os.path.join(repo, name)
        wfs = {w["id"]: w for w in json.load(open(os.path.join(d, "workflows.json"), encoding="utf-8"))}
        no_out += [(name, w) for w, x in wfs.items() if not x.get("outputs")]
        order, ran = run_order(d, set(wfs))
        m = maps[name]
        for n in (x for x in m["nodes"] if x["kind"] == "work" and x["id"] != "work:charter"):
            C = m["constellations"][n["id"]]
            arts_n += 1
            secs = [s["section"] for s in C["slots"] if s["section"]]
            team = next((t for t in m["teams"] for x in t["nodes"] if x["id"] in secs), None)
            assert sorted(secs) == sorted(x["id"] for x in (team or {"nodes": []})["nodes"] if x.get("section") and x["file"] == n["label"] and x["id"].startswith(f"sec:{n['id']}:")), (name, n["id"], "every section of the artifact is on its ring")
            assert len(secs) == len(set(secs)), (name, n["id"], "a section twice")
            ws = [w for s in C["slots"] for w in [s["builder"]] + s["fixes"]]
            assert len(ws) == len(set(ws)) and set(ws) == set(n.get("workflows") or []), (name, n["id"], "every workflow on the artifact once, as builder or fix", ws, n.get("workflows"))
            for s in C["slots"]:
                k = (s["section"] or "").rsplit(":", 1)[-1]
                if s["section"]:
                    assert wfs[s["builder"]].get("section") == k and not wfs[s["builder"]].get("revises") or s["builder"] == k, (name, s, "the builder: section = the key, no revises")
                    assert all(wfs[f].get("section") == k for f in s["fixes"]), (name, s, "a fix names the section")
                else:
                    assert s["empty"] == bool(secs or not wfs[s["builder"]].get("outputs")), (name, s, "an empty slot: no section here, or no recorded output")
                sec_n += bool(s["section"]); fix_n += len(s["fixes"]); empty_slots += s["empty"]
            lead = [s["builder"] for s in C["slots"]]
            assert lead == sorted(lead, key=order.index), (name, n["id"], "ring order is run order (chat.jsonl)", lead)
            for w, f in C["workflows"].items():
                assert f["rank"] == order.index(w) and f["ran"] == (w in ran), (name, w, "run order and ran, from chat.jsonl")
    assert arts_n > 150, ("every artifact of every run", arts_n)
    # the page's layout (node, page script, stub DOM): every run, every artifact, at rest and every focus; and the scale rules on synthetic artifacts
    def syn(n_sec, per, n_in, empty=0, cid="work:syn"):
        """a constellation with n_sec sections (builder W-i and per(i) - 1 fixes; per a number or a function), n_in inputs from 5 teams read by the builders, empty workflows with no output"""
        per_ = per if callable(per) else (lambda i: per)
        wid, ref, makes, team_of, chat, k = {}, {}, {}, {}, [], 0
        file_secs = {cid: {}}
        arts = {cid: {"label": "Synthetic", "file": None, "sec": False}}
        for j in range(n_in):
            a, o = f"work:in{j}", f"O-{j}"
            arts[a] = {"label": f"Input {j}", "file": None, "sec": False}
            makes[o] = [a]
            team_of[o] = f"Team {j % 5}"
        for i in range(1, n_sec + 1):
            b = f"W-{i}"
            sid = f"sec:{cid}:{b}"
            file_secs[cid][b] = sid
            arts[sid] = {"label": f"Part {i} section", "file": "Synthetic", "sec": True}
            wid[b] = {"id": b, "name": f"build-{i}", "section": b, "outputs": ["index.html"]}
            ref[b] = [(f"work:in{(i - 1) % n_in}", f"O-{(i - 1) % n_in}")] if n_in else []
            makes[b] = [sid]
        k = n_sec
        for i in range(1, n_sec + 1):
            for _ in range(per_(i) - 1):
                k += 1
                f = f"W-{k}"
                wid[f] = {"id": f, "name": f"fix-{k}", "section": f"W-{i}", "revises": f"W-{i}", "outputs": ["index.html"]}
                ref[f] = [(f"sec:{cid}:W-{i}", f"W-{i}")]
        for _ in range(empty):
            k += 1
            wid[f"W-{k}"] = {"id": f"W-{k}", "name": f"empty-{k}", "outputs": []}
        ran = [f"W-{i}" for i in range(1, k + 1) if wid[f"W-{i}"].get("outputs")]
        ran = ran[:10][::-1] + ran[10:]      # the first ten ran in reverse: ring order follows the run, not the number
        chat = [{"who": w, "t": "12:00:00"} for w in ran]
        node_of = {cid: {"id": cid, "label": "Synthetic", "workflows": sorted(wid, key=lambda w: int(w[2:]))}}
        return M.constellations(wid, node_of, file_secs, arts, makes, ref, team_of, chat)
    syn24 = syn(24, lambda i: 3 if i <= 13 else 1, 6)      # 24 sections, 50 workflows: 24 builders and 26 fixes (13 sections with 2), on one ring
    assert len(syn24["work:syn"]["workflows"]) == 50 and sum(1 for s in syn24["work:syn"]["slots"] if s["section"]) == 24, "the synthetic artifact: 24 sections, 50 workflows"
    sy = {"syn24": {"constellations": syn24}, "wf3": {"constellations": syn(2, 3, 0)}, "wf4": {"constellations": syn(2, 4, 0), "states": [{"id": "work:syn", "fan": {"sec:work:syn:W-1": True}}]},
          "in12": {"constellations": syn(12, 1, 12)}, "in13": {"constellations": syn(13, 1, 13), "states": [{"id": "work:syn", "grp": {"Team 0": True}}]},
          "n100": {"constellations": syn(49, 1, 1)}, "n101": {"constellations": syn(50, 1, 0)}}
    layout_note = "node not found: layout steps skipped"
    node = shutil.which("node")
    if node:
        tmp = tempfile.mkdtemp(prefix="j2-cons-")
        try:
            run_ = lambda x: json.loads(subprocess.run([node, os.path.join(here, "j2_graph_layout.js"), os.path.join(here, "j2_ui.html"), x], capture_output=True, text=True, timeout=600, check=True).stdout)
            mp, sp = os.path.join(tmp, "maps.json"), os.path.join(tmp, "syn.json")
            json.dump(maps, open(mp, "w"), default=str)
            json.dump(sy, open(sp, "w"))
            lay, lay2, syl = run_(mp), run_(mp), run_(sp)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        import math
        arts, suns, teams = [L for L in lay if "id" in L], [L for L in lay if "wf" in L], [L for L in lay if "team" in L]
        assert lay == lay2 and len(arts) == arts_n and all(L["again"] for L in lay), ("every artifact and workflow laid out, the same twice", len(arts), arts_n)
        meets = lambda a, b: a[0] < b[2] - 0.5 and b[0] < a[2] - 0.5 and a[1] < b[3] - 0.5 and b[1] < a[3] - 0.5
        inside = lambda p, b: b[0] + 1 < p[0] < b[2] - 1 and b[1] + 1 < p[1] < b[3] - 1
        dense = lambda pts: [(pts[i][0] + (pts[i + 1][0] - pts[i][0]) * t / 20, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * t / 20) for i in range(len(pts) - 1) for t in range(21)]
        near = lambda b, n: math.hypot(max(b[0] - n["x"], 0, n["x"] - b[2]), max(b[1] - n["y"], 0, n["y"] - b[3]))
        wfish = lambda v, n: n["kind"] in ("wf", "badge") or (n["kind"] == "centre" and v["kind"] == "wf")      # a workflow, or a node standing for workflows

        def no_wf_wf(where, v, lines):      # every line has an artifact (or an input) at one end at least: never workflow to workflow
            by_ = {n["id"]: n for n in v["nodes"]}
            for a, b in lines:
                assert not (wfish(v, by_[a]) and wfish(v, by_[b])), (where, "a workflow-workflow line", a, b)

        def at_rest(where, v, ring=True):
            ids = [n["id"] for n in v["nodes"]]
            assert len(ids) == len(set(ids)), (where, "a node twice")
            assert all(isinstance(n["x"], (int, float)) and n["x"] == n["x"] for n in v["nodes"]), (where, "a node without a place")
            labs = [(n["id"], n["label"]["box"]) for n in v["nodes"] if n["label"]]
            assert not any("…" in l for n in v["nodes"] if n["label"] for l in n["label"]["lines"]), (where, "a label cut short")
            no_wf_wf(where, v, [(e["from"], e["to"]) for e in v["rest"]])
            if not v["quiet"]:
                for i, (a, p) in enumerate(labs):
                    assert not any(meets(p, q) for b, q in labs[i + 1:]), (where, "two labels overlap at rest", a)
                    assert not any(meets(p, n["box"]) for n in v["nodes"] if n["id"] != a and n["kind"] != "centre"), (where, "a label over a shape at rest", a)
                    own = next(n for n in v["nodes"] if n["id"] == a)
                    assert all(near(p, n) > near(p, own) for n in v["nodes"] if n["id"] != a), (where, "a label nearer another node than its own", a)
                for e in v["rest"]:
                    for a, p in labs:
                        assert not any(inside(q, p) for q in dense(e["pts"])), (where, "a line through a label at rest", e["from"], e["to"], a)
            if not ring:
                return []
            lead = [n for n in v["nodes"] if n["kind"] in ("section", "empty", "part") or (n["kind"] == "wf" and n["role"] == "builder" and not any(m_["slot"] == n["slot"] and m_["kind"] in ("section", "empty") for m_ in v["nodes"]))]
            angs = [(math.atan2(n["x"], -n["y"]) + 2 * math.pi) % (2 * math.pi) for n in lead]
            assert angs == sorted(angs), (where, "ring order clockwise from the top")
            return lead
        quiet_n = sec_n = 0
        for L in arts:
            C = maps[L["run"]]["constellations"][L["id"]]
            v, where = L["rest"], (L["run"], L["id"])
            lead = at_rest(where, v)
            assert [n["slot"] for n in lead] == [s["section"] or s["builder"] for s in C["slots"]], (where, "the ring is the slots in run order")
            kinds = {n["id"]: n for n in v["nodes"]}
            for s in C["slots"]:
                if s["section"]:
                    assert kinds[s["section"]]["kind"] == "section", (where, s["section"])
                    sec_ = s["label"] if s["label"].endswith(" section") else f"{s['label']} section"
                    assert " ".join(kinds[s["section"]]["label"]["lines"]) == sec_ or v["quiet"], (where, s["section"], "the section's whole name beside its diamond", kinds[s["section"]]["label"])
                    sec_n += 1
                if s["empty"]:
                    assert kinds["slot:" + s["builder"]]["kind"] == "empty", (where, "a workflow with no output has a dashed slot", s["builder"])
                many = 1 + len(s["fixes"]) > 3
                assert kinds[s["builder"]]["role"] == "builder" and (("fan:" + (s["section"] or "slot:" + s["builder"])) in kinds if many else all(kinds[f]["role"] == "fix" for f in s["fixes"])), (where, s)
            quiet_n += v["quiet"]
            stand = {}
            for s in C["slots"]:
                key = s["section"] or "slot:" + s["builder"]
                stand[s["builder"]] = s["builder"]
                for f in s["fixes"]:
                    stand[f] = ("fan:" + key) if 1 + len(s["fixes"]) > 3 else f
            node_of_art = lambda a: a if a in kinds else None
            for fid, F in L["focus"].items():
                n = kinds[fid]
                no_wf_wf(where + (fid,), v, [(a, b) for a, b, k in F["lines"]])
                reads = {(a, b) for a, b, k in F["lines"] if k == "reads"}
                if n["kind"] == "input":      # only that input's own lines: to every workflow that read it
                    want = {(fid, stand[w]) for w, f in C["workflows"].items() if fid in f["reads"]}
                    assert reads == want and F["eat"] == [fid], (where, fid, "an input lights only its own lines", reads, want)
                if n["kind"] == "wf":      # exactly its recorded reads, and those are marked consumed
                    want = {node_of_art(a) for a in C["workflows"][fid]["reads"]} - {None}
                    assert {a for a, b in reads} == want and all(b == fid for a, b in reads) and set(F["eat"]) == want, (where, fid, "a workflow lights exactly its reads", reads, want, F["eat"])
                assert set(F["eat"]) <= set(F["lit"]), (where, fid)
        # every workflow as the sun: exactly its recorded reads on the left and what it made on the right, artifacts only, no label overlaps
        for L in suns:
            m_, w, v = maps[L["run"]], L["wf"], L["rest"]
            where, reads, outs = (L["run"], w), set(), []
            for C in m_["constellations"].values():
                for s_ in C["slots"]:
                    if w in [s_["builder"]] + s_["fixes"]:
                        reads |= set(C["workflows"][w]["reads"])
                        o = s_["section"] or ("" if s_["empty"] else C["id"])
                        if o and o not in outs:
                            outs.append(o)
            got = {"L": [], "R": []}
            for n in v["nodes"]:
                if n["kind"] != "centre":
                    got["L" if n["x"] < 0 else "R"].append(n["id"].split("#")[0])      # a revision reads what it makes: it stands on both sides
            assert set(v["left"]) == reads and v["right"] == outs, (where, "a workflow's sun: its reads and its outputs", v["left"], reads, v["right"], outs)
            assert sorted(got["L"]) == sorted(set(v["left"])) and sorted(got["R"]) == sorted(outs), (where, "reads on the left, outputs on the right, each once", got)
            assert all(n["kind"] in ("centre", "section", "input") for n in v["nodes"]), (where, "only artifacts round a workflow")
            at_rest(where, v, ring=False)
        # every team as its own solar system: exactly its workflows (no team node), a star for each artifact it made (the one most of them built in the middle),
        # each workflow orbiting the star it built, the inputs from other teams; at rest and in every focus, no workflow-workflow line, labels clear and beside their own
        top_ = lambda a: ":".join(a.split(":")[1:-1]) if a.startswith("sec:") else a
        team_lines = 0
        for L in teams:
            m_, v, where = maps[L["run"]], L["rest"], (L["run"], L["team"])
            cx = {}
            for C in m_["constellations"].values():
                for w, f in C["workflows"].items():
                    x = cx.setdefault(w, {"reads": [], "outs": []})
                    x["reads"] = f["reads"]
                    for s_ in C["slots"]:
                        if w in [s_["builder"]] + s_["fixes"]:
                            o = s_["section"] or ("" if s_["empty"] else C["id"])
                            if o and top_(o) not in x["outs"]:
                                x["outs"].append(top_(o))
            arts_ = {a for C in m_["constellations"].values() for a in [C["id"]] + [s_["section"] for s_ in C["slots"] if s_["section"]]}
            wfs, tree = L["tree"]["wfs"], L["tree"]
            stars = {o for w in wfs for o in cx.get(w, {"outs": []})["outs"]} | set(tree["made"])
            inputs = {a for w in wfs for a in cx.get(w, {"reads": []})["reads"] if a in arts_ and top_(a) not in stars} | {a for a in tree["read"] if a not in stars}
            assert L["again"] and sorted(w["id"] for w in L["wfs"]) == sorted(wfs) and set(L["stars"]) == stars and set(L["inputs"]) == inputs, (where, "a team view shows exactly its workflows, its artifacts and its inputs", L["stars"], stars, L["inputs"], inputs)
            kinds = {n["id"]: n for n in v["nodes"]}
            assert not any(i.startswith("stage:") for i in kinds) and sum(n["kind"] == "centre" for n in v["nodes"]) == 1 and v["kind"] == "team", (where, "no team node, one star in the middle")
            if stars:
                assert kinds[L["stars"][0]]["kind"] == "centre" and all(kinds[a]["kind"] == "star" for a in L["stars"][1:]), (where, "the main star in the middle, the others outside the orbit")
            for w in L["wfs"]:
                assert kinds[w["id"]]["kind"] == "wf" and kinds[w["id"]]["role"] == w["role"] and (not w["built"] or w["star"] in w["built"]), (where, w, "a workflow orbits a star it built")
            assert {(e["from"], e["to"]) for e in v["rest"]} == {(w["id"], a) for w in L["wfs"] for a in w["built"] if a in kinds}, (where, "at rest, each workflow's line to what it built")
            at_rest(where, v, ring=False)
            for fid, F in L["focus"].items():
                no_wf_wf(where + (fid,), v, [(a, b) for a, b, k in F["lines"]])
                if kinds[fid]["kind"] == "wf":      # a workflow lights exactly what it read: an input, or its own team's star that holds it
                    want = {a if a in kinds else top_(a) for a in cx.get(fid, {"reads": []})["reads"] if (a if a in kinds else top_(a)) in kinds}
                    assert {a for a, b, k in F["lines"] if k == "reads"} == want and set(F["eat"]) == want, (where, fid, "a workflow lights exactly what it read", F["lines"], want)
                team_lines += len(F["lines"])
        # the scale rules, at their thresholds
        S = {(r["run"], json.dumps(r.get("state"), sort_keys=True)): r["rest"] for r in syl if "id" in r}
        rest = lambda k, st=None: S[(k, json.dumps(st, sort_keys=True))] if st else next(r["rest"] for r in syl if r["run"] == k and "id" in r and "state" not in r)
        kinds_of = lambda v, k: [n for n in v["nodes"] if n["kind"] == k]
        s24 = rest("syn24")
        assert len(kinds_of(s24, "section")) == 24 and not s24["quiet"] and len(kinds_of(s24, "wf")) == 50 and not kinds_of(s24, "badge"), "24 sections and 50 workflows: one ring, every label shown"
        assert not kinds_of(rest("wf3"), "badge") and len(kinds_of(rest("wf3"), "wf")) == 6 and len(kinds_of(rest("wf4"), "badge")) == 2 and len(kinds_of(rest("wf4"), "wf")) == 2, "over 3 workflows on a section: builder and badge"
        fan = rest("wf4", {"id": "work:syn", "fan": {"sec:work:syn:W-1": True}})
        assert len(kinds_of(fan, "badge")) == 1 and len([n for n in kinds_of(fan, "wf") if n["role"] == "fix"]) == 3, "a badge fans its fixes out"
        assert not kinds_of(rest("in12"), "group") and len(kinds_of(rest("in12"), "input")) == 12 and len(kinds_of(rest("in13"), "group")) == 5 and not kinds_of(rest("in13"), "input"), "over 12 inputs: one node per team"
        assert len(kinds_of(rest("in13", {"id": "work:syn", "grp": {"Team 0": True}}), "input")) == 3, "a team's group expands"
        assert len(rest("n100")["nodes"]) == 100 and not rest("n100")["quiet"] and len(rest("n101")["nodes"]) == 101 and rest("n101")["quiet"], "over 100 nodes: labels on hover"
        for r in syl:
            at_rest((r["run"], r.get("state"), r.get("wf")), r["rest"], ring="id" in r)
        layout_note = (f"node: {len(arts)} artifact suns at rest and in every focus, {len(suns)} workflow suns (exactly their reads left, outputs right, artifacts only) and {len(teams)} team views "
                       f"(exactly their workflows, artifacts and inputs, no team node, {team_lines} focus lines), the same twice, no workflow-workflow line, no label overlaps, cut or nearer another node "
                       f"({sec_n} section names whole beside their diamonds), no line through a label, ring in run order ({quiet_n} with labels on hover); a 24-section 50-workflow artifact on one ring with every label; badges at 3/4 workflows, groups at 12/13 inputs, hover labels at 100/101 nodes")
    # the real page (Chrome, 1440x900): 174314's Website, clicked on the Tree
    seen = {}
    run = "j2-20261026-174314"
    chrome = j2.j2_check.find_chrome()
    if chrome and BROWSER and os.path.isdir(os.path.join(repo, run)):
        ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
        js = ("const q = x => [...document.querySelectorAll(x)], ev = (el, t) => el.dispatchEvent(new MouseEvent(t, {bubbles: true})), rc = el => { const b = el.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom]; },"
              " esc = () => document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})), node = id => q('.consvg .cnode').find(x => x.dataset.cid === id), sv = () => document.querySelector('.consvg'), crumbs = () => q('.cpath b, .cpath button').length;"
              " ev(q('.tnodes > .tnode.tdeck').find(x => x.dataset.id === 'work:website'), 'click'); const s = sv(); r.open = s && s.dataset.cons;"
              " r.labels = q('.consvg .ctext').map(rc); r.fontpx = +s.dataset.fontpx; r.rest = q('.consvg .cline.lit').length; r.inLines = q('.consvg .cline.reads').length; r.sw = [document.documentElement.scrollWidth, innerWidth];"
              " r.look = [q('.consvg .csky circle').length, q('.consvg .crings > *').length, getComputedStyle(s).backgroundImage.includes('radial'), q('.consvg .k-centre .csub')[0].textContent];"
              " ev(node('W-8'), 'click'); r.glide = [q('.consvg.cmoving').length, sv().dataset.kind, sv().dataset.cons]; await wait(1000);"
              " r.w8 = [q('.consvg .cnode').filter(x => x.dataset.cid !== 'wf:W-8').map(x => x.dataset.cid + ':' + (+x.dataset.x < 0 ? 'L' : 'R')).sort(), q('.consvg .cnode.k-wf').length, crumbs(), q('.consvg.cmoving').length];"
              " ev(node('sec:work:website:W-8'), 'click'); await wait(1000); r.walk = [sv().dataset.cons, CONS.focus, crumbs(), !!document.querySelector('.conspanel')];"
              " esc(); await wait(50); r.esc1 = [CONS.focus, sv().dataset.cons]; esc(); await wait(1000); r.esc2 = sv().dataset.cons; esc(); await wait(600); r.esc3 = [sv().dataset.cons, crumbs()]; esc(); await wait(100); r.esc4 = [!!sv(), !!document.querySelector('.treesvg')];"
              " ev(q('.tnodes > .tnode.tdeck').find(x => x.dataset.id === 'work:website'), 'click'); await wait(100);"
              " ev(node('work:W-1'), 'click'); r.spec = [q('.consvg .cline.lit.reads').map(x => x.dataset.from), q('.consvg .cline.lit.reads').map(x => x.dataset.to).sort(), document.querySelector('.conspanel').textContent.includes('used by'), q('.consvg .cnode.eat').map(x => x.dataset.cid)];"
              " r.anim = getComputedStyle(q('.consvg .eat .chalo')[0]).animationName; r.far = q('.consvg .cnode.far').length;"
              " ev(sv(), 'click'); r.empty = q('.consvg.focusing').length; document.querySelector('[data-linezoom=\"1.5\"]').click(); r.zoom = sv().dataset.rel; document.querySelector('[data-linefit]').click(); r.fit = sv().dataset.rel;"
              " document.querySelector('[data-consback]').click(); r.back = [!!sv(), !!document.querySelector('.treesvg')];")

        def probe(flags=()):
            tmp = tempfile.mkdtemp(prefix="j2-consmap-")
            os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
            open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(ui.replace("</body>", "<script>setTimeout(async () => { const r = {}, wait = ms => new Promise(f => setTimeout(f, ms)); try { showTab('map'); " + js
                                                                                          + " } catch (e) { r.error = String(e.stack || e); } document.body.setAttribute('data-r', JSON.stringify(r)); }, 2500)</script></body>"))
            keep_here, keep_runs = j2_server.HERE, j2.RUNS_DIR
            j2_server.HERE, j2.RUNS_DIR = tmp, repo
            srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            prof = tempfile.mkdtemp(prefix="j2-consprof-")
            try:
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--user-data-dir={prof}", "--no-first-run", "--window-size=1440,900", "--virtual-time-budget=15000", *flags, "--dump-dom",
                                  f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={run}&mapview=tree"], capture_output=True, text=True, timeout=120).stdout
            finally:
                srv.shutdown()
                j2_server.HERE, j2.RUNS_DIR = keep_here, keep_runs
                shutil.rmtree(tmp, ignore_errors=True)
                shutil.rmtree(prof, ignore_errors=True)
            hit = re.search(r'data-r="([^"]*)"', dom)
            assert hit, ("the page did not finish its steps", dom[-300:])
            got = json.loads(htmllib.unescape(hit.group(1)))
            assert "error" not in got, got
            return got
        r = seen = probe()
        assert r["open"] == "work:website" and r["rest"] == 0 and r["inLines"] == 0, ("a click on Website makes it the sun; no input lines at rest", r)
        meets = lambda a, b: a[0] < b[2] - 0.5 and b[0] < a[2] - 0.5 and a[1] < b[3] - 0.5 and b[1] < a[3] - 0.5
        assert not any(meets(a, b) for i, a in enumerate(r["labels"]) for b in r["labels"][i + 1:]), ("labels overlap on the page at rest", r["labels"])
        assert r["fontpx"] >= 11 and r["sw"][0] <= r["sw"][1], ("labels at least 11px, no horizontal scroll", r)
        assert r["look"][0] == 180 and r["look"][1] == 3 and r["look"][2] and r["look"][3] == "10 sections · 12 workflows", ("the sky, three orbits, the sun's count", r["look"])
        assert r["glide"] == [1, "wf", "W-8"], ("a click on W-8 makes it the sun, gliding", r["glide"])
        assert r["w8"][0] == sorted(["sec:work:website:W-7:L", "work:W-2:L", "work:W-3:L", "sec:work:website:W-8:R"]) and r["w8"][1] == 0 and r["w8"][2] == 2 and r["w8"][3] == 0, ("W-8's sun: its reads left, its section right, artifacts only, the path", r["w8"])
        assert r["walk"] == ["work:website", "sec:work:website:W-8", 3, True], ("its section makes Website the sun again, the section focused", r["walk"])
        assert r["esc1"] == ["", "work:website"] and r["esc2"] == "W-8" and r["esc3"] == ["work:website", 1] and r["esc4"] == [False, True], ("Esc: the focus, then one step back each time, then the Map", r)
        assert set(r["spec"][0]) == {"work:W-1"} and r["spec"][1] == ["W-12", "W-6", "W-7"] and r["spec"][2] and r["spec"][3] == ["work:W-1"] and r["far"] > 0, ("Product spec: only its own lines, it glows, the rest fades", r["spec"])
        assert r["anim"] != "none" and r["empty"] == 0, ("the glow pulses; empty space clears the focus", r)
        assert r["zoom"] == "1.5" and r["fit"] == "1" and r["back"] == [False, True], ("zoom and Fit as the Line view; Back returns to the Map", r)
        rm = probe(("--force-prefers-reduced-motion",))
        assert rm["anim"] == "none" and rm["spec"][3] == ["work:W-1"] and rm["glide"] == [0, "wf", "W-8"], ("reduced motion: no glide, the frame stays without pulsing", rm["anim"], rm["glide"])
    print(f"graph map: {teams_n} teams with workflows over {len(names)} runs ({empty_n} with none): no team node, no workflow-workflow edge, columns follow reads and makes, "
          f"sections are artifacts ({loops} read-back loops), {len(unresolved)} unresolved reads, {len(cycles)} cycles; constellations: {arts_n} artifacts, {sec_n} sections, {fix_n} fixes, "
          f"{empty_slots} empty slots, {len(no_out)} workflows with no recorded output {no_out}; every section and every builder and fix once, ring in run order (chat.jsonl); {layout_note}"
          + ("; real page at 1440x900: Website is the sun on a click (sky, orbits, count), no input lines at rest, no label overlaps, 11px, W-8 glides in as the sun (3 reads left, its section right), "
             "its section makes Website the sun again, Esc steps back one each time then the Map, Product spec only its own lines and glows, zoom, Fit, Back, reduced motion" if seen else "") + " ok")


THEME_TEXT = ("ink", "muted", "accent", "ok", "bad", "validator", "warm1", "warm2", "warm3", "identity", "adaptation", "priority", "coordination", "audit", "system",
              "wf0", "wf1", "wf2", "wf3", "wf4", "wf5", "flowin", "flowout", "sec", "bld", "fix", "doc")      # tokens used as words on the page


def theme_tokens(ui):
    """The two token sets of j2_ui.html, var() references resolved: {"dark": {name: "#rrggbb"}, "light": {...}}."""
    dark = dict(re.findall(r"--([\w-]+):([^;}]+)", re.search(r"(?s)\n:root\{color-scheme:dark;(.*?)\n\}", ui).group(1)))
    light = {**dark, **dict(re.findall(r"--([\w-]+):([^;}]+)", re.search(r"(?s):root\[data-theme=light\]\{color-scheme:light;(.*?)\}", ui).group(1)))}
    def res(t, v, k=0):
        m = re.fullmatch(r"var\(--([\w-]+)\)", v.strip())
        return res(t, t[m.group(1)], k + 1) if m and k < 9 else v.strip()
    return {n: {k: res(t, v) for k, v in t.items()} for n, t in (("dark", dark), ("light", light))}


def contrast(a, b):
    lum = lambda h: (lambda c: .2126 * c[0] + .7152 * c[1] + .0722 * c[2])([x / 12.92 if x <= .03928 else ((x + .055) / 1.055) ** 2.4 for x in (int(h[i:i + 2], 16) / 255 for i in (1, 3, 5))])
    x, y = sorted((lum(a), lum(b)))
    return (y + .05) / (x + .05)


def warm_ui():
    """Warm UI: every colour of j2_ui.html is a theme token (no hex, rgb or hsl outside the two token sets, so none in map rendering);
    text tokens keep 4.5:1 and line tokens 3:1 in both sets; the Style guide has no tab of its own. With Chrome (--browser), for every run:
    the Tree, the Line, every team focused and opened, every artifact sun and every workflow sun render in dark and in light with no page error and no colour in the
    markup, with words at least 11px on screen, never cut and never overlapping another node's, the maps' colours follow the theme at once (no reload); Appearance is Light by default and the choice persists across a reload."""
    import html as htmllib
    import threading
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    head = ui.index("\n:root{color-scheme:dark;"), ui.index("}", ui.index(":root[data-theme=light]{")) + 1
    rest = ui[:head[0]] + ui[head[1]:]
    left = re.findall(r"#[0-9a-fA-F]{3,8}\b(?![\w-])|\b(?:rgba?|hsla?)\(", rest)
    assert not left, ("hard-coded colours outside the theme tokens", left[:10])
    T = theme_tokens(ui)
    assert set(T["dark"]) == set(T["light"]) and all(re.fullmatch(r"#[0-9a-f]{6}", T[t][k]) for t in T for k in THEME_TEXT + ("bg", "panel", "panel2", "edge", "spoke", "mapbg", "sky0", "sky1")), "both sets name the same tokens"
    low = []
    for t, v in T.items():
        for k in THEME_TEXT:      # words: 4.5:1 on the page's three surfaces
            low += [(t, k, b, round(contrast(v[k], v[b]), 2)) for b in ("bg", "panel", "panel2") if contrast(v[k], v[b]) < 4.5]
        for k, bs in (("suntext", ("sky0", "sky1")), ("sectext", ("sky0", "sky1")), ("eattext", ("sky0", "sky1", "eatfill")), ("ink", ("sky0", "sky1", "mapbg")), ("muted", ("sky0", "sky1", "mapbg")), ("on", ("accent",))):
            low += [(t, k, b, round(contrast(v[k], v[b]), 2)) for b in bs if contrast(v[k], v[b]) < 4.5]
        for k, bs in (("edge", ("mapbg",)), ("muted", ("panel",)), ("spoke", ("sky0", "sky1")), ("sec", ("sky0", "sky1")), ("fix", ("sky0", "sky1")), ("eat", ("sky0", "sky1")), ("doc", ("sky0", "sky1"))):      # lines: 3:1
            low += [(t, k, b, round(contrast(v[k], v[b]), 2)) for b in bs if contrast(v[k], v[b]) < 3]
        blend = lambda f, b_, a_: "#" + "".join(f"{round(int(f[i:i + 2], 16) * a_ + int(b_[i:i + 2], 16) * (1 - a_)):02x}" for i in (1, 3, 5))
        for k in ("e-reads", "warm1", "warm2"):      # the edges: 3:1 on the sky, at the source end of their gradient too (82%)
            low += [(t, k, b_, a_, round(contrast(blend(v[k], v[b_], a_), v[b_]), 2)) for b_ in ("sky0", "sky1") for a_ in (1, .82) if contrast(blend(v[k], v[b_], a_), v[b_]) < 3]
    assert not low, ("below WCAG AA", low)
    rail = ui[ui.index('<nav class="rail tabs"'):ui.index("</nav>", ui.index('<nav class="rail tabs"'))]
    assert 'data-tab="style"' not in rail and 'data-themepick="system"' in ui, "no Style guide tab; Appearance in Run settings"
    note = "Chrome checks skipped"
    chrome = j2.j2_check.find_chrome()
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    if chrome and BROWSER and names:
        js = ("const errs = []; addEventListener('error', e => errs.push(String(e.message))); const hexy = /(?:fill|stroke|color|background)[=:]\\s*\"?(?:#[0-9a-f]{3}|rgb)/i;"
              " const tok = k => { const d = document.createElement('i'); d.style.color = `var(--${k})`; document.body.appendChild(d); const c = getComputedStyle(d).color; d.remove(); return c; };"
              " const sunTo = p => { Object.assign(CONS, {path: [p], id: p.id, kind: p.kind, focus: '', fan: {}, grp: {}}); paintMap(); };      /* no glide: the drawing as it lands */"
              " let edgesN = 0; const edgeCheck = (th, what, s) => {      /* every edge: the shared style, its arrowhead at the target's border, through no node and no label */"
              "   const off = el => { const m = /translate\\(([-\\d.e]+)[ ,]+([-\\d.e]+)\\)/.exec(el.getAttribute('transform') || ''); return m ? [+m[1], +m[2]] : [0, 0]; }, bb = (el, o) => { const b = el.getBBox(); return [b.x + o[0], b.y + o[1], b.x + b.width + o[0], b.y + b.height + o[1]]; };"
              "   const nodes = {}, quiet = s.classList.contains('quiet'); s.querySelectorAll('.tnodes > .tnode, .cnodes > .cnode, .mapnode').forEach(g => { const o = off(g), sh = [...g.querySelectorAll('.tdot, .ccore, .cdia, .cwf, .cdoc, .cbadge, .shape')].filter(x => x.getClientRects().length).map(x => bb(x, o)); if (!sh.length) return;"
              "     nodes[g.dataset.cid || g.dataset.id] = {round: !!g.querySelector('circle.tdot, .ccore, .cwf, circle.shape, .cbadge'), b: [Math.min(...sh.map(q => q[0])), Math.min(...sh.map(q => q[1])), Math.max(...sh.map(q => q[2])), Math.max(...sh.map(q => q[3]))], t: quiet ? [] : [...g.querySelectorAll('text')].filter(t => t.getClientRects().length && t.textContent.trim()).map(t => bb(t, o))}; });"
              "   const boxes = Object.entries(nodes).flatMap(([id, n]) => [[id, n.b, 'shape'], ...n.t.map(t => [id, t, 'label'])]);"
              "   for (const e of s.querySelectorAll('path[data-from]')){ if (!e.getClientRects().length || !nodes[e.dataset.from] || !nodes[e.dataset.to] || e.dataset.from === e.dataset.to) continue; edgesN++;"
              "     if (!e.dataset.edge || !/^url\\(\"?#ea-/.test(e.getAttribute('marker-end') || '') || !/url\\(\"?#eg-/.test(e.style.stroke) || !/^M[^A-Za-z]+C[^A-Za-z]+$/.test(e.getAttribute('d'))){ bad.push([th, what, 'edge not in the shared style', e.dataset.from, e.dataset.to, e.getAttribute('d').slice(0, 40)]); continue; }"
              "     const L = e.getTotalLength(), end = e.getPointAtLength(L), b = nodes[e.dataset.to].b, dx = Math.max(b[0] - end.x, 0, end.x - b[2]), dy = Math.max(b[1] - end.y, 0, end.y - b[3]), tn = nodes[e.dataset.to], d = tn.round ? Math.hypot(end.x - (b[0] + b[2]) / 2, end.y - (b[1] + b[3]) / 2) - Math.max(b[2] - b[0], b[3] - b[1]) / 2 : Math.hypot(dx, dy);"
              "     if (d < 0.5 || d > 4) bad.push([th, what, 'arrowhead not at the target border', e.dataset.from, e.dataset.to, +d.toFixed(2)]);"
              "     for (let i = 2; i <= 38; i++){ const p = e.getPointAtLength(L * i / 40), h = boxes.find(([, q]) => p.x > q[0] + 1 && p.x < q[2] - 1 && p.y > q[1] + 1 && p.y < q[3] - 1); if (h){ bad.push([th, what, 'an edge through a ' + h[2], e.dataset.from, e.dataset.to, h[0]]); break; } } } };"
              " let small = 99; const views = {dark: 0, light: 0}, bad = [], bgs = {}; showTab('map'); r.first = [document.documentElement.dataset.theme, document.querySelector('[data-themepick=\"light\"]').getAttribute('aria-pressed')];"
              " const look = (th, what, sel, bgk) => { const s = document.querySelector(sel); if (!s){ bad.push([th, what, 'missing']); return; } views[th]++; if (hexy.test(s.outerHTML)) bad.push([th, what, 'colour in markup']);"
              "   const cs = getComputedStyle(s), t = s.querySelector('text'); if (bgk && cs.backgroundColor !== tok(bgk) && !cs.backgroundImage.includes(tok(bgk).slice(0, 12))) bad.push([th, what, 'background', cs.backgroundColor, cs.backgroundImage.slice(0, 80), tok(bgk)]);"
              "   if (t && !getComputedStyle(t).fill) bad.push([th, what, 'no text fill']); (bgs[what.split(' ')[0]] = bgs[what.split(' ')[0]] || {})[th] = cs.backgroundColor + cs.backgroundImage;"
              "   if (!cs.backgroundImage.includes('radial-gradient')) bad.push([th, what, 'no sky']);"
              "   if (th === 'dark') edgeCheck(th, what, s);"
              "   if (what.startsWith('line') || th === 'light') return;      /* the words: at least 11px on screen, never cut, no two nodes' words overlapping (once per view: the layout is the theme's) */"
              "   const groups = [...s.querySelectorAll('.tnode, .cnode')].map(g => [...g.querySelectorAll('text')].filter(x => x.getBoundingClientRect().width > 0 && getComputedStyle(x).display !== 'none' && !s.classList.contains('quiet')));"
              "   for (const ts of groups) for (const x of ts){ const px = parseFloat(getComputedStyle(x).fontSize) * x.getScreenCTM().a; small = Math.min(small, px); if (px < 10.95) bad.push([th, what, 'under 11px', x.textContent, px]); if (x.textContent.includes('…')) bad.push([th, what, 'cut', x.textContent]); }"
              "   const rects = groups.map(ts => ts.map(x => [x.getBoundingClientRect(), x.textContent]));"
              "   for (let i = 0; i < rects.length; i++) for (let j = i + 1; j < rects.length; j++) for (const [a, ta] of rects[i]) for (const [b, tb] of rects[j]) if (a.left < b.right - 1 && b.left < a.right - 1 && a.top < b.bottom - 1 && b.top < a.bottom - 1) bad.push([th, what, 'words overlap', ta, tb, [a.left, a.top, a.right, a.bottom].map(Math.round), [b.left, b.top, b.right, b.bottom].map(Math.round)]); };"
              " for (const run of RUNS){ const m = await (await fetch('/api/map?run=' + encodeURIComponent(run), {cache: 'no-store'})).json(); for (const k of Object.keys(MAP)) delete MAP[k]; Object.assign(MAP, m);"
              "   for (const th of ['light', 'dark']){ document.querySelector(`[data-themepick=\"${th}\"]`).click(); if (document.documentElement.dataset.theme !== th) bad.push([th, run, 'theme not set']);"
              "     consBack(); MAPVIEW = 'tree'; TREE.focus = ''; TREE.zoom = null; paintMap(); look(th, 'tree ' + run, '.treesvg', 'sky1'); MAPVIEW = 'line'; paintMap(); look(th, 'line ' + run, '.mapsvg:not(.consvg)', 'sky1'); MAPVIEW = 'tree';"
              "     for (const sid of Object.keys(mapTree(MAP).stages)){ TREE.focus = sid; TREE.zoom = null; paintMap(); look(th, 'tfocus ' + run + ' ' + sid, '.treesvg', 'sky1'); TREE.focus = ''; TREE.zoom = null;"
              "       sunTo({id: sid, kind: 'team'}); look(th, 'team ' + run + ' ' + sid, '.consvg', 'sky1'); consBack(); }"
              "     for (const a of Object.keys(m.constellations || {})){ sunTo({id: a, kind: 'art'}); look(th, 'sun ' + run + ' ' + a, '.consvg', 'sky1'); }"
              "     for (const w of Object.keys(consIndex(MAP).wf)){ sunTo({id: w, kind: 'wf'}); look(th, 'wfsun ' + run + ' ' + w, '.consvg', 'sky1'); } consBack(); } }"
              " r.views = views; r.small = small; r.edges = edgesN; r.why = {}; bad.forEach(b => { r.why[b[2]] = (r.why[b[2]] || 0) + 1; }); r.kinds = Object.keys(bgs); r.bad = bad.slice(0, 20); r.nbad = bad.length; r.errs = errs; r.flip = Object.entries(bgs).map(([k, v]) => [k, v.dark !== v.light]);"
              " document.querySelector('[data-themepick=\"light\"]').click();"
              " const f = document.createElement('iframe'); f.style.cssText = 'width:900px;height:600px'; document.body.appendChild(f); const loaded = () => new Promise(ok => f.onload = ok);"
              " f.src = location.href; await loaded(); await wait(800); r.reload1 = [f.contentDocument.documentElement.dataset.theme, f.contentDocument.querySelector('[data-themepick=\"light\"]').getAttribute('aria-pressed')];"
              " f.contentDocument.querySelector('[data-themepick=\"system\"]').click(); f.contentWindow.location.reload(); await loaded(); await wait(800);"
              " r.reload2 = [f.contentDocument.documentElement.dataset.theme, f.contentDocument.querySelector('[data-themepick=\"system\"]').getAttribute('aria-pressed'), f.contentWindow.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark'];"
              " f.contentDocument.querySelector('[data-themepick=\"dark\"]').click(); r.stored = localStorage.getItem('j2theme');")
        import shutil
        tmp = tempfile.mkdtemp(prefix="j2-warm-")
        os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
        page = ui.replace("</body>", "<script>if (window === top) setTimeout(async () => { const r = {}, wait = ms => new Promise(f => setTimeout(f, ms)), RUNS = " + json.dumps(names)
                          + "; try { " + js + " } catch (e) { r.error = String(e.stack || e); } document.body.setAttribute('data-r', JSON.stringify(r)); }, 2500)</script></body>")
        open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(page)
        keep_here, keep_runs = j2_server.HERE, j2.RUNS_DIR
        j2_server.HERE, j2.RUNS_DIR = tmp, repo
        srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), j2_server.Handler)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        prof = tempfile.mkdtemp(prefix="j2-warmprof-")
        try:
            dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--user-data-dir={prof}", "--no-first-run", "--window-size=1440,900", "--virtual-time-budget=600000", "--dump-dom",
                              f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={names[0]}&mapview=tree"], capture_output=True, text=True, timeout=590).stdout
        finally:
            srv.shutdown()
            j2_server.HERE, j2.RUNS_DIR = keep_here, keep_runs
            shutil.rmtree(tmp, ignore_errors=True)
            shutil.rmtree(prof, ignore_errors=True)
        hit = re.search(r'data-r="([^"]*)"', dom)
        assert hit, ("the page did not finish its steps", dom[-300:])
        r = json.loads(htmllib.unescape(hit.group(1)))
        assert "error" not in r and not r["errs"], r
        assert r["first"] == ["light", "true"], ("Light by default (the studio's calm look; dark is one click away)", r["first"])
        assert r["nbad"] == 0 and r["views"]["dark"] == r["views"]["light"] > 2 * len(names), ("every map view in both themes, colours from the tokens", r["why"], r["bad"], r["views"])
        assert all(x[1] for x in r["flip"]) and r["kinds"] == ["tree", "line", "tfocus", "team", "sun", "wfsun"], ("each kind of map changes with the theme, no reload", r["flip"], r["kinds"])
        assert r["reload1"] == ["light", "true"] and r["reload2"][0] == r["reload2"][2] and r["reload2"][1] == "true" and r["stored"] == "dark", ("the choice persists across a reload", r)
        note = (f"Chrome at 1440x900: {r['views']['dark']} map views per theme over {len(names)} runs (Tree, Line, every team focused and opened, every artifact and workflow sun), no page error, each on its sky; "
                f"{r['edges']} edges, each one cubic in the shared style with its arrowhead at the target's border, none through a node or a label; "
                f"words at least 11px (smallest {r['small']:.1f}px), never cut, no two nodes' words overlapping; the choice kept across a reload")
    print(f"warm UI: no hard-coded colour outside the two token sets, {len(THEME_TEXT)} text tokens 4.5:1 and the map lines 3:1 in dark and light, no Style guide tab; {note} ok")


def map_motion():
    """Map motion (Chrome, --browser): every node of every view of every run (Tree, Line, every team focused and opened, every artifact and workflow sun) springs
    in and comes to rest within 2px of its slot, in fact exactly on it (the static layout: transforms and lines as drawn); in each a drag (more than 4px) moves
    only that node, its lines in the shared style, it stays where dropped, no click and no focus, Reset enabled and the place saved; Reset brings every node back
    within 1px (exactly), forgets the place and is disabled again, in light (even runs) and dark (odd runs). 174314: the place survives a reload, touch drags,
    hover leans the neighbours in and the rest away, the nodes drift; reduced motion: no drift, a new view and Reset at once, hover moves nothing; in real time
    (no virtual clock) a motion frame takes under 16ms."""
    import html as htmllib
    import shutil
    import subprocess
    import threading
    import time
    import j2_server
    here = os.path.dirname(os.path.abspath(__file__))
    repo = os.path.join(here, "runs")
    names = sorted(n for n in os.listdir(repo) if os.path.isfile(os.path.join(repo, n, "workflows.json"))) if os.path.isdir(repo) else []
    chrome = j2.j2_check.find_chrome()
    run = "j2-20261026-174314"
    if not (chrome and BROWSER and names):
        print("map motion: Chrome checks skipped")
        return
    ui = open(os.path.join(here, "j2_ui.html"), encoding="utf-8").read()
    helpers = ("const wait = ms => new Promise(f => setTimeout(f, ms)), q = s => [...document.querySelectorAll(s)];"
               " const fire = (t, el, x, y) => el.dispatchEvent(new MouseEvent(t, {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));"
               " const away = M => Math.max(0, ...M.nodes.map(n => { const m = /translate\(([-\d.]+),([-\d.]+)\)/.exec(n.el.getAttribute('transform') || ''); const x = M.v.abs ? +m[1] : n.hx + (m ? +m[1] : 0), y = M.v.abs ? +m[2] : n.hy + (m ? +m[2] : 0); return Math.hypot(x - n.hx, y - n.hy); }));"
               " const exact = M => M.nodes.every(n => M.v.abs ? n.el.getAttribute('transform') === 'translate(' + tRd(n.hx) + ',' + tRd(n.hy) + ')' : !n.el.hasAttribute('transform')) && M.edges.every(e => e.el.getAttribute('d') === e.d0);"
               " const land = async M => { for (let i = 0; i < 300 && M.svg.dataset.settled !== '1'; i++) await wait(20); return M.svg.dataset.settled === '1'; };"
               " const sel = () => document.querySelector('.consvg') || document.querySelector('.treesvg:not([hidden])') && MAPVIEW === 'tree' && document.querySelector('.treesvg') || q('.mapsvg').find(x => x.getClientRects().length);")

    def probe(js, flags=(), real=False):
        tmp = tempfile.mkdtemp(prefix="j2-motion-")
        os.symlink(os.path.join(here, "vendor"), os.path.join(tmp, "vendor"))
        got = []

        class H(j2_server.Handler):
            def do_POST(self):
                if self.path == "/__r":
                    got.append(self.rfile.read(int(self.headers["Content-Length"])).decode())
                    self.send_response(204)
                    self.end_headers()
                    return
                return super().do_POST()
        open(os.path.join(tmp, "j2_ui.html"), "w", encoding="utf-8").write(ui.replace("</body>", "<script>if (window === top) setTimeout(async () => { const r = {}; try { " + helpers + js
                                                                                      + " } catch (e) { r.error = String(e.stack || e); } document.body.setAttribute('data-r', JSON.stringify(r)); fetch('/__r', {method: 'POST', body: JSON.stringify(r)}); }, 2500)</script></body>"))
        keep_here, keep_runs = j2_server.HERE, j2.RUNS_DIR
        j2_server.HERE, j2.RUNS_DIR = tmp, repo
        srv = j2_server.http.server.ThreadingHTTPServer(("127.0.0.1", 0), H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        prof = tempfile.mkdtemp(prefix="j2-motionprof-")
        url = f"http://127.0.0.1:{srv.server_address[1]}/?view=detail&run={run}&mapview=tree"
        try:
            if real:      # the real clock: the page posts its result, then Chrome is closed
                p = subprocess.Popen([chrome, "--headless=new", f"--user-data-dir={prof}", "--no-first-run", "--window-size=1440,900", *flags, url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                t0 = time.time()
                while not got and time.time() - t0 < 90:
                    time.sleep(0.2)
                p.kill()
                p.wait()
                out = got[0] if got else None
            else:
                dom = chrome_dom([chrome, "--headless=new", "--disable-gpu", f"--user-data-dir={prof}", "--no-first-run", "--window-size=1440,900", "--virtual-time-budget=900000", *flags, "--dump-dom", url],
                                 capture_output=True, text=True, timeout=590).stdout
                hit = re.search(r'data-r="([^"]*)"', dom)
                out = htmllib.unescape(hit.group(1)) if hit else None
        finally:
            srv.shutdown()
            j2_server.HERE, j2.RUNS_DIR = keep_here, keep_runs
            shutil.rmtree(tmp, ignore_errors=True)
            shutil.rmtree(prof, ignore_errors=True)
        assert out, "the page did not finish its steps"
        r = json.loads(out)
        assert "error" not in r, r
        return r
    # every view of every run: it springs open from the middle and comes to rest on its slots (the frames run here, one after another, to the end)
    every = ("const views = [], bad = []; let drags = 0; showTab('map');"
             " const dragReset = async (svg, what) => { const M = motionOf(svg), n = M.nodes.find(x => M.edges.some(e => e.a === x || e.b === x) && x.el.getClientRects().length) || M.nodes.find(x => x.el.getClientRects().length); if (!n) return;"
             "  const tf0 = M.nodes.map(x => x.el.getAttribute('transform')), st0 = JSON.stringify([CONS.id, CONS.kind, CONS.focus, TREE.focus, MAPPIN, q('.conspanel, .mappanel').length]), btn = () => svg.closest('.consbox, .mapsvgwrap').parentElement.querySelector(':scope > .mapreset'), key = motionKey(svg);"
             "  if (!btn() || !btn().disabled) bad.push([what, 'Reset not disabled at first']); const b = n.el.getBoundingClientRect(), cx = b.left + b.width / 2, cy = b.top + b.height / 2, k = n.el.parentNode.getScreenCTM().a;"
             "  fire('mousedown', n.el, cx, cy); for (let i = 1; i <= 5; i++) fire('mousemove', window, cx + 8 * i, cy + 5 * i); fire('mouseup', window, cx + 40, cy + 25); fire('click', n.el, cx + 40, cy + 25); drags++;"
             "  const want = [40 / k, 25 / k], moved = Math.abs(n.x - n.hx - want[0]) < 1 && Math.abs(n.y - n.hy - want[1]) < 1;"
             "  if (!moved) bad.push([what, n.id, 'not dropped where let go', n.x - n.hx, n.y - n.hy, want]); if (!M.nodes.every((x, i) => x === n || x.el.getAttribute('transform') === tf0[i])) bad.push([what, 'another node moved']);"
             "  if (JSON.stringify([CONS.id, CONS.kind, CONS.focus, TREE.focus, MAPPIN, q('.conspanel, .mappanel').length]) !== st0) bad.push([what, 'the drag clicked or changed the focus']); if (document.activeElement === n.el) bad.push([what, 'the drag focused the node']);"
             "  if (btn().disabled || !localStorage.getItem(key)) bad.push([what, 'not saved or Reset not enabled']); if (M.edges.filter(e => e.a === n || e.b === n).some(e => e.el.getClientRects().length && (!e.el.dataset.edge || !/^M[^A-Za-z]+C[^A-Za-z]+$/.test(e.el.getAttribute('d'))))) bad.push([what, 'an edge left the shared style']);"
             "  await wait(30); btn().click(); await wait(360); if (!M.nodes.every((x, i) => x.el.getAttribute('transform') === tf0[i] && Math.hypot(x.x - x.hx, x.y - x.hy) <= 1) || localStorage.getItem(key) !== null || !btn().disabled) bad.push([what, 'Reset did not bring every node home, forget and disable']); };"
             " const settle = svg => { const M = motionOf(svg); if (!M) return bad.push(['no motion', svg.getAttribute('class')]); motionFrom(svg, null, null);"
             "  let i = 0; while (M.svg.dataset.settled !== '1' && i++ < 500) motionTick(M); views.push(i); const a = away(M); if (a > 2 || !exact(M)) bad.push([svg.dataset.cons || svg.getAttribute('class'), a, exact(M)]); return svg; };"
             " const sunTo = async p => { Object.assign(CONS, {path: [p], id: p.id, kind: p.kind, focus: '', fan: {}, grp: {}}); paintMap(); await dragReset(settle(document.querySelector('.consvg')), p.kind + ' ' + p.id); };"
             " for (const [ri, run] of RUNS.entries()){ viewRun = run; document.querySelector(`[data-themepick=\"${ri % 2 ? 'dark' : 'light'}\"]`).click(); const m = await (await fetch('/api/map?run=' + encodeURIComponent(run), {cache: 'no-store'})).json(); for (const k of Object.keys(MAP)) delete MAP[k]; Object.assign(MAP, m);"
             "  consBack(); MAPVIEW = 'tree'; TREE.focus = ''; TREE.zoom = null; paintMap(); await dragReset(settle(document.querySelector('.treesvg')), 'tree ' + run); MAPVIEW = 'line'; paintMap(); for (const x of q('.mapsvg:not(.consvg)').filter(x => x.getClientRects().length)) await dragReset(settle(x), 'line ' + run); MAPVIEW = 'tree';"
             "  for (const sid of Object.keys(mapTree(MAP).stages)){ TREE.focus = sid; TREE.zoom = null; paintMap(); await dragReset(settle(document.querySelector('.treesvg')), 'tfocus ' + sid); TREE.focus = ''; await sunTo({id: sid, kind: 'team'}); consBack(); }"
             "  for (const a of Object.keys(m.constellations || {})) await sunTo({id: a, kind: 'art'}); for (const w of Object.keys(consIndex(MAP).wf)) await sunTo({id: w, kind: 'wf'}); consBack(); }"
             " r.views = views.length; r.drags = drags; r.frames = Math.max(...views); r.bad = bad.slice(0, 10); r.nbad = bad.length;")
    r = probe("const RUNS = " + json.dumps(names) + "; " + every)
    assert r["nbad"] == 0 and r["views"] > 2 * len(names) and r["drags"] == r["views"], ("every view comes to rest exactly on its slots; a drag pins one node, Reset brings all home", r["bad"], r["views"], r["drags"])
    settled = r
    # 174314 on the real page: drag and release in the Tree, the Line, a team and a sun; hover; the drift
    js = ("showTab('map'); const out = {};"
          " MAPVIEW = 'tree'; paintMap(); let M = motionOf(document.querySelector('.treesvg')); "
          " const k = Object.keys(mapTree(MAP).stages).find(x => mapTree(MAP).stages[x].label === 'Web Developer'); treeFocusTeam(k); M = document.querySelector('.treesvg').__m; out.focusMoving = M.svg.classList.contains('tmoving'); out.focus = [await land(M), away(M), exact(M)];"
          " treeOpen(k); M = document.querySelector('.consvg').__m; out.teamOpen = [M.svg.classList.contains('cmoving'), await land(M), exact(M)];"
          " consGo([{id: 'work:website', kind: 'art'}]); M = document.querySelector('.consvg').__m; out.sunOpen = [await land(M), exact(M)];"
          " const n = M.nodes.find(x => x.id === 'W-8'), nb = M.nodes.find(x => x.id === 'sec:work:website:W-8'), far = M.nodes.find(x => x.id === 'W-13'); fire('mouseover', n.el, 0, 0); await wait(400);"
          " const lean = (a, b) => Math.hypot(b.hx - a.hx, b.hy - a.hy) - Math.hypot(b.hx - a.x, b.hy - a.y); out.hover = [lean(nb, n) > 2, lean(far, n) < -1, Math.round(Math.hypot(n.x - n.hx, n.y - n.hy))]; fire('mouseout', n.el, 0, 0); out.unhover = [await land(M), exact(M)];"
          " out.drift = getComputedStyle(n.el).animationName; consBack(); MAPVIEW = 'line'; paintMap();"
          " Object.assign(r, out);")
    t = probe(js)
    # 174314: a dropped place survives a reload (the page again, same viewer), Reset forgets it across a reload too; a touch drags as the mouse does
    rl = probe("showTab('map'); const f = document.createElement('iframe'); f.style.cssText = 'position:fixed;left:0;top:0;width:1440px;height:900px'; document.body.appendChild(f);"
               " const loaded = () => new Promise(ok => f.onload = ok), W = () => f.contentWindow, sun = async () => { W().showTab('map'); W().eval(\"consOpen('work:website')\"); await wait(1200); return W().document.querySelector('.consvg').__m; };"
               " f.src = location.href; await loaded(); await wait(2600); let M = await sun(), n = M.nodes.find(x => x.id === 'W-8'), b = n.el.getBoundingClientRect(), k = n.el.parentNode.getScreenCTM().a;"
               " const F = (t, el, x, y) => el.dispatchEvent(new (W().MouseEvent)(t, {bubbles: true, cancelable: true, view: W(), clientX: x, clientY: y, button: 0}));"
               " F('mousedown', n.el, b.left + 5, b.top + 5); for (let i = 1; i <= 5; i++) F('mousemove', W(), b.left + 5 - 12 * i, b.top + 5 - 8 * i); F('mouseup', W(), b.left - 55, b.top - 35); const at = [n.x, n.y]; await wait(30);"
               " W().location.reload(); await loaded(); await wait(2600); M = await sun(); n = M.nodes.find(x => x.id === 'W-8'); r.kept = [Math.abs(n.x - at[0]) < 0.2 && Math.abs(n.y - at[1]) < 0.2, Math.round(n.x - n.hx), Math.round(n.y - n.hy), !W().document.querySelector('.mapreset').disabled];"
               " W().document.querySelector('.mapreset').click(); await wait(400); W().location.reload(); await loaded(); await wait(2600); M = await sun(); r.reset = [M.nodes.every(x => x.x === x.hx && x.y === x.hy), W().document.querySelector('.mapreset').disabled];"
               " const t = M.nodes.find(x => x.id === 'W-9'), tb = t.el.getBoundingClientRect(), T = (x, y) => new (W().Touch)({identifier: 7, target: t.el, clientX: x, clientY: y});"
               " const touch = (type, x, y) => t.el.dispatchEvent(new (W().TouchEvent)(type, {bubbles: true, cancelable: true, touches: type === 'touchend' ? [] : [T(x, y)], targetTouches: type === 'touchend' ? [] : [T(x, y)], changedTouches: [T(x, y)]}));"
               " touch('touchstart', tb.left + 5, tb.top + 5); for (let i = 1; i <= 5; i++) touch('touchmove', tb.left + 5 + 10 * i, tb.top + 5 + 6 * i); touch('touchend', tb.left + 55, tb.top + 35);"
               " r.touch = [Math.round((t.x - t.hx) * t.el.parentNode.getScreenCTM().a), Math.round((t.y - t.hy) * t.el.parentNode.getScreenCTM().a), !W().document.querySelector('.mapreset').disabled];")
    assert rl["kept"][0] and rl["kept"][1] < -40 and rl["kept"][3] and rl["reset"] == [True, True], ("a dropped place survives a reload; Reset forgets it across one too", rl)
    assert rl["touch"] == [50, 30, True], ("a one-finger drag moves the node too", rl["touch"])
    assert t["focusMoving"] and t["focus"] == [True, 0, True] and t["teamOpen"] == [True, True, True] and t["sunOpen"] == [True, True], ("a new view or focus springs in and lands on its slots", t)
    assert t["hover"][:2] == [True, True] and t["hover"][2] == 0 and t["unhover"] == [True, True] and t["drift"] == "mdrift", ("hover: the neighbours lean in, the rest ease away, all go back; the nodes drift", t["hover"], t["unhover"], t["drift"])
    # deep links: from a workflow's sun to its Workflows row, from a section's focus to its Artifacts row (its fold opened); Back returns to the same view and focus
    dl = probe("showTab('map'); const vis = el => !!el && el.getClientRects().length > 0, inview = el => { const b = el.getBoundingClientRect(); return b.top >= 0 && b.bottom <= innerHeight; };"
               " const k = Object.keys(mapTree(MAP).stages).find(x => mapTree(MAP).stages[x].label === 'Web Developer'); consGo([{id: k, kind: 'team'}, {id: 'W-8', kind: 'wf'}]); await wait(200);"
               " document.querySelector('[data-openwf]').click(); await wait(400); const row = document.querySelector('#pane-workflows .dlhit');"
               " r.wf = [vis(document.getElementById('pane-workflows')), row ? row.dataset.wfrow : '', row ? inview(row) : false, document.querySelectorAll('.dlhit').length];"
               " document.getElementById('backmap').click(); await wait(300); r.wfBack = [vis(document.getElementById('pane-map')), CONS.kind, CONS.id, CONS.path.length, !!document.querySelector('.consvg[data-kind=wf]')];"
               " consGo([{id: 'work:website', kind: 'art'}], 'sec:work:website:W-8'); await wait(200); document.querySelector('.conspanel [data-openart]').click(); await wait(800);"
               " const a = document.querySelector('#pane-artifacts .dlhit'); r.art = [vis(document.getElementById('pane-artifacts')), a ? a.dataset.sec : '', a ? inview(a) : false, a ? [...(function* (){ let d = a.closest('details'); while (d){ yield d.open; d = d.parentElement.closest('details'); } })()].every(Boolean) : false];"
               " r.artNoBack = document.getElementById('backmap').hidden; showTab('map'); await wait(300); r.artBack = [vis(document.getElementById('pane-map')), CONS.kind, CONS.id, CONS.focus, !!document.querySelector('.consvg.focusing')];")
    assert dl["wf"] == [True, "W-8", True, 1] and dl["wfBack"] == [True, "wf", "W-8", 2, True], ("Open in Workflows: W-8's row, lit and in view; Back to the same sun", dl)
    assert dl["art"] == [True, "work:website|W-8", True, True] and dl["artNoBack"] is True and dl["artBack"] == [True, "art", "work:website", "sec:work:website:W-8", True], ("Open in Artifacts: the section's row, lit and in view (Artifacts has no Back to map); the Map keeps the same focus", dl)
    # reduced motion: no drift, a new view at once, hover moves nothing
    rm = probe("showTab('map'); MAPVIEW = 'tree'; paintMap(); const k = Object.keys(mapTree(MAP).stages)[0]; treeFocusTeam(k); let M = document.querySelector('.treesvg').__m; r.focus = [M.svg.dataset.settled, M.svg.classList.contains('tmoving'), exact(M)];"
               " consOpen('work:website'); M = document.querySelector('.consvg').__m; r.sun = [M.svg.dataset.settled, exact(M)]; const n = M.nodes.find(x => x.id === 'W-8'); fire('mouseover', n.el, 0, 0); await wait(300);"
               " r.hover = M.nodes.filter(x => Math.hypot(x.x - x.hx, x.y - x.hy) > 0.01).length; r.drift = getComputedStyle(n.el).animationName;"
               " const b = n.el.getBoundingClientRect(); fire('mousedown', n.el, b.left + 5, b.top + 5); for (let i = 1; i <= 5; i++) fire('mousemove', window, b.left + 5 + 9 * i, b.top + 5); fire('mouseup', window, b.left + 50, b.top + 5); await wait(30);"
               " r.dropped = Math.round(n.x - n.hx) > 0; document.querySelector('.mapreset').click(); r.resetNow = [M.nodes.every(x => x.x === x.hx && x.y === x.hy), M.svg.dataset.settled];", ("--force-prefers-reduced-motion",))
    assert rm["focus"] == ["1", False, True] and rm["sun"] == ["1", True] and rm["hover"] == 0 and rm["drift"] == "none" and rm["dropped"] and rm["resetNow"] == [True, "1"], ("reduced motion: no drift, no overshoot, Reset at once", rm)
    # frame time, on the real clock: the motion's own work each frame, and the display's frames while it moves
    ft = probe("showTab('map'); MAPVIEW = 'tree'; paintMap(); await wait(300); MOTION.frames.length = 0; const raf = []; let last = performance.now(), on = true; const loop = now => { raf.push(now - last); last = now; if (on) requestAnimationFrame(loop); }; requestAnimationFrame(loop);"
               " const k = Object.keys(mapTree(MAP).stages).find(x => mapTree(MAP).stages[x].label === 'Web Developer'); treeFocusTeam(k); await wait(900); consOpen('work:website'); await wait(900);"
               " const M = document.querySelector('.consvg').__m, n = M.nodes.find(x => x.id === 'W-8'), b = n.el.getBoundingClientRect(); fire('mousedown', n.el, b.left + 5, b.top + 5); raf.length = 0;"
               " for (let i = 1; i <= 20; i++){ fire('mousemove', window, b.left + 5 + 6 * i, b.top + 5 + 4 * i); await wait(16); } fire('mouseup', window, b.left + 125, b.top + 85); await wait(900); on = false;"
               " const f = MOTION.frames, rr = raf.slice(1).sort((a, c) => a - c); r.work = [f.length, Math.max(...f), f.reduce((a, c) => a + c, 0) / f.length]; r.raf = [rr.length, rr[Math.floor(rr.length / 2)]];", real=True)
    assert ft["work"][0] > 30 and ft["work"][1] < 16 and ft["raf"][1] < 17.5, ("a motion frame under 16ms on 174314", ft)
    print(f"map motion: {settled['views']} views over {len(names)} runs spring open and rest exactly on their slots (within 2px; at most {settled['frames']} frames); in each a node dragged "
          f"({settled['drags']}) moves alone, stays where dropped, no click or focus, its place saved, and Reset brings every node home exactly, forgets it and disables itself (light and dark); "
          f"174314: the place survives a reload, a touch drags, hover leans the neighbours in and the rest away, the nodes drift; deep links land and Back returns; reduced motion: none of it, Reset "
          f"at once; real clock: motion work at most {ft['work'][1]:.1f}ms a frame (mean {ft['work'][2]:.2f}ms), display frames {ft['raf'][1]:.1f}ms (median) ok")


def map_every_workflow():
    """Map: every workflow in workflows.json is on the map (by stage, then section, then output refs) or listed by id under
    not recorded; a realization run's specs are deliverables with their stage's role and "given to" lines to the build
    workflows that read them; a workflow set to done whose atom did not pass shows "done · checks did not pass" (amber),
    counted in the team label; the style guide is a small deliverable."""
    import j2_map as M
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runs")      # read-only: building a map never writes to a run
    runs = [os.path.join(repo, n) for n in sorted(os.listdir(repo)) if n.startswith("j2-")] if os.path.isdir(repo) else []
    seen = 0
    for d in runs:
        wfs = j2._read(d, "workflows.json", None)
        if not isinstance(wfs, list):
            continue
        m = M.build(d)
        on = {x for n in m["nodes"] for x in n.get("workflows") or []}
        listed = {x for t in m["not_recorded"] if t.startswith("workflows not placed on the map: ") for x in t.split(": ", 1)[1].split(", ")}
        miss = [w["id"] for w in wfs if w["id"] not in on | listed]
        assert not miss, (d, miss)
        assert not on & listed, (d, on & listed)
        seen += 1
    r = os.path.join(repo, "j2-20261026-155610")
    if not os.path.isdir(r):
        print(f"map: every workflow placed or listed in {seen} saved runs (run 155610 not here: its checks skipped) ok")
        return
    m = M.build(r)
    by = {n["id"]: n for n in m["nodes"]}
    work = [n["id"] for n in m["nodes"] if n["kind"] == "work" and n["lane"] == "trunk"]
    assert work == ["work:charter", "work:W-1", "work:W-2", "work:W-3", "work:style", "work:website"], work      # Charter -> specs -> style guide -> Website
    assert [(by[k]["label"], by[k].get("output"), by[k]["file"], by[k]["status"]) for k in work[1:4]] == [("Product spec", "Product plan", "artifacts/product-spec.md", "filed"),
        ("Design guide", "Design guide", "artifacts/design-guide.md", "filed"), ("Architecture", "Architecture (HLD + LLD)", "artifacts/architecture.md", "filed")]
    assert [by[f"step:{a}>{b}"]["team"] for a, b in (("charter", "W-1"), ("W-1", "W-2"), ("charter", "W-3"), ("W-3", "style"), ("style", "website"))] == \
        ["Product Manager", "Design Lead", "Solution Architect", "Web Developer", "Web Developer"]      # the architecture reads the product spec, not the design guide
    given = {(e["from"], e["to"]): e["label"] for e in m["edges"] if e["kind"] in ("step", "handoff") and e["from"].startswith("work:")}      # a read: artifact -> the team that read it
    assert given[("work:W-1", "step:W-1>W-2")] == "read by W-2" and given[("work:W-1", "step:charter>W-3")] == "read by W-3" and not any(a == "work:W-2" and b == "step:charter>W-3" for a, b in given), given
    assert given[("work:style", "step:style>website")].startswith("read by W-5, ") and not any(a == "work:website" for a, _ in given), "the style guide feeds the site's team"
    site, step = by["work:website"], by["step:style>website"]
    assert {"W-7", "W-9"} <= set(site["workflows"]) and site["status"] == "done_unchecked" and step["unchecked"] == ["W-7", "W-9"], (site, step)
    assert step["detail"].endswith("· 2 done, checks did not pass (W-7, W-9)"), step["detail"]
    assert (by["work:style"]["file"], by["work:style"]["workflows"], by["work:style"]["lane"]) == ("style.json", ["W-4"], "trunk")
    keep_dir, j2.RUNS_DIR = j2.RUNS_DIR, repo
    try:
        out = render_node(j2.saved_snapshot("j2-20261026-155610", 0), docs={"docs": {}, "map": m})["map"]
    finally:
        j2.RUNS_DIR = keep_dir
    wide = out[out.index('<svg class="mapsvg"'):out.index("</svg>")]
    assert all(t in wide for t in ("Product Manager", "Design Lead", "Solution Architect", "Web Developer</tspan> · 14 workflows · 2 done, checks did not pass")), wide[:400]
    assert 'stroke="var(--validator)" stroke-width="4" stroke-dasharray="2 3"' in wide and "done · checks did not pass" in out, "amber and dotted, never colour alone"
    print(f"map: every workflow placed or listed in {seen} saved runs; run 155610 Charter -> three specs (Product Manager, Design Lead, "
          "Solution Architect) -> Website, given-to lines, W-7 and W-9 done · checks did not pass (amber), style guide ok")


def map_tab():
    """Map v1 (map/1): map.json written beside atoms.json (additive, after the summary and again after the report), the
    same map from a rebuilt folder, an old run, a live run, /api/map, the SVG for every status (never colour alone), the
    card list for small screens, plain words, and (with Chrome) no sideways scroll at 500px."""
    import copy
    import shutil
    import threading
    import urllib.error
    import urllib.request
    import collections
    import html as htmllib
    import j2_map as M
    import j2_server
    run = docs_run(DESIGN_BRIEF, 900)
    name = os.path.basename(run.dir)
    saved = json.load(open(os.path.join(run.dir, "map.json")))
    atoms = json.load(open(os.path.join(run.dir, "atoms.json")))["atoms"]
    assert os.path.exists(os.path.join(run.dir, "atoms.json")) and saved["schema"] == "map/1" and saved["run"] == name and not saved["live"]
    # golden structure: the Requester, then the work in an order where each box follows what it reads, a team (step) before each box.
    # A step's id names the box before it only when the box reads it (else the Charter): the style guide reads the HLD, not the LLD.
    assert [n["id"] for n in saved["nodes"]] == ["person:requester", "fn:identity", "fn:adaptation", "fn:priority", "fn:coordination", "fn:audit", "work:charter", "step:charter>prd", "work:prd", "step:prd>hld",
        "work:hld", "step:hld>lld", "work:lld", "step:charter>style", "work:style", "step:style>website", "work:website"], [n["id"] for n in saved["nodes"]]
    assert [(n["kind"], n["row"]) for n in saved["nodes"]] == [("person", "people")] + [("function", "functions")] * 5 + [(k, "work") for k in
        ("work", "engine", "work", "engine", "work", "engine", "work", "engine", "work", "engine", "work")]
    by = {n["id"]: n for n in saved["nodes"]}
    assert [by[f"work:{k}"]["status"] for k in ("charter", "prd", "hld", "lld", "website")] == ["filed"] * 5
    assert [by[f"work:{k}"]["label"] for k in ("prd", "hld", "lld", "website")] == ["Product requirements", "High-level design", "Low-level design", "Website"]
    assert [by[f"work:{k}"]["tag"] for k in ("prd", "hld", "lld", "website")] == ["PRD", "HLD", "LLD", "Site"]
    assert [by[f"work:{k}"]["color"] for k in ("prd", "hld", "lld", "website")] == ["--prd", "--hld", "--lld", "--site"]
    rows = {r["type"]: r for r in json.load(open(os.path.join(run.dir, "artifacts.json")))["rows"]}
    for k in ("prd", "hld", "lld", "website"):      # versions and files come from artifacts.json, never invented
        assert by[f"work:{k}"]["version"] == rows[k]["version"] and by[f"work:{k}"]["file"] == rows[k]["file"], k
    assert by["work:charter"]["version"] is None and by["work:charter"]["file"] == "goal.json"
    assert [by[f"step:{a}>{b}"]["label"] for a, b in (("charter", "prd"), ("prd", "hld"), ("hld", "lld"), ("style", "website"))] == ["Write", "Write", "Write", "Build"]
    for k, step in (("prd", "charter>prd"), ("hld", "prd>hld"), ("lld", "hld>lld"), ("website", "style>website")):      # counts equal the atoms
        mine = [a for a in atoms if a["workflow"] in rows[k]["workflows"]]
        ok = sum(1 for a in mine for x in a["verification"] if x["met"] is True)
        tot = sum(1 for a in mine for x in a["verification"] if x["met"] is not None)
        assert by[f"step:{step}"]["detail"] == f"{len(rows[k]['workflows'])} workflows · {ok} of {tot} checks passed", (k, by[f"step:{step}"]["detail"])
    # every read is drawn from the artifact to the team that read it (never artifact to artifact), recorded reads only, producer -> consumer; the
    # box just before a team on the trunk is a straight step line, every other read a hand-off line
    assert {(e["from"], e["to"], e["basis"]) for e in saved["edges"] if e["kind"] == "handoff"} == {
        ("work:prd", "step:hld>lld", "recorded"), ("work:hld", "step:charter>style", "recorded"), ("work:hld", "step:style>website", "recorded"),
        ("work:lld", "step:style>website", "recorded")}
    assert not [e for e in saved["edges"] if e["kind"] in ("step", "handoff") and e["from"].startswith("work:") and e["to"].startswith("work:")], "no artifact -> artifact line"
    assert all(e.get("source") for e in saved["edges"]), "every line carries its record"
    assert sum(1 for e in saved["edges"] if e["kind"] == "step") == 1 + 3 + 5      # the Charter into the one team that reads nothing else, 3 reads of the box before, each team into its box
    assert [e["to"] for e in saved["edges"] if e["from"] == "work:charter" and e["kind"] == "step"] == ["step:charter>prd"], "the Charter is not drawn to a team that reads something else"
    assert by["work:charter"]["note"] == "Every team reads the charter."
    ck = [x for a in atoms for x in a["verification"] if x["met"] is not None]
    assert saved["status"] == {"state": "Done", "state_status": "idle", "checks": {"passed": sum(x["met"] is True for x in ck), "run": len(ck)}}
    assert "version of Charter" in saved["not_recorded"] and "which other function worked on Website (only Audit is recorded)" in saved["not_recorded"] and \
        any("Knows row" in x for x in saved["not_recorded"]) and not any("Functions row" in x for x in saved["not_recorded"]) and \
        not any(n["kind"] == "know" for n in saved["nodes"]) and "messages to and from workflow agents (W-n) are not drawn" in saved["not_recorded"]
    assert [l["key"] for l in saved["legend"] if not l["drawn"]] == []
    assert saved == M.build(run.dir), "map.json is what the folder builds"
    # the Functions row, golden: calls, seconds and tokens per function from calls.jsonl; a finished run is never "running"
    calls = [json.loads(x) for x in open(os.path.join(run.dir, "calls.jsonl"), encoding="utf-8")]
    chat = [json.loads(x) for x in open(os.path.join(run.dir, "chat.jsonl"), encoding="utf-8")]
    fnn = [n for n in saved["nodes"] if n["kind"] == "function"]
    assert [(n["label"], n["tab"], n["color"]) for n in fnn] == [("Identity", "charter", "--identity"), ("Adaptation", "workflows", "--adaptation"),
        ("Priority", "conflicts", "--priority"), ("Coordination", "timeline", "--coordination"), ("Audit", "audit", "--audit")]
    for n in fnn:
        fid, mine = n["id"][3:], [c for c in calls if c["fn"] == n["id"][3:]]
        said = [m for m in chat if m.get("who") == fid]
        assert n["calls"] == len(mine) and n["seconds"] == round(sum(c["seconds"] or 0 for c in mine), 1) and n["tokens"] == {
            "input": sum((c["tokens"] or {}).get("input", 0) for c in mine), "output": sum((c["tokens"] or {}).get("output", 0) for c in mine)}, n["id"]
        assert n["status"] == "idle" and n["detail"] == "last seen: " + said[-1]["text"][:140], n["id"]
    assert not any(n["status"] in ("running", "waiting") for n in fnn) and "running" not in json.dumps([n["status"] for n in saved["nodes"] if n["row"] != "work"])
    ud = [(e["from"], e["to"], e["n"]) for e in saved["edges"] if e["kind"] == "speaks_to" and not e["to"].startswith("work:")]      # speaks to: counts from the chat
    want = collections.Counter((m["who"], m["next"]) for m in chat if m.get("who") in ("identity", "adaptation", "priority", "coordination", "audit")
                               and m.get("next") in ("identity", "adaptation", "priority", "coordination", "audit") and m["who"] != m["next"])
    assert ud[:2] == [("person:requester", "fn:identity", sum(1 for m in chat if m.get("who") == "user")),
                      ("fn:identity", "person:requester", sum(1 for m in chat if m.get("who") == "identity" and m.get("to_user")))]
    assert {(a[3:], b[3:]): c for a, b, c in ud[2:]} == dict(want) and all(a.startswith("fn:") for a, _, _ in ud[2:])
    docs_rec = json.load(open(os.path.join(run.dir, "documents.json")))      # who made each step: only where documents.json has the call range
    for k, step in (("prd", "charter>prd"), ("hld", "prd>hld"), ("lld", "hld>lld")):
        rng, st = docs_rec[k]["calls"], next(n for n in saved["nodes"] if n["id"] == f"step:{step}")
        per = {f: sum(1 for c in calls if c["fn"] == f and rng["from"] <= c["id"] <= rng["to"]) for f in ("identity", "adaptation", "priority", "coordination", "audit")}
        assert st["made_by"] == {"calls": rng, "functions": {f: n for f, n in per.items() if n}, "basis": "recorded"}, step
        assert {(e["from"][3:], e["n"], e["label"]) for e in saved["edges"] if e["kind"] == "speaks_to" and e["to"] == f"work:{k}"} == {(f, n, "calls") for f, n in per.items() if n}
    assert next(n for n in saved["nodes"] if n["id"] == "step:style>website")["made_by"] is None      # the site: not recorded, never guessed
    # function to work, golden: recorded data only. Identity to the Charter; each function to a document by its calls in the recorded range;
    # the site and a deed get only Audit (its audits in stage-*.json); nothing is a "made" edge any more
    lines = [(e["from"][3:], e["to"][5:], e["n"], e["label"], e["basis"]) for e in saved["edges"] if e["kind"] == "speaks_to" and e["to"].startswith("work:")]
    stage_web = json.load(open(os.path.join(run.dir, "stage-website.json")))
    exp = [("identity", "charter", None, "wrote the charter", "recorded")]
    for k in ("prd", "hld", "lld"):
        rng = docs_rec[k]["calls"]
        exp += [(f, k, by_fn(f, rng, calls), "calls", "recorded") for f in ("identity", "adaptation", "priority", "coordination", "audit") if by_fn(f, rng, calls)]
    exp += [("audit", "website", len(stage_web["audits"]), "audits", "recorded")]
    assert lines == exp, (lines, exp)
    assert not any(e["kind"] == "made" for e in saved["edges"]) and not [e for e in saved["edges"] if e["kind"] == "speaks_to" and e["to"].startswith("step:")]
    assert not [x for x in lines if x[1] == "website" and x[0] != "audit"], "the site gets only the Audit line"
    for k in ("prd", "hld", "lld"):      # every document with an audit in its stage file has an Audit line
        assert json.load(open(os.path.join(run.dir, f"stage-{k}.json")))["audits"] and any(x[0] == "audit" and x[1] == k for x in lines)
    assert by["person:requester"]["detail"] == "1 message from you" and by["person:requester"]["status"] == "idle"
    # a plain website run has the Charter and the site only; a PRD-only run has no site
    plain = docs_run(BREW_LAB, 200)
    assert [n["id"] for n in json.load(open(os.path.join(plain.dir, "map.json")))["nodes"]] == ["person:requester", "fn:identity", "fn:adaptation", "fn:priority", "fn:coordination", "fn:audit", "work:charter", "step:charter>style", "work:style", "step:style>website", "work:website"]
    # an old run: no artifacts.json, atoms.json or map.json; the same boxes, and the gaps are named
